namespace IsekaiMod.Localization {
  internal static class KoreanTranslationData {
    internal static void Register() {
      KoreanLocalization.Add("714b99be4cc74d8ea02500d4c7cffa4e", "Isekai Protagonist", "이세계 주인공", false);
      KoreanLocalization.Add("f60e8e23e4ad4e6e8236ab756d9090c6", "You gain immunity to Acid.", "산성에 면역이 됩니다.", true);
      KoreanLocalization.Add("18cba3f715a748bd9cfa596e2928dedf", "Acid Immunity", "산성 면역", false);
      KoreanLocalization.Add("efc15fc2c3074831b70d2b828f627209", "Administrator D is a playful, self-proclaimed \"Ultimate evil god\" that does things simply for entertainment. She is sadistic and enjoys watching the protagonist struggle for survival in the new world for her own amusement.\nDomains: Chaos, Evil, Knowledge, Death, Destruction\nFavoured Weapon: Scythe", "관리자 D는 스스로를 \"궁극의 악신\"이라 부르며, 순전히 재미를 위해 움직이는 장난기 많은 신입니다. 가학적인 성격으로, 주인공이 낯선 세계에서 살아남으려 발버둥 치는 모습을 즐겨 구경합니다.\n영역: 혼돈, 악, 지식, 죽음, 파괴\n선호 무기: 대낫", true);
      KoreanLocalization.Add("f52d634132954652a405140d6676d417", "Administrator D", "관리자 D", false);
      KoreanLocalization.Add("c0f8abb6d3824580a65507e9d2b6a692", "Gain the spells of an Aeon.", "에온의 주문을 얻습니다.", true);
      KoreanLocalization.Add("5b1828a981c345e385ac23a100f3d015", "Mythic Aeon Spells", "신화 에온 주문", false);
      KoreanLocalization.Add("02fb5d2ee5244f639393a199eedff6d5", "At 8th level, your movements are so fast that they leave an afterimage for your enemies.\nYou gain a +10 {g|Encyclopedia:Bonus}bonus{/g} to your {g|Encyclopedia:Speed}speed{/g} and any {g|Encyclopedia:Attack}attack{/g} targeting you has a 10% chance to miss.", "8레벨에 당신의 움직임은 적의 눈에 잔상을 남길 만큼 빨라집니다.\n{g|Encyclopedia:Speed}이동 속도{/g}에 +10 {g|Encyclopedia:Bonus}보너스{/g}를 받고, 당신을 대상으로 하는 모든 {g|Encyclopedia:Attack}공격{/g}은 10% 확률로 빗나갑니다.", true);
      KoreanLocalization.Add("1592a95ba5a34d5fa442642da9fd31e0", "Afterimage", "잔상", false);
      KoreanLocalization.Add("14068033d7294f638b202e954251cb12", "You have become an alpha. Your critical threats are automatically confirmed.", "당신은 최강자의 반열에 올랐습니다. 치명타 위협을 가하면 자동으로 치명타가 확정됩니다.", true);
      KoreanLocalization.Add("507e69d5f2464c22b2972f426d0b9688", "Alpha Strike", "알파 스트라이크", false);
      KoreanLocalization.Add("c328f9efb4ab48029bd7531630696f9f", "Gain the spells of an Angel.", "엔젤의 주문을 얻습니다.", true);
      KoreanLocalization.Add("880ba75b6813475eb9e9bff3e1ac9468", "Mythic Angel Spells", "신화 엔젤 주문", false);
      KoreanLocalization.Add("2441e6cd5ed440d2a8f483f1abbe98b6", "You release a powerful stroke of energy that deals {g|Encyclopedia:Dice}2d6{/g} points of holy {g|Encyclopedia:Damage}damage{/g} per character level. The target needs to make a successful Reflex saving throw, or become prone.\nIf the target is evil, the {g|Encyclopedia:Spell}spell{/g} instead deals 2d8 points of holy {g|Encyclopedia:Energy_Damage}damage{/g} per character level. The target needs to make a successful Reflex saving throw, or become prone and suffer a -2 {g|Encyclopedia:Penalty}penalty{/g} to {g|Encyclopedia:Armor_Class}AC{/g}, {g|Encyclopedia:Attack}attack rolls{/g} and saving throws.\nIf the target is an evil outsider or an undead creature, the spell instead deals 2d10 points of holy damage per character level. The target needs to make a successful Reflex saving throw, or become prone and suffer a -4 penalty to AC, attack rolls and saving throws.\nIf the target is a demon lord, an evil dragon or a lord of undead (a powerful undead creature like liches, undead dragons, nightshades and similar), the spell instead deals 2d12 points of holy damage per character level. The target suffers a -4 penalty to AC, attack rolls and saving throws. It also needs to make a successful Reflex saving throw, or become prone.", "강력한 에너지를 방출하여 캐릭터 레벨당 {g|Encyclopedia:Dice}2d6{/g}의 성스러운 {g|Encyclopedia:Damage}피해{/g}를 입힙니다. 대상은 반사 내성에 실패하면 넘어집니다.\n대상이 악 성향이면, 이 {g|Encyclopedia:Spell}주문{/g}은 대신 캐릭터 레벨당 2d8의 성스러운 {g|Encyclopedia:Energy_Damage}피해{/g}를 입힙니다. 대상은 반사 내성에 실패하면 넘어지고, {g|Encyclopedia:Armor_Class}방어도{/g}와 {g|Encyclopedia:Attack}명중 굴림{/g}, 내성 굴림에 -2 {g|Encyclopedia:Penalty}불이익{/g}을 받습니다.\n대상이 악 성향 외차원체나 언데드라면, 이 주문은 대신 캐릭터 레벨당 2d10의 성스러운 피해를 입힙니다. 대상은 반사 내성에 실패하면 넘어지고, 방어도와 명중 굴림, 내성 굴림에 -4 불이익을 받습니다.\n대상이 데몬 군주, 악한 드래곤 또는 언데드의 군주(리치, 언데드 드래곤, 나이트셰이드와 같은 강력한 언데드)라면, 이 주문은 대신 캐릭터 레벨당 2d12의 성스러운 피해를 입힙니다. 대상은 방어도와 명중 굴림, 내성 굴림에 -4 불이익을 받으며, 반사 내성에 실패하면 넘어집니다.", true);
      KoreanLocalization.Add("8a5aa491c81b4386ab86f3f9eeb81ac2", "Angelic Bolt", "천사의 번개", false);
      KoreanLocalization.Add("3e26d7db2f1f42f0badb44f5d242b8d3", "Your otherworldy background allows you to  easily graps some of the exploits available within the laws of magic. \nThis allows you to shape the magic around you in specific ways that might  be similar to spells but are not quite spells.", "이세계에서 온 당신은 마법 법칙의 허점을 손쉽게 이해합니다.\n그 덕분에 주변의 마력을 마음대로 다루어, 주문과 비슷하면서도 주문은 아닌 독특한 효과를 만들어 냅니다.", true);
      KoreanLocalization.Add("20e143fe5b934f1ab6397c15baf89fff", "Arcanist Legacy - Arcanist", "아카니스트 전승: 아카니스트", false);
      KoreanLocalization.Add("6df4691ef4054176bb23579be37d430f", "TBD", "설명 준비 중입니다.", true);
      KoreanLocalization.Add("db1eceaa1882495b8f04d4ee441eecfa", "Arcanist Legacy - Brown Fur Transmuter", "아카니스트 전승: 브라운 퍼 트랜스뮤터", false);
      KoreanLocalization.Add("defb10f21ded486fb6691a6ff3afe0e8", "Arcanist Legacy - Eldritch Font", "아카니스트 전승: 엘드리치 폰트", false);
      KoreanLocalization.Add("b44fc92c096346e9ad1070669e3cd61e", "You gain a natural armor bonus to AC equal to your strength modifier.", "방어도에 힘 수정치만큼 자연 갑옷 보너스를 받습니다.", true);
      KoreanLocalization.Add("d519efc5fadd431dafc1f279fb155848", "Armor of Strength", "힘의 갑옷", false);
      KoreanLocalization.Add("de2232ba65414e758a3ca6f106951075", "You can move at normal speed while wearing armor. You also reduce your armor check penalty to zero and increase your max dexterity bonus by 20.", "갑옷을 입어도 정상 속도로 이동합니다. 갑옷 판정 불이익이 0이 되고, 최대 민첩 보너스가 20 증가합니다.", true);
      KoreanLocalization.Add("c7713092a36a433180b3797a7efb4ae0", "Armor Saint", "갑옷의 달인", false);
      KoreanLocalization.Add(null, "You begin ascension to godhood, you are upgraded to Deity Status increasing all stats by 20.", "당신은 신격을 향해 승천하기 시작합니다. 신의 반열에 올라 모든 능력치가 15 증가합니다.", true);
      KoreanLocalization.Add(null, "Ascension", "승천", false);
      KoreanLocalization.Add("c734b9868dea434783d324b90aee3086", "At 10th level, you are able to choose an aura.", "10레벨에 오라 하나를 선택합니다.", false);
      KoreanLocalization.Add("79afcbcb3f70407da82dd17adb466ba7", "Every time you cast a spell, it becomes bolstered, as though using the Bolster Spell feat.", "시전하는 모든 주문에 확산 주문 특기의 효과가 자동으로 적용됩니다.", false);
      KoreanLocalization.Add("112ef1b9d4ba4d33bfcc24c2fd7c917e", "Overpowered Ability — Auto Bolster", "초월 능력: 자동 확산", false);
      KoreanLocalization.Add("67902a27c40e47db9093483985c3febb", "Every time you cast a acid of fire spell, it causes acid or fire damage on the next round, as though using the Burning Spell feat.", "시전하는 모든 산성 또는 화염 주문에 연소 주문 특기의 효과가 적용되어, 다음 라운드에도 산성 또는 화염 피해를 입힙니다.", false);
      KoreanLocalization.Add("376bc95e1feb417f951e41aecf083a23", "Overpowered Ability — Auto Burning", "초월 능력: 자동 연소", false);
      KoreanLocalization.Add("656c4ad37a254cd1beaf5acfcdfc6dc9", "Every time you cast a spell, you can replace or split its damage with acid damage, as though using the Elemental Spell (Acid) feat.", "시전하는 모든 주문에 원소 주문 (산성) 특기의 효과가 적용되어, 피해 전부 또는 일부를 산성 피해로 바꿀 수 있습니다.", false);
      KoreanLocalization.Add("80089f10e0cb4a82a25ed3aafa98d60a", "Overpowered Ability — Auto Elemental (Acid)", "초월 능력: 자동 원소 (산성)", false);
      KoreanLocalization.Add("ebfff11f910a4b26a34418c67265f332", "Every time you cast a spell, you can replace or split its damage with cold damage, as though using the Elemental Spell (Cold) feat.", "시전하는 모든 주문에 원소 주문 (냉기) 특기의 효과가 적용되어, 피해 전부 또는 일부를 냉기 피해로 바꿀 수 있습니다.", false);
      KoreanLocalization.Add("30b549b63b7a487bb2df382ed0328059", "Overpowered Ability — Auto Elemental (Cold)", "초월 능력: 자동 원소 (냉기)", false);
      KoreanLocalization.Add("a73441f95fa64c68a37599148254087a", "Every time you cast a spell, you can replace or split its damage with electricity damage, as though using the Elemental Spell (Electricity) feat.", "시전하는 모든 주문에 원소 주문 (전격) 특기의 효과가 적용되어, 피해 전부 또는 일부를 전격 피해로 바꿀 수 있습니다.", false);
      KoreanLocalization.Add("42e6135e36544e1b8fb92c1707ca652b", "Overpowered Ability — Auto Elemental (Electricity)", "초월 능력: 자동 원소 (전격)", false);
      KoreanLocalization.Add("cea428717b7f4987b69a55ef6b0c9fb3", "Every time you cast a spell, you can replace or split its damage with fire damage, as though using the Elemental Spell (Fire) feat.", "시전하는 모든 주문에 원소 주문 (화염) 특기의 효과가 적용되어, 피해 전부 또는 일부를 화염 피해로 바꿀 수 있습니다.", false);
      KoreanLocalization.Add("7646dc3cd05646b9b69ed9f3163ed3c4", "Overpowered Ability — Auto Elemental (Fire)", "초월 능력: 자동 원소 (화염)", false);
      KoreanLocalization.Add("ddc72905ceb442289902d43b9d8b367e", "Every time you cast a spell, it becomes empowered, as though using the Empower Spell feat.", "시전하는 모든 주문에 강화 주문 특기의 효과가 자동으로 적용됩니다.", false);
      KoreanLocalization.Add("4e8795c7fd2d4209a7ce61e346d26e1d", "Overpowered Ability — Auto Empower", "초월 능력: 자동 강화", false);
      KoreanLocalization.Add("37c33c665f74457abd3f7f272c2e2aad", "Every time you cast a spell, increase its morale bonus by 1, as though using the Encouraging Spell feat.", "시전하는 모든 주문에 격려 주문 특기의 효과가 적용되어, 해당 주문이 부여하는 사기 보너스가 1 증가합니다.", false);
      KoreanLocalization.Add("f9966b7ebef046bf8257e81351950cd6", "Overpowered Ability — Auto Encouraging", "초월 능력: 자동 격려", false);
      KoreanLocalization.Add("b11d0e9e3bbc48af9d0b78eff5108c37", "Every time you cast a spell, it becomes extended, as though using the Extend Spell feat.", "시전하는 모든 주문에 시간 연장 주문 특기의 효과가 자동으로 적용됩니다.", false);
      KoreanLocalization.Add("aa275255a88d4d8db9ba0c598a13a981", "Overpowered Ability — Auto Extend", "초월 능력: 자동 시간 연장", false);
      KoreanLocalization.Add("4c2b14fd1e654d13b92e103228a642de", "Every time you cast a light, fire, or electricity spell, it causes the dazzling condition, as though using the Flaring Spell feat.", "시전하는 모든 빛, 화염, 전격 주문에 섬광 주문 특기의 효과가 적용되어 눈부심을 유발합니다.", false);
      KoreanLocalization.Add("e20574e4191442bcaa659a28dd7c20f0", "Overpowered Ability — Auto Flaring", "초월 능력: 자동 섬광", false);
      KoreanLocalization.Add("2fa644f5e1f24c638ceb234c78b5fa82", "Every time you cast a spell, increase its maximum damage dice by 5, as though using the Intensified Spell feat.", "시전하는 모든 주문에 강렬화 주문 특기의 효과가 적용되어, 최대 피해 주사위 수가 5 증가합니다.", false);
      KoreanLocalization.Add("9d5bb51ca24142f8a89615973bdfe989", "Overpowered Ability — Auto Intensified", "초월 능력: 자동 강렬화", false);
      KoreanLocalization.Add("328716fd75ee4c85bba52e8cfe5beb82", "Every time you cast a spell, it becomes maximized, as though using the Maximize Spell feat.", "시전하는 모든 주문에 극대화 주문 특기의 효과가 자동으로 적용됩니다.", false);
      KoreanLocalization.Add("4b2730270d7844e0afe8672de1cddc71", "Overpowered Ability — Auto Maximize", "초월 능력: 자동 극대화", false);
      KoreanLocalization.Add("09a6d3ac1d864d4db4519ad527be4917", "Overpowered Ability — Auto Metamagic", "초월 능력: 자동 메타매직", false);
      KoreanLocalization.Add("f07306e39b2d4efbb2c0a38b0a1528cf", "Auto Metamagic", "자동 메타매직", false);
      KoreanLocalization.Add("79bee31e28f540dea4a13834ecd480f2", "Every time you cast a spell against a target, it treats the spell resistance of the target as 5 lower than its actual SR, as though using the Piercing Spell feat.", "시전하는 모든 주문에 관통 주문 특기의 효과가 적용되어, 대상의 주문 저항을 실제 수치보다 5 낮게 취급합니다.", false);
      KoreanLocalization.Add("1e26e017a3644dccb51e5ed00cc0ff0b", "Overpowered Ability — Auto Piercing", "초월 능력: 자동 관통", false);
      KoreanLocalization.Add("23ee3aa855cc44bf8e04c5146dce587e", "Every time you cast a spell, it becomes quickened, as though using the Quicken Spell feat.", "시전하는 모든 주문에 신속 주문 특기의 효과가 자동으로 적용됩니다.", false);
      KoreanLocalization.Add("02c95b600f0343db81c7ab47d019013e", "Overpowered Ability — Auto Quicken", "초월 능력: 자동 신속", false);
      KoreanLocalization.Add("1d70dec2b1724a5791ad46cced7e0105", "Every time you cast a spell, it increases its range by one range category, as though using the Reach Spell feat.", "시전하는 모든 주문에 사거리 연장 주문 특기의 효과가 적용되어, 사거리 범주가 한 단계 증가합니다.", false);
      KoreanLocalization.Add("b53869e1c0b944e3a5cace3afc22a1a2", "Overpowered Ability — Auto Reach", "초월 능력: 자동 사거리 연장", false);
      KoreanLocalization.Add("a207afa84cb54ed68cfa021f40fbe57b", "Every time you cast a cold spell, it entangles the target, as though using the Rime Spell feat.", "시전하는 모든 냉기 주문에 서리 주문 특기의 효과가 적용되어, 대상을 얽힘 상태로 만듭니다.", false);
      KoreanLocalization.Add("c8fc6e6800c54825bf690efa2641bf74", "Overpowered Ability — Auto Rime", "초월 능력: 자동 서리", false);
      KoreanLocalization.Add("8410f503063a4fac98bd00d274da7930", "Every time you cast a spell, you can exclude targets from the effects of your spell, as though using the Selective Spell feat.", "시전하는 모든 주문에 선택적 주문 특기의 효과가 적용되어, 원하는 대상을 주문 효과에서 제외할 수 있습니다.", false);
      KoreanLocalization.Add("98a62af8053b419c9f297451ff384c42", "Overpowered Ability — Auto Selective", "초월 능력: 자동 선택적", false);
      KoreanLocalization.Add("aa1da040888f4b97bb02845445d000ef", "Every time you cast a shadow spell, it becomes 20% more real, as though using the Solid Shadows Spell feat.", "시전하는 모든 그림자 주문에 견고한 그림자 특기의 효과가 적용되어, 실재성이 20% 증가합니다.", false);
      KoreanLocalization.Add("7a11cddec336484199029994b266213e", "Overpowered Ability — Auto Solid Shadows", "초월 능력: 자동 견고한 그림자", false);
      KoreanLocalization.Add("1b739339d68a42cbaeff25600751a504", "You gain powerful metamagic effects that automatically apply to your spells.", "당신의 주문에 자동으로 적용되는 강력한 메타매직 효과를 얻습니다.", false);
      KoreanLocalization.Add("ca33dea456ca40918043e680569e394f", "Gain the spells of an Azata.", "아자타의 주문을 얻습니다.", true);
      KoreanLocalization.Add("f50c3f369925435c97bf508b805a49c0", "Mythic Azata Spells", "신화 아자타 주문", false);
      KoreanLocalization.Add("989b268fc3a24a99bebf477552942114", "The Beta Tester has a +4 competence bonus to initiative and adds {g|Encyclopedia:Lore_Nature}Lore (Nature){/g}, {g|Encyclopedia:Lore_Religion}Lore (Religion){/g}, {g|Encyclopedia:Knowledge_World}Knowledge (World){/g}, {g|Encyclopedia:Knowledge_Arcana}Knowledge (Arcana){/g}, and {g|Encyclopedia:Perception}Perception{/g} to the list of her class {g|Encyclopedia:Skills}skills{/g}.\nIf the character already has the class skill, {g|Encyclopedia:Weapon_Proficiency}weapon proficiency{/g} or armor proficiency granted by the selected background from her class during character creation, then the corresponding {g|Encyclopedia:Bonus}bonuses{/g} from background change to a +1 competence bonus in case of skills, a +1 enhancement bonus in case of weapon proficiency and a -1 Armor {g|Encyclopedia:Check}Check{/g} {g|Encyclopedia:Penalty}Penalty{/g} reduction in case of armor proficiency.", "베타 테스터는 우선권에 +4 능숙 보너스를 받고, {g|Encyclopedia:Lore_Nature}전승 (자연){/g}, {g|Encyclopedia:Lore_Religion}전승 (종교){/g}, {g|Encyclopedia:Knowledge_World}지식 (세계){/g}, {g|Encyclopedia:Knowledge_Arcana}지식 (비전){/g}, {g|Encyclopedia:Perception}지각{/g}을 클래스 {g|Encyclopedia:Skills}기술{/g} 목록에 추가합니다.\n캐릭터 생성 시 클래스에서 이미 얻은 클래스 기술, {g|Encyclopedia:Weapon_Proficiency}무기 숙련{/g} 또는 갑옷 숙련을 이 배경에서 다시 얻는다면, 해당 배경의 {g|Encyclopedia:Bonus}보너스{/g}는 다음과 같이 바뀝니다. 기술에는 +1 능숙 보너스를, 무기 숙련에는 +1 강화 보너스를 받으며, 갑옷 숙련의 경우 갑옷 {g|Encyclopedia:Check}판정{/g} {g|Encyclopedia:Penalty}불이익{/g}이 1 감소합니다.", true);
      KoreanLocalization.Add("a8a6a80cc2d24cb6b8beef027da43ac0", "Beta Tester", "베타 테스터", false);
      KoreanLocalization.Add("3558bfdefb8c4717b6eb9797633d2d53", "The Demonic Cultivator adds Athletics and Mobility to the list of her class skills and uses the higher of Strength and Dexterity while attempting Athletics and Mobility Checks.\nIf the character already has the class skill, {g|Encyclopedia:Weapon_Proficiency}weapon proficiency{/g} or armor proficiency granted by the selected background from her class during character creation, then the corresponding {g|Encyclopedia:Bonus}bonuses{/g} from background change to a +1 competence bonus in case of skills, a +1 enhancement bonus in case of weapon proficiency and a -1 Armor {g|Encyclopedia:Check}Check{/g} {g|Encyclopedia:Penalty}Penalty{/g} reduction in case of armor proficiency.", "마공 수련자는 운동과 기동성을 클래스 기술 목록에 추가하며, 운동과 기동성 판정에 힘과 민첩 중 더 높은 능력치를 사용합니다.\n캐릭터 생성 시 클래스에서 이미 얻은 클래스 기술, {g|Encyclopedia:Weapon_Proficiency}무기 숙련{/g} 또는 갑옷 숙련을 이 배경에서 다시 얻는다면, 해당 배경의 {g|Encyclopedia:Bonus}보너스{/g}는 다음과 같이 바뀝니다. 기술에는 +1 능숙 보너스를, 무기 숙련에는 +1 강화 보너스를 받으며, 갑옷 숙련의 경우 갑옷 {g|Encyclopedia:Check}판정{/g} {g|Encyclopedia:Penalty}불이익{/g}이 1 감소합니다.", true);
      KoreanLocalization.Add("7759ab11f0c247a1b7a2f8a67981745e", "Demonic Cultivator", "마공 수련자", false);
      KoreanLocalization.Add("45086c63b645427fa0d8a1394736bbf7", "The Enlightened Sage adds {g|Encyclopedia:Lore_Nature}Lore (Nature){/g}, {g|Encyclopedia:Lore_Religion}Lore (Religion){/g}, {g|Encyclopedia:Knowledge_World}Knowledge (World){/g}, {g|Encyclopedia:Knowledge_Arcana}Knowledge (Arcana){/g}, and {g|Encyclopedia:Perception}Perception{/g} to the list of her class {g|Encyclopedia:Skills}skills{/g} and can use the higher of {g|Encyclopedia:Intelligence}Intelligence{/g} and {g|Encyclopedia:Wisdom}Wisdom{/g} while attempting Knowledge (World), Knowledge (Arcana), Lore (Religion), or Lore (Nature) {g|Encyclopedia:Check}checks{/g}.\nIf the character already has the class skill, {g|Encyclopedia:Weapon_Proficiency}weapon proficiency{/g} or armor proficiency granted by the selected background from her class during character creation, then the corresponding {g|Encyclopedia:Bonus}bonuses{/g} from background change to a +1 competence bonus in case of skills, a +1 enhancement bonus in case of weapon proficiency and a -1 Armor {g|Encyclopedia:Check}Check{/g} {g|Encyclopedia:Penalty}Penalty{/g} reduction in case of armor proficiency.", "깨달음을 얻은 현자는 {g|Encyclopedia:Lore_Nature}전승 (자연){/g}, {g|Encyclopedia:Lore_Religion}전승 (종교){/g}, {g|Encyclopedia:Knowledge_World}지식 (세계){/g}, {g|Encyclopedia:Knowledge_Arcana}지식 (비전){/g}, {g|Encyclopedia:Perception}지각{/g}을 클래스 {g|Encyclopedia:Skills}기술{/g} 목록에 추가합니다. 지식 (세계), 지식 (비전), 전승 (종교), 전승 (자연) {g|Encyclopedia:Check}판정{/g}에는 {g|Encyclopedia:Intelligence}지능{/g}과 {g|Encyclopedia:Wisdom}지혜{/g} 중 더 높은 능력치를 사용할 수 있습니다.\n캐릭터 생성 시 클래스에서 이미 얻은 클래스 기술, {g|Encyclopedia:Weapon_Proficiency}무기 숙련{/g} 또는 갑옷 숙련을 이 배경에서 다시 얻는다면, 해당 배경의 {g|Encyclopedia:Bonus}보너스{/g}는 다음과 같이 바뀝니다. 기술에는 +1 능숙 보너스를, 무기 숙련에는 +1 강화 보너스를 받으며, 갑옷 숙련의 경우 갑옷 {g|Encyclopedia:Check}판정{/g} {g|Encyclopedia:Penalty}불이익{/g}이 1 감소합니다.", true);
      KoreanLocalization.Add("1cf1456108ad4edea5025bbf9ddcdf7e", "Enlightened Sage", "깨달음을 얻은 현자", false);
      KoreanLocalization.Add("e23526bd09cd486685424c7e8e398f19", "The Gamer has a +8 competence bonus to all knowledge, lore, and perception checks.\nIf the character already has the class skill, {g|Encyclopedia:Weapon_Proficiency}weapon proficiency{/g} or armor proficiency granted by the selected background from her class during character creation, then the corresponding {g|Encyclopedia:Bonus}bonuses{/g} from background change to a +1 competence bonus in case of skills, a +1 enhancement bonus in case of weapon proficiency and a -1 Armor {g|Encyclopedia:Check}Check{/g} {g|Encyclopedia:Penalty}Penalty{/g} reduction in case of armor proficiency.", "게이머는 모든 지식, 전승, 지각 판정에 +8 능숙 보너스를 받습니다.\n캐릭터 생성 시 클래스에서 이미 얻은 클래스 기술, {g|Encyclopedia:Weapon_Proficiency}무기 숙련{/g} 또는 갑옷 숙련을 이 배경에서 다시 얻는다면, 해당 배경의 {g|Encyclopedia:Bonus}보너스{/g}는 다음과 같이 바뀝니다. 기술에는 +1 능숙 보너스를, 무기 숙련에는 +1 강화 보너스를 받으며, 갑옷 숙련의 경우 갑옷 {g|Encyclopedia:Check}판정{/g} {g|Encyclopedia:Penalty}불이익{/g}이 1 감소합니다.", true);
      KoreanLocalization.Add("4a6548016cc34cf5b4559d89489a0186", "Gamer", "게이머", false);
      KoreanLocalization.Add("271aab37feb941b9ada585d0116bc5ea", "The Highschool Student gains a +1 bonus to all attributes.\nIf the character already has the class skill, {g|Encyclopedia:Weapon_Proficiency}weapon proficiency{/g} or armor proficiency granted by the selected background from her class during character creation, then the corresponding {g|Encyclopedia:Bonus}bonuses{/g} from background change to a +1 competence bonus in case of skills, a +1 enhancement bonus in case of weapon proficiency and a -1 Armor {g|Encyclopedia:Check}Check{/g} {g|Encyclopedia:Penalty}Penalty{/g} reduction in case of armor proficiency.", "고등학생은 모든 능력치에 +1 보너스를 받습니다.\n캐릭터 생성 시 클래스에서 이미 얻은 클래스 기술, {g|Encyclopedia:Weapon_Proficiency}무기 숙련{/g} 또는 갑옷 숙련을 이 배경에서 다시 얻는다면, 해당 배경의 {g|Encyclopedia:Bonus}보너스{/g}는 다음과 같이 바뀝니다. 기술에는 +1 능숙 보너스를, 무기 숙련에는 +1 강화 보너스를 받으며, 갑옷 숙련의 경우 갑옷 {g|Encyclopedia:Check}판정{/g} {g|Encyclopedia:Penalty}불이익{/g}이 1 감소합니다.", true);
      KoreanLocalization.Add("d22f60648cd44038b4d27865ae8e3273", "Highschool Student", "고등학생", false);
      KoreanLocalization.Add("fd3cfab8d597484e9298b89363a8ce18", "The Martial Artist is proficient with all exotic weapons.\nIf the character already has the class skill, {g|Encyclopedia:Weapon_Proficiency}weapon proficiency{/g} or armor proficiency granted by the selected background from her class during character creation, then the corresponding {g|Encyclopedia:Bonus}bonuses{/g} from background change to a +1 competence bonus in case of skills, a +1 enhancement bonus in case of weapon proficiency and a -1 Armor {g|Encyclopedia:Check}Check{/g} {g|Encyclopedia:Penalty}Penalty{/g} reduction in case of armor proficiency.", "무도가는 모든 특수 무기에 숙련됩니다.\n캐릭터 생성 시 클래스에서 이미 얻은 클래스 기술, {g|Encyclopedia:Weapon_Proficiency}무기 숙련{/g} 또는 갑옷 숙련을 이 배경에서 다시 얻는다면, 해당 배경의 {g|Encyclopedia:Bonus}보너스{/g}는 다음과 같이 바뀝니다. 기술에는 +1 능숙 보너스를, 무기 숙련에는 +1 강화 보너스를 받으며, 갑옷 숙련의 경우 갑옷 {g|Encyclopedia:Check}판정{/g} {g|Encyclopedia:Penalty}불이익{/g}이 1 감소합니다.", true);
      KoreanLocalization.Add("db57d7bdecc74ae693e3999c8705e969", "Martial Artist", "무도가", false);
      KoreanLocalization.Add("844d0e7a317e4da384eac6075c01a47c", "The Musician add Persuasion to the list of her class skills and has a +2 bonus to caster level and DC for Sonic spells.\nIf the character already has the class skill, {g|Encyclopedia:Weapon_Proficiency}weapon proficiency{/g} or armor proficiency granted by the selected background from her class during character creation, then the corresponding {g|Encyclopedia:Bonus}bonuses{/g} from background change to a +1 competence bonus in case of skills, a +1 enhancement bonus in case of weapon proficiency and a -1 Armor {g|Encyclopedia:Check}Check{/g} {g|Encyclopedia:Penalty}Penalty{/g} reduction in case of armor proficiency.", "음악가는 설득을 클래스 기술 목록에 추가하고, 음파 주문의 시전자 레벨과 난이도에 +2 보너스를 받습니다.\n캐릭터 생성 시 클래스에서 이미 얻은 클래스 기술, {g|Encyclopedia:Weapon_Proficiency}무기 숙련{/g} 또는 갑옷 숙련을 이 배경에서 다시 얻는다면, 해당 배경의 {g|Encyclopedia:Bonus}보너스{/g}는 다음과 같이 바뀝니다. 기술에는 +1 능숙 보너스를, 무기 숙련에는 +1 강화 보너스를 받으며, 갑옷 숙련의 경우 갑옷 {g|Encyclopedia:Check}판정{/g} {g|Encyclopedia:Penalty}불이익{/g}이 1 감소합니다.", true);
      KoreanLocalization.Add("ec9cff54e4ee411a8d45e842a77b6697", "Musician", "음악가", false);
      KoreanLocalization.Add("726ae8ac0f6044c194102790bcc9a5a4", "The Otaku adds all skills to the list of her class skills except Persuasion.\nIf the character already has the class skill, {g|Encyclopedia:Weapon_Proficiency}weapon proficiency{/g} or armor proficiency granted by the selected background from her class during character creation, then the corresponding {g|Encyclopedia:Bonus}bonuses{/g} from background change to a +1 competence bonus in case of skills, a +1 enhancement bonus in case of weapon proficiency and a -1 Armor {g|Encyclopedia:Check}Check{/g} {g|Encyclopedia:Penalty}Penalty{/g} reduction in case of armor proficiency.", "오타쿠는 설득을 제외한 모든 기술을 클래스 기술 목록에 추가합니다.\n캐릭터 생성 시 클래스에서 이미 얻은 클래스 기술, {g|Encyclopedia:Weapon_Proficiency}무기 숙련{/g} 또는 갑옷 숙련을 이 배경에서 다시 얻는다면, 해당 배경의 {g|Encyclopedia:Bonus}보너스{/g}는 다음과 같이 바뀝니다. 기술에는 +1 능숙 보너스를, 무기 숙련에는 +1 강화 보너스를 받으며, 갑옷 숙련의 경우 갑옷 {g|Encyclopedia:Check}판정{/g} {g|Encyclopedia:Penalty}불이익{/g}이 1 감소합니다.", true);
      KoreanLocalization.Add("b83e848454dd4f1b996b78e3f312379b", "Otaku", "오타쿠", false);
      KoreanLocalization.Add("196d3de964a9431d9b94f53482679b28", "The Rationalist is immune to any {g|Encyclopedia:Spell}spell{/g} or {g|Encyclopedia:Special_Abilities}spell-like ability{/g} that allows {g|Encyclopedia:Spell_Resistance}spell resistance{/g} but cannot cast any spells.\nIf the character already has the class skill, {g|Encyclopedia:Weapon_Proficiency}weapon proficiency{/g} or armor proficiency granted by the selected background from her class during character creation, then the corresponding {g|Encyclopedia:Bonus}bonuses{/g} from background change to a +1 competence bonus in case of skills, a +1 enhancement bonus in case of weapon proficiency and a -1 Armor {g|Encyclopedia:Check}Check{/g} {g|Encyclopedia:Penalty}Penalty{/g} reduction in case of armor proficiency.", "합리주의자는 {g|Encyclopedia:Spell_Resistance}주문 저항{/g}을 허용하는 모든 {g|Encyclopedia:Spell}주문{/g}과 {g|Encyclopedia:Special_Abilities}주문 유사 능력{/g}에 면역이 되지만, 어떤 주문도 시전할 수 없습니다.\n캐릭터 생성 시 클래스에서 이미 얻은 클래스 기술, {g|Encyclopedia:Weapon_Proficiency}무기 숙련{/g} 또는 갑옷 숙련을 이 배경에서 다시 얻는다면, 해당 배경의 {g|Encyclopedia:Bonus}보너스{/g}는 다음과 같이 바뀝니다. 기술에는 +1 능숙 보너스를, 무기 숙련에는 +1 강화 보너스를 받으며, 갑옷 숙련의 경우 갑옷 {g|Encyclopedia:Check}판정{/g} {g|Encyclopedia:Penalty}불이익{/g}이 1 감소합니다.", true);
      KoreanLocalization.Add("0e3ec9c7797b47159ff4925a51c11165", "Rationalist", "합리주의자", false);
      KoreanLocalization.Add("2adf4f45839b4d65a0c01d4505a5276b", "The Reborn Demon Lord has a +2 bonus to strength and electricity resistance 20.\nIf the character already has the class skill, {g|Encyclopedia:Weapon_Proficiency}weapon proficiency{/g} or armor proficiency granted by the selected background from her class during character creation, then the corresponding {g|Encyclopedia:Bonus}bonuses{/g} from background change to a +1 competence bonus in case of skills, a +1 enhancement bonus in case of weapon proficiency and a -1 Armor {g|Encyclopedia:Check}Check{/g} {g|Encyclopedia:Penalty}Penalty{/g} reduction in case of armor proficiency.", "환생한 마왕은 힘에 +2 보너스를 받고 전격 저항 20을 얻습니다.\n캐릭터 생성 시 클래스에서 이미 얻은 클래스 기술, {g|Encyclopedia:Weapon_Proficiency}무기 숙련{/g} 또는 갑옷 숙련을 이 배경에서 다시 얻는다면, 해당 배경의 {g|Encyclopedia:Bonus}보너스{/g}는 다음과 같이 바뀝니다. 기술에는 +1 능숙 보너스를, 무기 숙련에는 +1 강화 보너스를 받으며, 갑옷 숙련의 경우 갑옷 {g|Encyclopedia:Check}판정{/g} {g|Encyclopedia:Penalty}불이익{/g}이 1 감소합니다.", true);
      KoreanLocalization.Add("c4da699e5cb04ccda5473a5b7d92a458", "Reborn Demon Lord", "환생한 마왕", false);
      KoreanLocalization.Add("2207757e657d40b6bc255b5719156d9c", "The Salaryman adds Perception to the list of her class skills. She can also use her Charisma instead of Wisdom while attempting Perception checks.\nIf the character already has the class skill, {g|Encyclopedia:Weapon_Proficiency}weapon proficiency{/g} or armor proficiency granted by the selected background from her class during character creation, then the corresponding {g|Encyclopedia:Bonus}bonuses{/g} from background change to a +1 competence bonus in case of skills, a +1 enhancement bonus in case of weapon proficiency and a -1 Armor {g|Encyclopedia:Check}Check{/g} {g|Encyclopedia:Penalty}Penalty{/g} reduction in case of armor proficiency.", "회사원은 지각을 클래스 기술 목록에 추가합니다. 지각 판정에 지혜 대신 매력을 사용할 수 있습니다.\n캐릭터 생성 시 클래스에서 이미 얻은 클래스 기술, {g|Encyclopedia:Weapon_Proficiency}무기 숙련{/g} 또는 갑옷 숙련을 이 배경에서 다시 얻는다면, 해당 배경의 {g|Encyclopedia:Bonus}보너스{/g}는 다음과 같이 바뀝니다. 기술에는 +1 능숙 보너스를, 무기 숙련에는 +1 강화 보너스를 받으며, 갑옷 숙련의 경우 갑옷 {g|Encyclopedia:Check}판정{/g} {g|Encyclopedia:Penalty}불이익{/g}이 1 감소합니다.", true);
      KoreanLocalization.Add("61c8580542044084970fdf9b04919bfc", "Salaryman", "회사원", false);
      KoreanLocalization.Add("46de686d894847bc89034bf0dceac626", "The Tabletop RPG Player adds {g|Encyclopedia:Lore_Nature}Lore (Nature){/g}, {g|Encyclopedia:Lore_Religion}Lore (Religion){/g}, {g|Encyclopedia:Knowledge_World}Knowledge (World){/g} and {g|Encyclopedia:Knowledge_Arcana}Knowledge (Arcana){/g} to the list of her class {g|Encyclopedia:Skills}skills{/g} and can use her {g|Encyclopedia:Charisma}Charisma{/g} instead of {g|Encyclopedia:Intelligence}Intelligence{/g} or {g|Encyclopedia:Wisdom}Wisdom{/g} while attempting Knowledge (World), Knowledge (Arcana), Lore (Religion), or Lore (Nature) {g|Encyclopedia:Check}checks{/g}.\nIf the character already has the class skill, {g|Encyclopedia:Weapon_Proficiency}weapon proficiency{/g} or armor proficiency granted by the selected background from her class during character creation, then the corresponding {g|Encyclopedia:Bonus}bonuses{/g} from background change to a +1 competence bonus in case of skills, a +1 enhancement bonus in case of weapon proficiency and a -1 Armor {g|Encyclopedia:Check}Check{/g} {g|Encyclopedia:Penalty}Penalty{/g} reduction in case of armor proficiency.", "테이블톱 RPG 플레이어는 {g|Encyclopedia:Lore_Nature}전승 (자연){/g}, {g|Encyclopedia:Lore_Religion}전승 (종교){/g}, {g|Encyclopedia:Knowledge_World}지식 (세계){/g}, {g|Encyclopedia:Knowledge_Arcana}지식 (비전){/g}을 클래스 {g|Encyclopedia:Skills}기술{/g} 목록에 추가합니다. 지식 (세계), 지식 (비전), 전승 (종교), 전승 (자연) {g|Encyclopedia:Check}판정{/g}에는 {g|Encyclopedia:Intelligence}지능{/g}이나 {g|Encyclopedia:Wisdom}지혜{/g} 대신 {g|Encyclopedia:Charisma}매력{/g}을 사용할 수 있습니다.\n캐릭터 생성 시 클래스에서 이미 얻은 클래스 기술, {g|Encyclopedia:Weapon_Proficiency}무기 숙련{/g} 또는 갑옷 숙련을 이 배경에서 다시 얻는다면, 해당 배경의 {g|Encyclopedia:Bonus}보너스{/g}는 다음과 같이 바뀝니다. 기술에는 +1 능숙 보너스를, 무기 숙련에는 +1 강화 보너스를 받으며, 갑옷 숙련의 경우 갑옷 {g|Encyclopedia:Check}판정{/g} {g|Encyclopedia:Penalty}불이익{/g}이 1 감소합니다.", true);
      KoreanLocalization.Add("9ad57bb50ad74ea1bd88c15d1aebf10d", "Tabletop RPG Player", "테이블톱 RPG 플레이어", false);
      KoreanLocalization.Add("a24805b2c79740cbb30493809cf6b255", "You really are just a walking bundle of issues waiting to explode at anyone getting too close, aren't you?", "당신은 누군가 조금만 다가와도 터져 버릴 듯한, 걸어 다니는 분노 덩어리군요?", true);
      KoreanLocalization.Add("0ad058a74d004c78a5aa663a1a19fc7d", "Barbarian Legacy - Ball of Rage", "바바리안 전승: 분노 덩어리", false);
      KoreanLocalization.Add("e0015b4af0514441ad458f3cf12a229f", "You know what is even more effective in gathering a great harem than being a great hero? \nThat is right, music the language of romance, there is a reason why so many males hate bards...", "훌륭한 용사가 되는 것보다 멋진 하렘을 만드는 데 더 효과적인 게 뭔지 아십니까?\n바로 낭만의 언어, 음악입니다. 세상 남자들이 바드를 그토록 싫어하는 데는 다 이유가 있답니다…", true);
      KoreanLocalization.Add("365a6ec4c0924b01b32ee408c21cd143", "Bard Legacy - Musical Prodige", "바드 전승: 음악 신동", false);
      KoreanLocalization.Add("77841a2afc14448f835464ac17f54bcc", "At 7th level, you are able to channel your energy to form a solid barrier to shield allies from physical and magical attacks.", "7레벨에 에너지를 단단한 장벽으로 응축하여, 물리 공격과 마법 공격으로부터 아군을 보호할 수 있습니다.", true);
      KoreanLocalization.Add("c42919b8e3fc4ce3b744510e361e4839", "Energy Barrier", "에너지 장벽", false);
      KoreanLocalization.Add(null, "You get an additional {g|Encyclopedia:Attack}attack{/g} per {g|Encyclopedia:Combat_Round}round{/g}.", "{g|Encyclopedia:Combat_Round}라운드{/g}마다 {g|Encyclopedia:Attack}공격{/g} 횟수를 한 번 추가로 얻습니다.", true);
      KoreanLocalization.Add("ed05e7ce736d45d19884da29afbeddd3", "Beta Strike", "베타 스트라이크", false);
      KoreanLocalization.Add("45b5d46776c94031b05a644ba172d780", "Wings (Black)", "날개 (검은색)", false);
      KoreanLocalization.Add("df7fe95cdaec47edaf09f46ed2060205", "You gain immunity to bleed.", "출혈에 면역이 됩니다.", true);
      KoreanLocalization.Add("59ee2560a106464f85a44f3d33763f92", "Bleed Immunity", "출혈 면역", false);
      KoreanLocalization.Add("430652d6ad0b46b4aeb900e99fb1a769", "Behold the blessing of the Angel.", "천사의 축복을 보십시오.", true);
      KoreanLocalization.Add("27a287aa2371463b8ceb67d1aaa49bb8", "Angel Mythic Class Feature", "엔젤 신화 클래스 능력", false);
      KoreanLocalization.Add("5d0e5d19d6064a48bc786d821800023a", "Let me show you something fun!", "재미있는 걸 보여 줄게!", true);
      KoreanLocalization.Add("46b9ee94e2e9412095ad6e721a30662b", "Azata Mythic Class Feature", "아자타 신화 클래스 능력", false);
      KoreanLocalization.Add("126e0a6c73df4e8fab130838147d559a", "What?\nA bit of undeath never hurt anyone...", "왜요?\n언데드의 힘을 조금 쓴다고 큰일 나지는 않잖아요…", true);
      KoreanLocalization.Add("de8355f6a537450a9db3099a2c53e28f", "Lich Mythic Class Feature", "리치 신화 클래스 능력", false);
      KoreanLocalization.Add("4f13778f3c734e51ab1c0133df61e931", "So I am an angel, is that really a reason not to cast demonic spells? \nOr to deny myself some of those sweet abilities of the trickster?\nSome of you Aeons are far too unflexible.\nSpeaking of Aeons, you got some great spells as well, didn't you?\nLet me quickly learn them...\nSource: Isekai Mod", "내가 천사라고 해서 데몬의 주문을 쓰지 말라는 법이라도 있나요?\n트릭스터의 근사한 능력들을 포기할 이유도 없고요.\n에온 여러분은 너무 고지식하다니까요.\n그러고 보니 에온도 좋은 주문을 많이 갖고 있었죠?\n금방 배워 볼게요…\n출처: 이세계 모드", true);
      KoreanLocalization.Add("2bc360b0dfcf4feea7e7dc94a4e9c89c", "Mythic Class Feature", "신화 클래스 능력", false);
      KoreanLocalization.Add("eb08b17e3b94402a8c58a3eb2c55dc4d", "A feat worthy of a Trickster.", "트릭스터에게 어울리는 특기입니다.", true);
      KoreanLocalization.Add("94be6d880a5547239b6935567a97dc90", "Trickster Mythic Class Feature", "트릭스터 신화 클래스 능력", false);
      KoreanLocalization.Add("4e2ada13262342dc8081a946c2eeb6fd", "You gain immunity to blindness.", "실명에 면역이 됩니다.", true);
      KoreanLocalization.Add("521a68d68957464ebeaa980356d5b08d", "Blind Immunity", "실명 면역", false);
      KoreanLocalization.Add("1e7a61b6c7424d3fbaa8c735a4941bc2", "Much like the Chimera you draw upon the power of inhuman bloodlines and learned how to slowly either awaken or fuse more of them into yourself. \nHowever, you would rather use that to empower your melee attacks rather than your spells.\nAfter all, what is the point of draconic claws or a phoenixes burning wings if you only use them as a fallback?", "키메라처럼 이형의 혈통에서 힘을 끌어내는 당신은, 더 많은 혈통을 몸 안에서 서서히 일깨우거나 융합하는 법을 배웠습니다.\n다만 그 힘을 주문보다는 근접 공격을 강화하는 데 쓰고 싶어 합니다.\n드래곤의 발톱이나 피닉스의 불타는 날개를 기껏 얻어 놓고, 비상시에만 쓴다면 무슨 소용이겠습니까?", true);
      KoreanLocalization.Add("8ed67611a05446db9ae8cefcc574089a", "Bloodrager Legacy - Chimeric Rager", "블러드레이저 전승: 키메라의 분노", false);
      KoreanLocalization.Add("a6832e06ce0f4ffb8d8f5f1f5c898e4a", "At 10th level, you gain the ability to alter the bodies and minds of those around you.", "10레벨에 주변 존재의 육체와 정신을 변화시키는 능력을 얻습니다.", true);
      KoreanLocalization.Add("037091429eed4bf2b99273e64265ede6", "Alteration of Body and Mind", "심신 변형", false);
      KoreanLocalization.Add("87675887e893474b9ecdfba6f96c3df3", "You gain {g|Encyclopedia:Damage_Reduction}DR{/g}/— equal to your character level.", "캐릭터 레벨만큼 {g|Encyclopedia:Damage_Reduction}피해 감소{/g}/—를 얻습니다.", true);
      KoreanLocalization.Add("d39d42807ca14fdfbcddfe6854b62a57", "Body Strengthening", "육체 강화", false);
      KoreanLocalization.Add("18e2199768e4404da8480204024b2a14", "You charge into the thick of things, but no matter how hectic the chaos around you gets you never forget your team. \nAfter all teamwork is at its most important if you and the team are surrounded by enemies on all sides.", "당신은 전투 한복판으로 돌진하면서도 동료들을 잊지 않습니다.\n사방을 적에게 포위당했을 때야말로 협동이 가장 중요하니까요.", true);
      KoreanLocalization.Add("3c80da5745fc4a7d896b86eedbf85222", "Cavalier Legacy - Frontline Leader", "캐벌리어 전승: 전위 지휘관", false);
      KoreanLocalization.Add("da05d413756c4470b02f4c1680135473", "What do you mean shields don't stop magic?\nWell I can make my shield work to block magic too, don't blame me if you are not good enough to do it too...", "방패로는 마법을 못 막는다고요?\n내 방패는 마법도 막습니다. 당신 실력이 모자란 걸 내 탓으로 돌리지는 마세요…", true);
      KoreanLocalization.Add("27f5f676f4ae4f97a3771eff29b50071", "Cavalier Legacy - Magic Shield", "캐벌리어 전승: 마법 방패", false);
      KoreanLocalization.Add("6d7600777dd74d20a5958e1f68172018", "Some lead from the front, but while you can charge ahead you prefer to lead from the back.\nAfter all the backline grants you a much better strategic position to evaluate where the problems in the formation are. \nAlso, at your core you are a caster, so why should you charge into the thick of things?", "앞장서서 이끄는 사람도 있지만, 당신은 돌격할 수 있어도 후방에서 지휘하는 편을 택합니다.\n뒤에 있어야 대형의 허점을 더 잘 살필 수 있으니까요.\n게다가 당신은 본래 주문 시전자입니다. 굳이 난전 속으로 뛰어들 이유가 있나요?", true);
      KoreanLocalization.Add("8192bc631f024b54b7a4bb24e5cfb73d", "Cavalier Legacy - Backline Leader", "캐벌리어 전승: 후위 지휘관", false);
      KoreanLocalization.Add("e7f4f0ed9c144bcdaa39f8d096009367", "Allies within 40 feet of you transform their damage type into divine.", "40피트 이내 아군이 입히는 피해의 유형이 신성으로 바뀝니다.", false);
      KoreanLocalization.Add("6d7ca2a07d95401b983c470687457ad6", "Celestial Realm", "천상의 영역", false);
      KoreanLocalization.Add("d5f2b123420243b48d442a4abc6f3222", "This character transforms their damage type into divine.", "이 캐릭터가 입히는 피해의 유형이 신성으로 바뀝니다.", false);
      KoreanLocalization.Add("c49f86b003004561902221a57a3f2584", "Chaotic allies within 120 feet of you has two extra attacks and deals an additional 2d6 physical damage.", "120피트 이내의 혼돈 성향 아군은 공격 횟수를 두 번 추가로 얻고, 물리 피해를 2d6만큼 추가로 입힙니다.", false);
      KoreanLocalization.Add("7850193df7ab4e86bfc82f341edca447", "Overpowered Aura — Chaotic Frenzy", "초월 오라: 혼돈의 광란", false);
      KoreanLocalization.Add("a4c0b04b40794e4fa5e47b2f2979444f", "This character has two extra attacks and deals an additional 2d6 physical damage.", "이 캐릭터는 공격 횟수를 두 번 추가로 얻고, 물리 피해를 2d6만큼 추가로 입힙니다.", false);
      KoreanLocalization.Add("588efa8448714b3f8828947236986dc6", "Aura of Chaotic Frenzy", "혼돈의 광란 오라", false);
      KoreanLocalization.Add("f91a8548088246a09c3fa8d930554fdd", "You gain immunity to charm.", "매혹에 면역이 됩니다.", true);
      KoreanLocalization.Add("06627a907f934ed5aba0886ea55ffb24", "Charm Immunity", "매혹 면역", false);
      KoreanLocalization.Add("62c6ae402b364fe09e59f5fbf93415e2", "Allies within 120 feet gain 1 additional {g|Encyclopedia:Attack}attack{/g} to their main weapon, a +10 bonus to speed, and attacks have a 50% chance to miss them.", "120피트 이내 아군은 주무기의 {g|Encyclopedia:Attack}공격{/g} 횟수를 한 번 추가로 얻고 이동 속도에 +10 보너스를 받으며, 자신을 향한 공격을 50% 확률로 회피합니다.", false);
      KoreanLocalization.Add("63d0770779674681bfee8e5f334f04cc", "This character has 1 additional {g|Encyclopedia:Attack}attack{/g} to their main weapon, a +10 bonus to speed, and attacks have a 50% chance to miss them.", "이 캐릭터는 주무기의 {g|Encyclopedia:Attack}공격{/g} 횟수를 한 번 추가로 얻고 이동 속도에 +10 보너스를 받으며, 자신을 향한 공격을 50% 확률로 회피합니다.", true);
      KoreanLocalization.Add("a9a59fd498f04dc794ddf92fa7f5486e", "Chuunibyou Actualisation", "중2병의 현실화", false);
      KoreanLocalization.Add("511038cf90fc4d089d8202465200e499", "You gain immunity to Cold.", "냉기에 면역이 됩니다.", true);
      KoreanLocalization.Add("16256e8815004da996bfaba73428b14e", "Cold Immunity", "냉기 면역", false);
      KoreanLocalization.Add(null, "College Student", "대학생", false);
      KoreanLocalization.Add(null, "The College Student gains a +2 bonus to all attributes.\nIf the character already has the class skill, {g|Encyclopedia:Weapon_Proficiency}weapon proficiency{/g} or armor proficiency granted by the selected background from her class during character creation, then the corresponding {g|Encyclopedia:Bonus}bonuses{/g} from background change to a +1 competence bonus in case of skills, a +1 enhancement bonus in case of weapon proficiency and a -1 Armor {g|Encyclopedia:Check}Check{/g} {g|Encyclopedia:Penalty}Penalty{/g} reduction in case of armor proficiency.", "대학생은 모든 능력치에 +2 보너스를 받습니다.\n캐릭터 생성 시 클래스에서 이미 얻은 클래스 기술, {g|Encyclopedia:Weapon_Proficiency}무기 숙련{/g} 또는 갑옷 숙련을 이 배경에서 다시 얻는다면, 해당 배경의 {g|Encyclopedia:Bonus}보너스{/g}는 다음과 같이 바뀝니다. 기술에는 +1 능숙 보너스를, 무기 숙련에는 +1 강화 보너스를 받으며, 갑옷 숙련의 경우 갑옷 {g|Encyclopedia:Check}판정{/g} {g|Encyclopedia:Penalty}불이익{/g}이 1 감소합니다.", true);
      KoreanLocalization.Add("e771dd9e8fd8404f9ffc0db211c7f774", "You gain immunity to compulsion effects.", "강제 효과에 면역이 됩니다.", true);
      KoreanLocalization.Add("ef049df6c2b2413a92830386fc63952c", "Compulsion Immunity", "강제 면역", false);
      KoreanLocalization.Add("7abbe05292cd403bb32fc51aea4b31e7", "You gain immunity to confusion.", "혼란에 면역이 됩니다.", true);
      KoreanLocalization.Add("4ac57ec2279a4432833cc60414feae2d", "Confusion Immunity", "혼란 면역", false);
      KoreanLocalization.Add("68c51794385e4ceb883f509f4dc1999a", "Your attacks have Corrosive. They deal an additional 1d6 acid damage.", "당신의 공격에 부식 효과가 적용되어 1d6의 추가 산성 피해를 입힙니다.", false);
      KoreanLocalization.Add("34a48453873f49d7ba07f6da307e535f", "Corrosive Weapon", "부식 무기", false);
      KoreanLocalization.Add("f11c30e434094033b009cd6075aa60c1", "Allies within 40 feet of the Overlord has a +4 profane bonus to attack, damage, AC and saving throws. Their attacks are treated as evil for the purpose of overcoming {g|Encyclopedia:Damage_Reduction}damage reduction{/g}.", "패왕의 40피트 이내 아군은 명중, 피해, 방어도와 내성 굴림에 +4 불경 보너스를 받습니다. 이들의 공격은 {g|Encyclopedia:Damage_Reduction}피해 감소{/g}를 극복할 때 악 성향으로 취급됩니다.", false);
      KoreanLocalization.Add("cafc4acc0b9a41a1ba19588aa9ae059c", "Corrupt Aura", "타락의 오라", false);
      KoreanLocalization.Add("7d4a4b36efc943a0946f9350b06e7cb0", "This character has a +4 profane bonus to attack, damage, AC and saving throws. Their attacks are treated as evil for the purpose of overcoming {g|Encyclopedia:Damage_Reduction}damage reduction{/g}.", "이 캐릭터는 명중, 피해, 방어도와 내성 굴림에 +4 불경 보너스를 받습니다. 이 캐릭터의 공격은 {g|Encyclopedia:Damage_Reduction}피해 감소{/g}를 극복할 때 악 성향으로 취급됩니다.", false);
      KoreanLocalization.Add("f825e95ca7224792b440534fdecb4cb6", "You gain immunity to cowering.", "위축에 면역이 됩니다.", true);
      KoreanLocalization.Add("cac133aa31ff4a8e868c84ae96db0e1d", "Cowering Immunity", "위축 면역", false);
      KoreanLocalization.Add("78540e10d8dc4eb7825e33817bfc4ca7", "You gain immunity to critical hits.", "치명타에 면역이 됩니다.", true);
      KoreanLocalization.Add("b4157ad678cc4ec0b21c1f9f034ef7a2", "Critical hit Immunity", "치명타 면역", false);
      KoreanLocalization.Add("4947f41eff04405b97414a61a7ca0814", "You gain immunity to curses.", "저주에 면역이 됩니다.", true);
      KoreanLocalization.Add("9d5fc6297aef4a55b9468829f19f457b", "Curse Immunity", "저주 면역", false);
      KoreanLocalization.Add("88ce6708129c4eb085aec3bce1f885c4", "You emit an aura of darkness that cause enemies to become uneasy and vulnerable.\nEnemies within 40 feet take a –4 penalty on AC and saving throws.", "적을 불안과 무력감에 빠뜨리는 어둠의 오라를 내뿜습니다.\n40피트 이내의 적은 방어도와 내성 굴림에 -4 불이익을 받습니다.", false);
      KoreanLocalization.Add("16ac8039b964437484ba38272ce0e729", "Dark Aura", "암흑의 오라", false);
      KoreanLocalization.Add("50fd6c2444654a099aec947454658d06", "This creature has a –4 penalty on AC and saving throws.", "이 크리처는 방어도와 내성 굴림에 -4 불이익을 받습니다.", false);
      KoreanLocalization.Add("479565f4dcaf41e98d9431c35ded4e1d", "You gain resistance against all elements (acid, cold, electricity, fire, and sonic) equal to 10 + 2 times your character level. Your physical attacks are treated as evil for the purpose of overcoming {g|Encyclopedia:Damage_Reduction}damage reduction{/g}.", "모든 원소(산성, 냉기, 전격, 화염, 음파)에 대해 10 + 캐릭터 레벨의 2배만큼 저항을 얻습니다. 당신의 물리 공격은 {g|Encyclopedia:Damage_Reduction}피해 감소{/g}를 극복할 때 악 성향으로 취급됩니다.", true);
      KoreanLocalization.Add("3b8674fff99044e692caa349d3551613", "Dark Energy Condensation", "암흑 에너지 응축", false);
      KoreanLocalization.Add("d1c3be6eef4144fe9f312165dbd61384", "You gain immunity to daze.", "몽롱에 면역이 됩니다.", true);
      KoreanLocalization.Add("c015af49840441cd9c652303a435a790", "Dazed Immunity", "몽롱 면역", false);
      KoreanLocalization.Add("b98843ee55e14042a242e7ff697c6ab2", "You gain immunity to the dazzled condition.", "눈부심에 면역이 됩니다.", true);
      KoreanLocalization.Add("198a098e03e44dfe91cf505a769527fb", "Dazzled Immunity", "눈부심 면역", false);
      KoreanLocalization.Add("f0fa488de27a4c5f872e513ab4b91c73", "You gain immunity to death effects.", "죽음 효과에 면역이 됩니다.", true);
      KoreanLocalization.Add("3fe69265e86940bc9485f9f9459ac7fc", "Death Immunity", "죽음 면역", false);
      KoreanLocalization.Add("22e0e7c648784298bf7d903c1c67d6b8", "At 10th level, the Deathsnatcher gains 2 additional uses of Animate Dead per day.", "10레벨에 죽음강탈자가 하루에 시체 일으키기를 사용할 수 있는 횟수가 2회 증가합니다.", true);
      KoreanLocalization.Add("5c8e155d72d44bdeb93c06247f75fed9", "Animate Dead — Additional Uses", "시체 일으키기: 추가 사용", false);
      KoreanLocalization.Add("794c4ad608234a36b0f4acd9b0bea827", "At 7th level, the Deathsnatcher gains Animate Dead as a spell-like ability 3 times per day.", "7레벨에 죽음강탈자는 시체 일으키기를 하루에 3회 주문 유사 능력으로 사용할 수 있습니다.", true);
      KoreanLocalization.Add("b8072c4f87fc485dba68a317c4a5ac3b", "This bipedal jackal has vulture wings and a rat tail ending in a scorpion’s stinger. Each of its four arms ends in a clawed hand.", "두 발로 걷는 자칼의 몸에 독수리 날개와 쥐 꼬리가 달려 있고, 꼬리 끝에는 전갈의 독침이 있습니다. 네 팔 끝에는 날카로운 발톱이 돋은 손이 달려 있습니다.", false);
      KoreanLocalization.Add("5f57888e441e4f28ae2a076e08dbcca4", "Deathsnatcher", "죽음강탈자", false);
      KoreanLocalization.Add("852e6147f6ae48b384c6fc42a020ed1b", "At 1st level, the Deathsnatcher gains Command Undead as a spell-like ability 10 times per day.", "1레벨에 죽음강탈자는 언데드 명령을 하루에 10회 주문 유사 능력으로 사용할 수 있습니다.", true);
      KoreanLocalization.Add("add4a8960fe8465283d207f180f10fb4", "At 13th level, the Deathsnatcher gains Create Undead as a spell-like ability once per day.", "13레벨에 죽음강탈자는 언데드 생성을 하루에 1회 주문 유사 능력으로 사용할 수 있습니다.", true);
      KoreanLocalization.Add("e8f74709fc0d4aa2b05ada364ba0c24f", "A creature with the fast healing special ability regains hit points at an exceptional rate. Fast healing continues to function even if the creature is unconscious or has less than zero hit points, as long as it's alive. If the creature dies, the effects of fast healing end immediately.", "빠른 치유 능력을 지닌 크리처는 생명력을 매우 빠르게 회복합니다. 살아 있는 한 의식을 잃거나 생명력이 0 미만이 되어도 빠른 치유가 계속됩니다. 크리처가 죽으면 이 효과는 즉시 끝납니다.", true);
      KoreanLocalization.Add("d9871b0a70024cb781fd5f27a50994ad", "Fast Healing 10", "빠른 치유 10", false);
      KoreanLocalization.Add("45673f9071f64f928ceb21aae3a5361c", "Deathsnatchers dwell amid the ruins of fallen civilizations, where they play at being godlings worshiped by undead slaves. Though self-aggrandizing, deathsnatchers are known to give homage to (and claim descent from) the various demon lords of darkness, the desert, and undeath.\n{g|Encyclopedia:Size}Size{/g}: Tiny\n{g|Encyclopedia:Speed}Speed{/g}: 30 ft.\n{g|Encyclopedia:Armor_Class}AC{/g}: +10 natural armor\n{g|Encyclopedia:Attack}Attack{/g}: 1 bite ({g|Encyclopedia:Dice}2d6{/g}), 4 claws (1d6), 1 sting (1d4)\n{g|Encyclopedia:Ability_Scores}Ability scores{/g}: {g|Encyclopedia:Strength}Str{/g} 17, {g|Encyclopedia:Dexterity}Dex{/g} 25, {g|Encyclopedia:Constitution}Con{/g} 28, {g|Encyclopedia:Intelligence}Int{/g} 16, {g|Encyclopedia:Wisdom}Wis{/g} 21, {g|Encyclopedia:Charisma}Cha{/g} 24\nAt 4th level size becomes Medium, Str +6, Dex -4, Con +4, +6 natural armor, gains pounce.", "죽음강탈자는 몰락한 문명의 폐허에 살며, 언데드 노예들의 숭배를 받는 작은 신 행세를 합니다. 이처럼 자만심이 강하지만, 어둠과 사막, 불사의 힘을 관장하는 여러 데몬 군주에게 경의를 표하며 자신이 그들의 후손이라고 주장하기도 합니다.\n{g|Encyclopedia:Size}크기{/g}: 극소형\n{g|Encyclopedia:Speed}이동 속도{/g}: 30피트\n{g|Encyclopedia:Armor_Class}방어도{/g}: 자연 갑옷 +10\n{g|Encyclopedia:Attack}공격{/g}: 물기 1회({g|Encyclopedia:Dice}2d6{/g}), 발톱 4회(1d6), 독침 1회(1d4)\n{g|Encyclopedia:Ability_Scores}능력치{/g}: {g|Encyclopedia:Strength}힘{/g} 17, {g|Encyclopedia:Dexterity}민첩{/g} 25, {g|Encyclopedia:Constitution}건강{/g} 28, {g|Encyclopedia:Intelligence}지능{/g} 16, {g|Encyclopedia:Wisdom}지혜{/g} 21, {g|Encyclopedia:Charisma}매력{/g} 24\n4레벨에 중형으로 성장하고, 힘 +6, 민첩 -4, 건강 +4, 자연 갑옷 +6을 얻으며 덮치기가 가능해집니다.", true);
      KoreanLocalization.Add("542d97deb0314574b279396caf1a7c21", "At 16th level, the Deathsnatcher gains Finger of Death as a spell-like ability once per day.", "16레벨에 죽음강탈자는 죽음의 손가락을 하루에 1회 주문 유사 능력으로 사용할 수 있습니다.", true);
      KoreanLocalization.Add("ac6f0977689c4935a775f46a6c9fd078", "The Deathsnatcher has +16 natural armor bonus to AC.", "죽음강탈자는 방어도에 +16 자연 갑옷 보너스를 받습니다.", true);
      KoreanLocalization.Add("13d2548e7d06400eb58f0420cb157001", "Deathsnatcher Armor", "죽음강탈자의 갑옷", false);
      KoreanLocalization.Add("d6f3be2935a643a6a599728441bd21ae", "The Deathsnatcher's sting attack becomes poisonous and inflicts 1d4 Constitution damage if the enemy fails a DC 28 Fortitude save.", "죽음강탈자의 독침 공격에 독이 깃듭니다. 적이 인내 내성에 실패하면 1d4의 건강 피해를 입히는 독에 중독됩니다.", true);
      KoreanLocalization.Add("95943d4c726543eb9cf6acbdaf0044bd", "Deathsnatcher Poison Sting", "죽음강탈자의 독침", false);
      KoreanLocalization.Add("0308e3bf16e04f42b07deb4216c25e34", "The Deathsnatcher is immune to negative energy and deaths effects, and has cold and fire resistance 30. It also has spell resistance equal to 10 + the Deathsnatcher's level.", "죽음강탈자는 음에너지와 죽음 효과에 면역이며, 냉기 저항과 화염 저항 30을 지닙니다. 또한 10 + 죽음강탈자 레벨만큼 주문 저항을 얻습니다.", true);
      KoreanLocalization.Add("975390bba3614b9aba8a01ea3cef24c3", "Deathsnatcher Resistances", "죽음강탈자의 저항", false);
      KoreanLocalization.Add("1a5a0b742a5240c3925e8c01291b4774", "The Deathsnatcher matures at 4th level. When this occurs, the Deathsnatcher’s natural armor bonus to its AC increases by 6, and gains the following ability scores adjustments: Str +6, Dex –4, Con +4.", "죽음강탈자는 4레벨에 성체가 됩니다. 이때 방어도에 적용되는 자연 갑옷 보너스가 6 증가하며, 능력치가 힘 +6, 민첩 -4, 건강 +4만큼 변합니다.", false);
      KoreanLocalization.Add("84e35dce1f124acab20e76290cf2194c", "Baby Deathsnatcher", "새끼 죽음강탈자", false);
      KoreanLocalization.Add("7d83f4d99e24481093decefb679dc90a", "At 20th level, the Deathsnatcher becomes a master of the undead.\nCommand Undead has unlimited uses.\nAnimate Dead has unlimited uses.\nCreate Undead has 2 additional uses per day.\nFinger of Death has 2 additional uses per day.", "20레벨에 죽음강탈자는 언데드의 지배자가 됩니다.\n언데드 명령의 사용 횟수 제한이 사라집니다.\n시체 일으키기의 사용 횟수 제한이 사라집니다.\n언데드 생성의 하루 사용 횟수가 2회 증가합니다.\n죽음의 손가락의 하루 사용 횟수가 2회 증가합니다.", true);
      KoreanLocalization.Add("451b9222ed77452bb95b784173802d26", "Undead Master", "언데드 지배자", false);
      KoreanLocalization.Add("b096841a085449369dfc7c06a4953626", "Gain the spells of a Demon.", "데몬의 주문을 얻습니다.", true);
      KoreanLocalization.Add("f1749ba66f1b425ba53072969a8b89cb", "Mythic Demon Spells", "신화 데몬 주문", false);
      KoreanLocalization.Add("f10c538eedde4e139376528357186ef7", "Wings (Demonic)", "날개 (데몬)", false);
      KoreanLocalization.Add("250d97b5da9f40f49f9fb17dbfe037ea", "Your channel energy, cure spells, and restore HP abilities heal the maximum amount.\nOnce per day, when your {g|Encyclopedia:HP}HP{/g} drops to 0, you are resurrected to full health. Allies within 40 feet are then restored to full health while enemies instantly die.", "에너지 전달, 치료 주문, 생명력 회복 능력의 회복량이 최대가 됩니다.\n휴식마다 한 번, 사망하면 {g|Encyclopedia:HP}생명력{/g}을 모두 회복한 상태로 부활합니다. 이어서 40피트 이내 아군의 생명력을 모두 회복시키고 적을 즉사시킵니다.", false);
      KoreanLocalization.Add("682f97897cbe41a68401c15de7902e8d", "Deus Ex Machina", "데우스 엑스 마키나", false);
      KoreanLocalization.Add("ebe5f48873de448880ba18abd25efbc9", "Wings (Devilish)", "날개 (데빌)", false);
      KoreanLocalization.Add("22fd7f1a11d14c608cb53468fc285278", "Wings", "날개", false);
      KoreanLocalization.Add("49392363dd7c4846847ce3445dfef36c", "You gain immunity to disease.", "질병에 면역이 됩니다.", true);
      KoreanLocalization.Add("64d3558e47a64fe69e67037a168de153", "Disease Immunity", "질병 면역", false);
      KoreanLocalization.Add("77f0e297aecf42aea684b8e073e223e5", "You emit an aura of divinity that cause enemies to be overcome with feelings of futility.\nEnemies within 40 feet take a –4 penalty on all attributes.", "적을 깊은 무력감에 빠뜨리는 신성한 오라를 내뿜습니다.\n40피트 이내의 적은 모든 능력치에 -4 불이익을 받습니다.", false);
      KoreanLocalization.Add("2c7bd95ccdfd422992edc5c646f16716", "Divine Aura", "신성한 오라", false);
      KoreanLocalization.Add("f004286c7f8b45c5b40ab68a7a916db9", "This creature has a –4 penalty on all attributes.", "이 크리처는 모든 능력치에 -4 불이익을 받습니다.", false);
      KoreanLocalization.Add("d648480ce8944192a6056a4b3f03f12d", "Underpowered Ability — Dodge Master", "하위 능력: 회피의 달인", false);
      KoreanLocalization.Add(null, "Dread Knight Legacy - Dread Lord", "드레드 나이트 전승: 공포의 군주", false);
      KoreanLocalization.Add(null, "*Blinks and slowly backs away*, Uhm are you certain you want to play this? I mean Dread Knights are kind of evil, you know? \nAs in the they are the opposite of anything a paladin represents...", "*눈을 깜빡이며 슬그머니 물러선다* 저기, 정말 이걸 고르시겠어요? 드레드 나이트는 좀 사악한 부류인데요?\n그러니까, 팔라딘이 추구하는 모든 것의 정반대라고요…", true);
      KoreanLocalization.Add("c97e9fd28b4b4f6595d8d5b613112fe8", "As a swift action, you can coat your weapon with a special drow poison. Enemies hit by the poisoned weapon will need to make a Fortitude save or become unconscious for 1 minute. This fortitude save is equal to 10 + your character level + your Intelligence modifier.", "신속 행동으로 무기에 특제 드로우 독을 바릅니다. 독을 바른 무기에 명중당한 적은 인내 내성에 실패하면 1분 동안 의식을 잃습니다. 내성 난이도는 10 + 캐릭터 레벨 + 지능 수정치입니다.", true);
      KoreanLocalization.Add("beb2115ad61940fa863ab8baf47be81d", "Drow Poison causes their target to become unconsious on a failed fortitude save.", "드로우 독에 중독된 대상은 인내 내성에 실패하면 의식을 잃습니다.", true);
      KoreanLocalization.Add("4cb0f40df78c477d8c122c2ac12a012d", "Drow Poison", "드로우 독", false);
      KoreanLocalization.Add("9029303643784721a20d86d41cd3b558", "You were a nature lover in your previous world, but you lived in a polluted and crowded city that stifled your connection to the natural world. \nYou dreamed of escaping to a place where you could be free and wild, and one day you got your wish. \nYou have been reincarnated in a world where nature is abundant and diverse, and you have learned how to tap into its primal magic. \nYou can cast spells that manipulate the elements, summon creatures, and enhance your own abilities. \nYou are a protector of nature and a friend to all living.", "당신은 전생에도 자연을 사랑했지만, 오염되고 혼잡한 도시에서 살며 자연과의 교감을 억눌러야 했습니다.\n자유롭게 야성을 누릴 곳으로 떠나기를 꿈꾸던 어느 날, 그 소원이 이루어졌습니다.\n풍요롭고 다채로운 자연이 가득한 세계에 환생한 당신은 자연의 원초적인 마력을 끌어내는 법을 배웠습니다.\n원소를 다루고, 크리처를 소환하고, 자신의 능력을 강화하는 주문을 시전할 수 있습니다.\n당신은 자연의 수호자이자 모든 생명의 벗입니다.", true);
      KoreanLocalization.Add("8faad5724a394ee691f27a30826218bf", "Druid Legacy - Nature Mage", "드루이드 전승: 자연의 마법사", false);
      KoreanLocalization.Add("389de8c879844d59a2ac891ccc50db36", "After reincarnating into Golarion, some protagonists use their newfound abilities to look cool and stylish. Their attacks become flashy and myriad, moving so fast that side characters would be lucky to even see the Afterimage.", "골라리온에 환생한 주인공 중에는 새로 얻은 힘을 오직 멋을 부리는 데 쏟는 이들도 있습니다. 현란한 공격을 쉴 새 없이 퍼붓고, 조연들은 그 잔상조차 보기 힘들 만큼 빠르게 움직입니다.", false);
      KoreanLocalization.Add("7e85ee18b8d54b1b9a6b7dc3012c7cff", "Edge Lord", "중2병 군주", false);
      KoreanLocalization.Add("94876eb6a960475ebc7c8aebe6f6e82a", "To truly look cool and stylish only a melee focus will really do...", "진정으로 멋을 부리려면 역시 근접전만 한 것이 없습니다…", true);
      KoreanLocalization.Add("7130f87fda5d442797d49c51a19ea9be", "Edgy Legacy", "중2병의 전승", false);
      KoreanLocalization.Add("d4d92b8595a34976b10fc7f3735d96c8", "The Edge Lord is proficient with all simple, martial, and exotic weapons as well as light and medium armor. They can cast {g|Encyclopedia:Spell}spells{/g} from this class while wearing armor without incurring the normal {g|Encyclopedia:Spell_Fail_Chance}arcane spell failure chance{/g}, but they incur the normal arcane spell failure chance for arcane spells received from other classes.", "중2병 군주는 모든 단순 무기, 군용 무기, 특수 무기와 경장·평장 갑옷에 숙련됩니다. 갑옷을 입어도 이 클래스에서 얻은 {g|Encyclopedia:Spell}주문{/g}에는 일반적인 {g|Encyclopedia:Spell_Fail_Chance}비전 주문 실패 확률{/g}이 적용되지 않습니다. 다른 클래스에서 얻은 비전 주문에는 정상적으로 적용됩니다.", true);
      KoreanLocalization.Add("aa741ef1ab1b413a95c98470ff83ef6a", "Edge Lord Proficiencies", "중2병 군주의 숙련", false);
      KoreanLocalization.Add("a887e031b4cf425083015e4bba6fb590", "You gain immunity to a specific condition or effect.", "특정 상태나 효과에 면역이 됩니다.", false);
      KoreanLocalization.Add("9323c9b11dee415dad5a3dfdc32aff63", "Effect Immunity", "효과 면역", false);
      KoreanLocalization.Add("b127941d09764b1080c1a001b34a6724", "You gain immunity to Electricity.", "전격에 면역이 됩니다.", true);
      KoreanLocalization.Add("298b0ee0ddb641ceb1ebd81031355992", "Electricity Immunity", "전격 면역", false);
      KoreanLocalization.Add("1f30a67ee4154ce396b7eeca77a30609", "At 5th level, you are able to condense your channelled energy to form a protective layer around you, giving you resistance against elemental damage.", "5레벨에 전달한 에너지를 몸 주위의 보호막으로 응축하여, 원소 피해에 대한 저항을 얻습니다.", true);
      KoreanLocalization.Add("6c4252045b394ab8b007c629c51cd22e", "Energy Condensation", "에너지 응축", false);
      KoreanLocalization.Add("e0e2fb279b5440ebb615ea7fb7f42120", "You gain energy immunity of a particular type.", "특정 유형의 에너지에 면역이 됩니다.", true);
      KoreanLocalization.Add("fa1c9cd2707b47c3be615a641fd48a21", "Energy Immunity", "에너지 면역", false);
      KoreanLocalization.Add("bcb1b8093ce14b7b903fd36c3d6e5611", "You gain immunity to the entangled condition.", "얽힘에 면역이 됩니다.", true);
      KoreanLocalization.Add("9841bda321fe4485877d58f88565284c", "Entangled Immunity", "얽힘 면역", false);
      KoreanLocalization.Add("ed823d959d7a408abba90e7be10edc0c", "Your primary weapon gains the holy and radiant enchantments. Your attack range is increased by 40 feet.", "주무기에 성스러움과 광휘 인챈트가 부여됩니다. 공격 사거리가 40피트 증가합니다.", false);
      KoreanLocalization.Add("533f76d24b4e4edfa797b52395d1c391", "Excalibur", "엑스칼리버", false);
      KoreanLocalization.Add("464dd190f07a49ee966288ec9e75f270", "Exceptional feats are feats that no ordinary NPC possess.\nSource: Isekai Mod", "평범한 NPC라면 가질 수 없는 비범한 특기입니다.\n출처: 이세계 모드", false);
      KoreanLocalization.Add("b0ed1bf6322241b49b4c23a25df7f440", "Exceptional Feats", "비범한 특기", false);
      KoreanLocalization.Add("980700e7ece547e294c199ef30de8e31", "Your summons become more powerful as you increase your level.", "레벨이 오를수록 소환수가 더욱 강해집니다.", false);
      KoreanLocalization.Add("31cfe27695664dd8b42fac9e55e27edd", "Exceptional Summoning", "비범한 소환", false);
      KoreanLocalization.Add("207dedc01af54146ba529ac7d82e4273", "Your primary and secondary weapons have an additional enchantment.", "주무기와 보조무기에 추가 인챈트가 부여됩니다.", false);
      KoreanLocalization.Add("f79f5d30d3214436bac6bf3b36bcf9fc", "Exceptional Weapon", "비범한 무기", false);
      KoreanLocalization.Add("bfc205d07a904d7ebc3db0bce9a3cf83", "You gain immunity to exhaustion.", "탈진에 면역이 됩니다.", true);
      KoreanLocalization.Add("79034234c7bc45459ba123bac7ab3e0f", "Exhausted Immunity", "탈진 면역", false);
      KoreanLocalization.Add("0024cbd23e134cefa1c8577fcc5f0b08", "You become proficient with all Exotic Weapons.", "모든 특수 무기에 숙련됩니다.", true);
      KoreanLocalization.Add("fb9ab7dac48c425fa8bb573f8f09f66c", "Exotic Weapon Proficiency", "특수 무기 숙련", false);
      KoreanLocalization.Add("f7984fb1efb245efa75ad9a80344c200", "You gain an additional Special Power.", "특수 능력을 하나 더 얻습니다.", true);
      KoreanLocalization.Add("dd6a8690a83c4e1b8e3df6784271714e", "Extra Special Power", "추가 특수 능력", false);
      KoreanLocalization.Add("dadd346477da455887f04fa4e6fc50c3", "You gain 1 additional {g|Encyclopedia:Attack}attack{/g}. This also applies to your off-hand weapon if you are wielding a second weapon.", "{g|Encyclopedia:Attack}공격{/g} 횟수를 한 번 추가로 얻습니다. 쌍수 무기를 사용한다면 보조무기에도 적용됩니다.", true);
      KoreanLocalization.Add("46c50228b9b64afd8f718657727260b3", "Extra Strike", "추가 타격", false);
      KoreanLocalization.Add("58c9a4992cf34fe7b8a6a2f75692e573", "Allies within 40 feet of you gain a {g|Encyclopedia:Bonus}bonus{/g} to your {g|Encyclopedia:Speed}speed{/g} equal to 5 times your character level.", "40피트 이내 아군은 {g|Encyclopedia:Speed}이동 속도{/g}에 당신의 캐릭터 레벨의 5배만큼 {g|Encyclopedia:Bonus}보너스{/g}를 받습니다.", false);
      KoreanLocalization.Add("ada5a344a59a4cfeb91056c46132b10f", "Extreme Speed", "극한의 속도", false);
      KoreanLocalization.Add("6577228d9a79403ea311dd01609249d6", "This creature gains a {g|Encyclopedia:Bonus}bonus{/g} to their {g|Encyclopedia:Speed}speed{/g}.", "이 크리처는 {g|Encyclopedia:Speed}이동 속도{/g}에 {g|Encyclopedia:Bonus}보너스{/g}를 받습니다.", false);
      KoreanLocalization.Add("713b61e836f04b48a2cda63689b4397f", "Attacks always miss you.", "당신을 향한 공격은 항상 빗나갑니다.", true);
      KoreanLocalization.Add("beaa87f1ec5d4457b6502d9db32ab876", "Faster than Light", "빛보다 빠르게", false);
      KoreanLocalization.Add("5b59ae7ecb794bd6980fc5ddfabb1a4c", "You gain immunity to fatigue.", "피로에 면역이 됩니다.", true);
      KoreanLocalization.Add("b6f2a2ce90e943978333e1d577b04f05", "Fatigue Immunity", "피로 면역", false);
      KoreanLocalization.Add("da61f63db5ff45d69ca65b72d23cdf88", "You gain immunity to fear effects.", "공포 효과에 면역이 됩니다.", true);
      KoreanLocalization.Add("d326efa6962144fc9402fed3a8dd7246", "Fear Immunity", "공포 면역", false);
      KoreanLocalization.Add("be4c56958d6c4baa911d4a66b25b2b05", "Your summoned creatures have 2 additional attacks and gain a +10 bonus to speed. It also gains 1d6 sneak attack per character level.", "소환수는 공격 횟수를 두 번 추가로 얻고 이동 속도에 +10 보너스를 받습니다. 또한 당신의 캐릭터 레벨당 1d6의 암습 피해를 얻습니다.", false);
      KoreanLocalization.Add("8b740acb0a664e9e94ec95ee25c7cf35", "Ferocious Summoning", "흉포한 소환", false);
      KoreanLocalization.Add("cf457e94ff244451bdb5a2bf2b1b3f23", "This creature has 2 additional attacks and gains a +10 bonus to speed. It also gains 1d6 sneak attack per character level.", "이 크리처는 공격 횟수를 두 번 추가로 얻고 이동 속도에 +10 보너스를 받습니다. 또한 소환자의 캐릭터 레벨당 1d6의 암습 피해를 얻습니다.", false);
      KoreanLocalization.Add("7ea9d4415a70463ca6832816f60fcfce", "What is cooler than swinging a sword at a speed the eye can barely follow?\nSwinging a massive two handed sword at that speed and watching your enemy as he runs in fear at the sheer size of your weapon and the speed at which you wield it.\nEven better if it is an elven blade or estoc so you can stack sneak attack on top for some truly critical hits...", "눈으로 쫓기 힘든 속도로 검을 휘두르는 것보다 더 멋진 게 뭘까요?\n바로 거대한 양손검을 그 속도로 휘두르는 겁니다. 적은 그 크기와 속도에 질려 도망치겠지요.\n엘프 곡도나 에스톡이라면 더 좋습니다. 암습까지 얹어서 정말 치명적인 일격을 날릴 수 있으니까요…", true);
      KoreanLocalization.Add("c9af834165db45bbafac3632b4ddedfb", "Fighter Legacy - Two Handed Fighter", "파이터 전승: 양손 무기 전사", false);
      KoreanLocalization.Add("343b59135a4348db8cec8fd9391b9e4e", "Sure others make fun of you for being basic.\nWhat they fail to understand is that they are the basic ones, they play an auto optimized build that only allows them some little choice on what feature to use in each fight.\nYou are carefully crafted at each level to ensure the optimal combination of feats.\nThey completely fail to see the hours of planning it takes to ensure that when the time for battle comes your attack will always do the optimum damage, even if it is just repeatedly smashing the hammer into the enemies face.", "다들 당신을 평범한 파이터라며 놀리겠지요.\n하지만 정말 평범한 건 그들입니다. 알아서 최적화되는 빌드를 따라가며, 전투마다 쓸 능력 몇 개만 고르면 그만이니까요.\n당신은 레벨이 오를 때마다 최적의 특기 조합을 직접 설계합니다.\n그들은 전투가 시작되면 언제나 최대의 피해를 입히도록 준비하는 데 얼마나 오랜 계획이 필요한지 모릅니다. 결국 적의 얼굴에 망치를 연달아 내리찍을 뿐이라 해도 말이지요.", true);
      KoreanLocalization.Add("deaa017e91e14af3809777de7f350258", "Fighter Legacy - Basic Fighter", "파이터 전승: 정통 전사", false);
      KoreanLocalization.Add("5450293fad0147a783ede8fefd93d130", "You are the shield guarding your party.\n With your trusty shield in hand no enemy can break your defense.\nJust let the fool's try...", "당신은 동료들을 지키는 방패입니다.\n믿음직한 방패를 손에 든 이상, 어떤 적도 당신의 방어를 뚫을 수 없습니다.\n어리석은 놈들, 어디 한번 덤벼 보라지요…", true);
      KoreanLocalization.Add("4df27257d75a44938fa70f082a0532a2", "Fighter Legacy - Guardian Shield", "파이터 전승: 수호의 방패", false);
      KoreanLocalization.Add("c4cd09e4d3ec41c9bfc5b56c6014b40a", "You gain immunity to Fire.", "화염에 면역이 됩니다.", true);
      KoreanLocalization.Add("970b7c8a5e0b488f98fc8758dfb6080d", "Fire Immunity", "화염 면역", false);
      KoreanLocalization.Add("8a339939f7cc44e0baec8d3e5d593887", "Your attacks have Flaming. They deal an additional 1d6 fire damage.", "당신의 공격에 화염 효과가 적용되어 1d6의 추가 화염 피해를 입힙니다.", false);
      KoreanLocalization.Add("86fd31561c984904a5a1eb8b618743b1", "Flaming Weapon", "화염 무기", false);
      KoreanLocalization.Add("bdb4dd35a5e94938adbe89ff10570951", "Your summoned creatures gain a +10 bonus to hit points per character level and a +1 bonus to all attributes per character level.", "소환수는 당신의 캐릭터 레벨당 최대 생명력에 +5 보너스를, 모든 능력치에 +1 보너스를 받습니다.", false);
      KoreanLocalization.Add("81e76d49e8f748cca8397aa3ba504db9", "Forbidden Summoning", "금단의 소환", false);
      KoreanLocalization.Add("9e2a4ac6bcb64f7e98f316e03f305807", "This creature gains a +10 bonus to maximum Hit Points per character level and a +1 bonus to all attributes per character level.", "이 크리처는 소환자의 캐릭터 레벨당 최대 생명력에 +5 보너스를, 모든 능력치에 +1 보너스를 받습니다.", false);
      KoreanLocalization.Add("93e8122c42ad42eea553345845569377", "You emit an aura of friendship that cause enemies to subconsciously hold back.\nEnemies within 40 feet take a –4 penalty on attack and damage rolls.", "적이 무의식적으로 힘을 빼게 만드는 우호의 오라를 내뿜습니다.\n40피트 이내의 적은 명중 굴림과 피해 굴림에 -4 불이익을 받습니다.", false);
      KoreanLocalization.Add("bafc48c4f4c643a18c801bf2fbc1960e", "Friendly Aura", "우호의 오라", false);
      KoreanLocalization.Add("27d57affa2344cda8716f7705325b425", "This creature has a –4 penalty on attack {g|Encyclopedia:Dice}rolls{/g}.", "이 크리처는 명중 {g|Encyclopedia:Dice}굴림{/g}과 피해 굴림에 -4 불이익을 받습니다.", false);
      KoreanLocalization.Add("e4967a07507e4009a61ff6fefb2a0360", "You gain immunity to the frightened condition.", "겁먹음에 면역이 됩니다.", true);
      KoreanLocalization.Add("43c9ae16aa614726bf4d8efad7aded08", "Frightened Immunity", "겁먹음 면역", false);
      KoreanLocalization.Add("56b81beacaf748559d48e9454647f397", "Your attacks have Frost. They deal an additional 1d6 cold damage.", "당신의 공격에 냉기 효과가 적용되어 1d6의 추가 냉기 피해를 입힙니다.", false);
      KoreanLocalization.Add("5a438826291d466fbad2b90ae4a2db8d", "Frost Weapon", "냉기 무기", false);
      KoreanLocalization.Add("c33ccdc66cba4eea9cbb731a0b5747ed", "Your attacks ignore concealment and are treated as adamantite for the purpose of overcoming {g|Encyclopedia:Damage_Reduction}damage reduction{/g}.", "당신의 공격은 은폐를 무시하며, {g|Encyclopedia:Damage_Reduction}피해 감소{/g}를 극복할 때 아다만틴으로 취급됩니다.", true);
      KoreanLocalization.Add("989a1b13980c420cb94cb3fe5b027c4c", "Gamma Strike", "감마 스트라이크", false);
      KoreanLocalization.Add("165c8d1177db41ee8b52d22bc49f25da", "Wings (Ghostly)", "날개 (유령)", false);
      KoreanLocalization.Add("0f03d214ae5e422e929e765ee2f6ab04", "You are talented in all skills and professions.\nYou gain a +4 competence bonus to all skills and you always take the higher of two d20 rolls.", "당신은 모든 기술과 직업에 재능을 타고났습니다.\n모든 기술에 +4 능숙 보너스를 받으며, d20을 굴릴 때마다 두 번 굴려 더 높은 결과를 사용합니다.", true);
      KoreanLocalization.Add("85ea0803ea92471aba3cc40377f83b2d", "Gifted", "천부적 재능", false);
      KoreanLocalization.Add("974420e2cf10498e94e8b494cade3ab8", "Rather than wandering aimlessly, collecting harems, or defeating demon lords, some protagonists decide to become gods. They sacrifice their special powers to gain powerful auras and a journey towards godhood.", "정처 없이 떠돌거나 하렘을 모으거나 마왕을 무찌르는 대신, 신이 되기로 결심한 주인공도 있습니다. 신황은 특수 능력을 포기하는 대신 강력한 오라를 얻고, 신격에 이르는 여정을 시작합니다.", false);
      KoreanLocalization.Add("0042c1cce90e4ba09b4da23c75dc565d", "God Emperor", "신황", false);
      KoreanLocalization.Add("234567c753494963b674e2186004c686", "Regal Aura", "제왕의 오라", false);
      KoreanLocalization.Add("79264deaf865476bb8460aa62fadaabd", "At 3rd level, the God Emperor is able to choose between channeling positive energy or negative energy.", "3레벨에 신황은 양에너지 전달과 음에너지 전달 중 하나를 선택합니다.", true);
      KoreanLocalization.Add("22e6d0a97c404460abf3a82bfbcea095", "Channel Energy", "에너지 전달", false);
      KoreanLocalization.Add("a6d348856de54f31ad5448576528bf9a", "Your increasing divine power also manifests as the following features from a lesser class.", "커져 가는 신성한 힘이 하위 클래스의 다음 능력으로도 발현됩니다.", true);
      KoreanLocalization.Add("cca1b45848614920861e309e78d801f0", "Divine Legacy", "신성한 전승", false);
      KoreanLocalization.Add("fc3f42244cd0407d9f6ddbc556ca815a", "The God Emperor is proficient with all simple, martial, and exotic weapons and with all armor (heavy, light, and medium) and shields (including tower shields). They can cast {g|Encyclopedia:Spell}spells{/g} from this class while wearing armor and shields (including tower shields) without incurring the normal {g|Encyclopedia:Spell_Fail_Chance}arcane spell failure chance{/g}, but they incur the normal arcane spell failure chance for arcane spells received from other classes.", "신황은 모든 단순 무기, 군용 무기, 특수 무기와 모든 갑옷(경장, 평장, 중장), 모든 방패(타워 실드 포함)에 숙련됩니다. 갑옷이나 방패(타워 실드 포함)를 착용해도 이 클래스에서 얻은 {g|Encyclopedia:Spell}주문{/g}에는 일반적인 {g|Encyclopedia:Spell_Fail_Chance}비전 주문 실패 확률{/g}이 적용되지 않습니다. 다른 클래스에서 얻은 비전 주문에는 정상적으로 적용됩니다.", true);
      KoreanLocalization.Add("8b88c7e766c246268d9798cf48657b2a", "God Emperor Proficiences", "신황의 숙련", false);
      KoreanLocalization.Add("61fc5e4335e84512853a0efb1fd5905f", "At 15th level, you gain a competence {g|Encyclopedia:Bonus}bonus{/g} to your {g|Encyclopedia:Initiative}initiative{/g} {g|Encyclopedia:Check}checks{/g} equal to your {g|Encyclopedia:Wisdom}Wisdom{/g} modifier.", "15레벨에 {g|Encyclopedia:Initiative}우선권{/g} {g|Encyclopedia:Check}판정{/g}에 {g|Encyclopedia:Wisdom}지혜{/g} 수정치만큼 능숙 {g|Encyclopedia:Bonus}보너스{/g}를 받습니다.", true);
      KoreanLocalization.Add("90d931a27e2847b98805541938b1ca4d", "GodEmperor", "신황", false);
      KoreanLocalization.Add("fb615656a2d646ed9ee31bd023c4a0ec", "Aqua is the goddess of water who guided humans in the afterlife and oversaw the reincarnation of people into other worlds. She is an extremely useful goddess, so much so that she worked multiple part-time jobs in another world. As a goddess that cries alot, it is said that her tears can purify the foulest waters and even the most wretched undead.\nDomains: Water, Healing, Good, Protection\nFavoured Weapon: Quarterstaff", "아쿠아는 사후 세계에서 인간을 인도하고, 다른 세계로 환생하는 일을 관장하던 물의 여신입니다. 얼마나 유능한지 이세계에서는 여러 아르바이트까지 전전했다고 합니다. 눈물이 많은 여신으로도 유명하며, 그 눈물은 가장 더러운 물은 물론 흉측한 언데드까지 정화할 수 있다고 전해집니다.\n영역: 물, 치유, 선, 보호\n선호 무기: 육척봉", true);
      KoreanLocalization.Add("4fc15ff5455d4aff9332a6f245125481", "Aqua", "아쿠아", false);
      KoreanLocalization.Add("46867b77763d4f9fb3d42df0488e1b1d", "Ristarte is the goddess of healing who aids reincarnated heroes in their journey to defeat the demon lord in their new world. Though the healing abilities of Ristarte are only as good as a common herb, her kind and caring smile provide an even greater emotional healing.\nDomains: Healing, Good, Travel, Luck\nFavoured Weapon: Longsword", "리스타르테는 환생한 용사가 새로운 세계의 마왕을 물리치도록 돕는 치유의 여신입니다. 치유 능력은 평범한 약초 수준에 불과하지만, 따뜻하고 다정한 미소만큼은 그보다 훨씬 깊이 마음을 어루만져 줍니다.\n영역: 치유, 선, 여행, 행운\n선호 무기: 장검", true);
      KoreanLocalization.Add("93afab0399bc46f39f32e93150b26180", "Ristarte", "리스타르테", false);
      KoreanLocalization.Add("a11d8f6fd6dd4d568f702132f8ac57d8", "At 20th level, you surpass the pinnacle of this physical reality. You are immune to all spells and {g|Encyclopedia:Physical_Damage}physical damage{/g}. Your attacks ignore concealment and damage reduction. Your spells ignore spell resistance and spell immunity.", "20레벨에 당신은 물질세계의 한계를 초월합니다. 모든 주문과 {g|Encyclopedia:Physical_Damage}물리 피해{/g}에 면역이 됩니다. 당신의 공격은 은폐와 피해 감소를 무시하고, 주문은 주문 저항과 주문 면역을 무시합니다.", true);
      KoreanLocalization.Add("706a785c8022404aad5fe5cd5f37dfb3", "Godhood", "신격", false);
      KoreanLocalization.Add("616cc03b7b654b6394bc74694320327b", "At 17th level, the God Emperor gains immunity to all elements (acid, cold, electricity, fire, and sonic).", "17레벨에 신황은 모든 원소(산성, 냉기, 전격, 화염, 음파)에 면역이 됩니다.", true);
      KoreanLocalization.Add("edb0b03c16664d2a850597f5ffb715c1", "Godly Vessel", "신의 그릇", false);
      KoreanLocalization.Add("90f8b1d54baf413abfe80fa7e530df62", "Allies within 40 feet of you gain a sacred bonus to AC and saving throws equal to 1/2 your character level.", "40피트 이내 아군은 방어도와 내성 굴림에 당신의 캐릭터 레벨의 절반만큼 신성 보너스를 받습니다.", false);
      KoreanLocalization.Add("d37e4dbdc0e64513b21eb9e6af52f45e", "This character has a sacred bonus to AC and saving throws equal to 1/2 your character level.", "이 캐릭터는 방어도와 내성 굴림에 능력 소유자의 캐릭터 레벨의 절반만큼 신성 보너스를 받습니다.", true);
      KoreanLocalization.Add("3929edcfe5264b4caf72505e1ea25db4", "Gold Barrier", "황금 장벽", false);
      KoreanLocalization.Add("9b033b9d5e614300aa91f43d1ef3f9be", "At 12th level, Gold Barrier now also grants fast healing equal to your character level.", "12레벨에 황금 장벽이 당신의 캐릭터 레벨만큼 빠른 치유도 부여합니다.", true);
      KoreanLocalization.Add("f0a4fa458e114ade86b19d69973edbcf", "Greater Gold Barrier", "상급 황금 장벽", false);
      KoreanLocalization.Add("5c56622ba43141cfa105507f8925d3f5", "This character has fast healing equal to your character level.", "이 캐릭터는 능력 소유자의 캐릭터 레벨만큼 빠른 치유를 얻습니다.", true);
      KoreanLocalization.Add("2b1b5fff1d2e4b7bb39e86b5ecae4113", "At 10th level, Gold Barrier now also grants Greater Heroism to your allies.", "10레벨에 황금 장벽이 아군에게 ‘영웅심, 상급’ 효과도 부여합니다.", true);
      KoreanLocalization.Add("dc8bc35cccd14b1183b9d8464aacb4d1", "Improved Gold Barrier", "향상된 황금 장벽", false);
      KoreanLocalization.Add("40574539d73a4a9db27e9e4005b34534", "At 15th level, Gold Barrier now also grants DR/— and resistance against all elements (acid, cold, electricity, fire, and sonic) equal to 1/2 your character level.", "15레벨에 황금 장벽이 피해 감소/—와 모든 원소(산성, 냉기, 전격, 화염, 음파)에 대한 저항도 부여합니다. 수치는 각각 당신의 캐릭터 레벨의 절반입니다.", true);
      KoreanLocalization.Add("66d0e0c5af434fb5b6519c426ffe6166", "Grand Gold Barrier", "최상급 황금 장벽", false);
      KoreanLocalization.Add("a24258acc5ec41d7a5821813700607ca", "This character has DR/— and resistance against all elements (acid, cold, electricity, fire, and sonic) equal to 1/2 your character level.", "이 캐릭터는 능력 소유자의 캐릭터 레벨의 절반만큼 피해 감소/—와 모든 원소(산성, 냉기, 전격, 화염, 음파)에 대한 저항을 얻습니다.", true);
      KoreanLocalization.Add("e12820944950455a871372be822b46c6", "The Hero uses their Charisma modifier for their melee attack and damage bonus instead of Strength. In addition, they may use their Charisma in place of their Strength for CMB and to qualify for any feat for which it is a prerequisite.", "용사는 근접 명중과 피해 보너스에 힘 대신 매력 수정치를 사용합니다. 전법 보너스(CMB)와 힘을 선행 조건으로 요구하는 특기를 습득할 때에도 힘 대신 매력을 사용할 수 있습니다.", true);
      KoreanLocalization.Add("f7110d36f8ac432a85c9ccf237383bdd", "Graceful Combat", "우아한 전투", false);
      KoreanLocalization.Add("10d585956ace445b858885ec830e1cb4", "Vendor prices are reduced by 50%.", "상점 구매 가격이 50% 감소합니다.", true);
      KoreanLocalization.Add("5438dac9e29541c8b254ca31032e2e83", "Haggler", "흥정꾼", false);
      KoreanLocalization.Add("fd72dc6ca40c4d348301f48e1d7ffc0e", "The Hero heals allies for double the amount.", "용사가 아군을 치유할 때 회복량이 두 배가 됩니다.", true);
      KoreanLocalization.Add("2a4901bb4daf4a4bb9131884d7bd1ba1", "Hands of Salvation", "구원의 손길", false);
      KoreanLocalization.Add("ddfb34d52e8d4028a32af55b75b8063f", "So this is the result of 100 push-ups, 100 sit-ups, 100 squats and a 10km run...", "팔굽혀펴기 100회, 윗몸일으키기 100회, 스쿼트 100회, 달리기 10km의 결과가 바로 이것인가…", true);
      KoreanLocalization.Add("d433bad9a5fe414aafeeb8513c881340", "Hax", "규격 외의 힘", false);
      KoreanLocalization.Add("766ea3557e564948b5fbb610368a445a", "You gain immunity to bleed, blindness, curses, poison, disease, sickened, and nauseated conditions.", "출혈, 실명, 저주, 독, 질병, 고통과 구토에 면역이 됩니다.", true);
      KoreanLocalization.Add("3e1c5203f8124982b3abc6f7235cd42f", "Healthy Body", "건강한 육체", false);
      KoreanLocalization.Add("de7caf16fbe0405c99599b679b30e6a6", "Heroes use their newfound powers for good. After realising the suffering and despair of the inhabitants of the new world, the hero sets out to bring knowledge from their old world in order to save them.", "용사는 새롭게 얻은 힘을 선한 일에 사용합니다. 낯선 세계의 주민들이 겪는 고통과 절망을 알게 된 용사는, 전생의 지식으로 이들을 구하고자 길을 나섭니다.", false);
      KoreanLocalization.Add("f488e3c731d740db830ae37ce754d695", "Hero", "용사", false);
      KoreanLocalization.Add("08f1d4e4d9d94b7598f0a1cd324360cd", "Heroic Aura", "용사의 오라", false);
      KoreanLocalization.Add("eb6a66320c164681b5fbf13ece5db134", "You are a shining beacon of Light. The beacon that shows the way through the darkness and your legacy reflects that.", "당신은 어둠 속에서 길을 밝히는 찬란한 빛입니다. 당신이 이어받은 전승에도 그 빛이 깃들어 있습니다.", true);
      KoreanLocalization.Add("fb35e8e92a45454092b8fe7e9cf92a45", "Heroic Legacy", "용사의 전승", false);
      KoreanLocalization.Add("5593eb5d5c6a45e99d7f50cb3ce52df6", "The Hero is proficient with all simple, martial, and exotic weapons and with all armor (heavy, light, and medium) and shields (including tower shields). They can cast {g|Encyclopedia:Spell}spells{/g} from this class while wearing armor and shields (including tower shields) without incurring the normal {g|Encyclopedia:Spell_Fail_Chance}arcane spell failure chance{/g}, but they incur the normal arcane spell failure chance for arcane spells received from other classes.", "용사는 모든 단순 무기, 군용 무기, 특수 무기와 모든 갑옷(경장, 평장, 중장), 모든 방패(타워 실드 포함)에 숙련됩니다. 갑옷이나 방패(타워 실드 포함)를 착용해도 이 클래스에서 얻은 {g|Encyclopedia:Spell}주문{/g}에는 일반적인 {g|Encyclopedia:Spell_Fail_Chance}비전 주문 실패 확률{/g}이 적용되지 않습니다. 다른 클래스에서 얻은 비전 주문에는 정상적으로 적용됩니다.", true);
      KoreanLocalization.Add("85c9704d4692487492ae05aee3ae379d", "Hero Proficiences", "용사의 숙련", false);
      KoreanLocalization.Add("fa3d7c3c182043ac9191f4dccc2b7fcd", "You gain immunity to hexes.", "주술에 면역이 됩니다.", true);
      KoreanLocalization.Add("0f6b4cbbad3442c3a774dea723cf8a51", "Hex Immunity", "주술 면역", false);
      KoreanLocalization.Add("6420a34876114bda980b46bf319eaa75", "Lawful allies within 120 feet of you deals an additional 8d6 force damage.", "120피트 이내의 질서 성향 아군은 8d6의 추가 역장 피해를 입힙니다.", false);
      KoreanLocalization.Add("df47e1c6dc2644d18c475152efd8c427", "Overpowered Aura — Indignant Fury", "초월 오라: 의분", false);
      KoreanLocalization.Add("84cb3543c6524dffa4029263812ef750", "This character deals an additional 8d6 force damage.", "이 캐릭터는 8d6의 추가 역장 피해를 입힙니다.", false);
      KoreanLocalization.Add("af47876362ef4fe9b10f9a3526b64d04", "Aura of Indignant Fury", "의분의 오라", false);
      KoreanLocalization.Add("b7f1ff5cfbe34a2a84d7bbf0bc2fec9b", "\"Hey you, yes you! Have you ever wondered why the bag of holding is so limited? I mean, you can't even fit your whole harem inside. Well, with the Interdimensional Pocket 9000 now you can! Using advanced Numerian technologies with state-of-the-art Alkenstarian manufacturing techniques, the Interdimensional Pocket 9000 is able to have a storage capacity of INFINITE tons.\nAnd that's not all! The composite nahyndrian crystal and dragonhide nanofibers provide an excellent, sleek, and tough exterior, ensuring that it is both comfortable to use and durable even in the harshest environments.\nSo what are you waiting for? Get your Interdimensional Pocket 9000 today and experience the ultimate in storage solutions. Whether you're carrying your harem, your plethora of corpse-looted weapons, or your suspiciously large amount of gold, the Interdimensional Pocket 9000 is the perfect accessory for all your storage needs. Don't miss out on this incredible opportunity - order now!\"\n— Antonius Sullivarus, the Merchant Mage of Magnificent Wares\nBenefit: You have an infinite carry capacity.", "\"거기 당신, 그래요, 당신! 보관의 가방이 왜 이리 좁은지 생각해 본 적 없습니까? 하렘 식구들도 다 못 넣잖아요. 하지만 차원 주머니 9000이라면 가능합니다! 첨단 누메리아 기술과 최신 앨켄스타 제조 공법으로 탄생한 차원 주머니 9000의 수납 한도는 무한대 톤!\n이것만이 아닙니다! 나힌드리안 수정 복합재와 드래곤 가죽 나노섬유로 완성한 외피는 매끄럽고 튼튼하며 보기에도 훌륭합니다. 쓰기 편한 것은 물론, 아무리 험한 환경에서도 끄떡없지요.\n망설일 이유가 있습니까? 지금 바로 차원 주머니 9000으로 최고의 수납을 경험하세요. 하렘 식구든, 시체에서 주워 모은 무기 더미든, 수상할 만큼 많은 골드든, 차원 주머니 9000 하나면 전부 해결됩니다. 이 놀라운 기회를 놓치지 마세요. 지금 주문하세요!\"\n진귀한 물건을 파는 상인 마법사, 안토니우스 설리바루스\n효과: 운반 중량 한도가 무제한이 됩니다.", true);
      KoreanLocalization.Add("0596438aab8d457ea7ad2f98bc43a543", "Overpowered Ability — Infinite Space", "초월 능력: 무한 공간", false);
      KoreanLocalization.Add("d20aec7e455b46729b24dcebe74e40be", "You gain immunity to shaken, frightened, cowering, fear, death effects, {g|Encyclopedia:Ability_Scores}ability score{/g} drain, energy drain, and negative levels.", "동요, 겁먹음, 위축, 공포, 죽음 효과, {g|Encyclopedia:Ability_Scores}능력치{/g} 흡수, 에너지 흡수와 음수 레벨에 면역이 됩니다.", true);
      KoreanLocalization.Add("f5b7635b0a464cfab6a9f1323f84b955", "Inner Power", "내면의 힘", false);
      KoreanLocalization.Add("794e550fd82f40dc8dc4ccc934ba35ad", "Your reincarnation by divine means has strengthened your divine connection above that of normal people. \nThe difference might not be easily visible at the beginning. \nBut as time passes it will slowly grow, granting you access to more and more domains.", "신의 힘으로 환생하면서 당신과 신성한 힘의 연결은 보통 사람보다 훨씬 깊어졌습니다.\n처음에는 차이가 눈에 잘 띄지 않을 수도 있습니다.\n하지만 시간이 흐를수록 그 힘이 자라나, 점점 더 많은 영역을 다룰 수 있게 됩니다.", true);
      KoreanLocalization.Add("8abb9c0d7a914c50a692de88c0fbabab", "Inquisitor Legacy - Domain Lord", "인퀴지터 전승: 영역의 주인", false);
      KoreanLocalization.Add("b4c84c9b3c7a40bcbbcb4b17cb76c946", "You were a judge in your previous world, but you were killed by a corrupt system that twisted the law to serve its own interests. \nYou have been reborn in a world where law is often ignored or perverted, and you have sworn to uphold the law and punish the lawbreakers. \nYou can use your judgements more often and more effectively than normal inquisitors, enhancing your abilities and weakening your foes. \nYou are a champion of law and order, and a scourge of chaos and anarchy.", "전생에 당신은 판사였지만, 사익을 위해 법을 왜곡한 부패한 체제에 살해당했습니다.\n법이 무시되거나 악용되는 세계에 다시 태어난 당신은 법을 수호하고 범법자를 처벌하겠다고 맹세했습니다.\n보통 인퀴지터보다 심판을 더 자주, 더 강력하게 사용하여 자신을 강화하고 적을 약화시킬 수 있습니다.\n당신은 법과 질서의 수호자이며 혼돈과 무정부 상태를 응징하는 존재입니다.", true);
      KoreanLocalization.Add("87c3e30b097f4c2e9cd0b2d8cdadf0de", "Inquisitor Legacy - Judge", "인퀴지터 전승: 재판관", false);
      KoreanLocalization.Add("c0a932dba91b4e63992868715778cbee", "You are used to telling people what to do. \nYou were the tactician who led your guild to first kill Onyxia. \nThis, as far as you are concerned, is just another raid to conquer with your brilliant tactics and perfect preparation... \nUsing your good Judgement you can quickly spot the weaknesses of the opponent and exploit them even as you tactically help your allies to avoid their own.", "당신은 사람들에게 지시하는 일에 익숙합니다.\n길드를 이끌고 오닉시아 최초 처치에 성공한 전술가였으니까요.\n당신에게 이 세계는 뛰어난 전술과 완벽한 준비로 공략할 또 하나의 공격대 던전일 뿐입니다…\n탁월한 심판으로 적의 약점을 재빨리 찾아 공략하는 한편, 전술적 지원으로 아군이 약점을 드러내지 않게 돕습니다.", true);
      KoreanLocalization.Add("3808c9b741a945acae6c3719ef61f268", "Inquisitor Legacy - Tactician", "인퀴지터 전승: 전술가", false);
      KoreanLocalization.Add(null, "Who will live and who will die? This ultimate power to alter fate lies within your grasp. Will you wield it wisely, or will you assert your dominion as a god of the new world?\nBenefit: Instantly kills the targeted creature if they fail a Fortitude saving throw. The DC starts at 25 and scales with your level and Charisma modifier, making it increasingly difficult to resist. Creatures immune to death effects are not spared, but instead suffer significant unholy damage.\nFailure: Creatures that succeed on the saving throw are stunned for 1 round, giving you the opportunity to turn the tide in your favor.", "누구를 살리고 누구를 죽일 것인가? 운명을 바꿀 궁극의 힘이 당신의 손안에 있습니다. 현명하게 쓰겠습니까, 아니면 이세계의 신으로 군림하겠습니까?\n효과: 대상이 인내 내성에 실패하면 불경 피해를 1 받으며, 내성에 성공하면 1라운드 동안 기절합니다. 주문 저항이 적용됩니다.", false);
      KoreanLocalization.Add("6a504c9462484c9d862c53689cc8846c", "Overpowered Ability — Instakill", "초월 능력: 즉사", false);
      KoreanLocalization.Add("01c74725a4b7488d9626a1735d003cdc", "You cannot take damage.", "피해를 받지 않습니다.", true);
      KoreanLocalization.Add("7b65d3e0b31945c3a2d90a0793a5b1ba", "Invincibility", "무적", false);
      KoreanLocalization.Add("a4bff8e12de34ecfa24cd0bb41352b91", "Otherworldly entities who are reincarnated into the world of Golarion as an Angel have both extreme beauty and power. They serve as exemplars of good and light regardless of the myriad forms they may take.\nThe Isekai Angel has a +4 racial {g|Encyclopedia:Bonus}bonus{/g} to {g|Encyclopedia:Strength}Strength{/g} and {g|Encyclopedia:Charisma}Charisma{/g}, and a +2 racial bonus on {g|Encyclopedia:Persuasion}Persuasion{/g} and {g|Encyclopedia:Lore_Religion}Lore (religion){/g} checks. They have DR 10/Evil, and have spell resistance equal to 10 + their character level. They have immunity to acid, cold, and petrification as well as fire and electricity resistance 20. They can also use the Angelic Bolt spell once per day.", "골라리온에 천사로 환생한 이세계인은 빼어난 아름다움과 힘을 함께 지닙니다. 어떤 모습으로 나타나든 선과 빛의 모범이 됩니다.\n이세계 천사는 {g|Encyclopedia:Strength}힘{/g}과 {g|Encyclopedia:Charisma}매력{/g}에 +4 종족 {g|Encyclopedia:Bonus}보너스{/g}를, {g|Encyclopedia:Persuasion}설득{/g}과 {g|Encyclopedia:Lore_Religion}전승 (종교){/g} 판정에 +2 종족 보너스를 받습니다. 피해 감소 10/악과 10 + 캐릭터 레벨만큼 주문 저항을 지닙니다. 산성, 냉기, 석화에 면역이며 화염 저항과 전격 저항 20을 얻습니다. 또한 천사의 번개 주문을 하루에 한 번 사용할 수 있습니다.", true);
      KoreanLocalization.Add("701c2196af0643cbad84ce598fd5bd32", "Isekai Angel", "이세계 천사", false);
      KoreanLocalization.Add("cdac7a1edef44a9bae7c55627f613e89", "Otherworldly Aura", "이세계의 오라", false);
      KoreanLocalization.Add("03c45d27e9e14d4e824287595f596ccd", "Before you were hit by a truck, you were a...", "트럭에 치이기 전, 당신은…", true);
      KoreanLocalization.Add("0e195ee3f966496d9c2dd58a80114214", "Isekai", "이세계", false);
      KoreanLocalization.Add("95fae9f1fc3f43148db74cf5d61bc055", "You can pick additional bloodlines as your chimera blood becomes stronger.", "키메라의 피가 강해지면서 추가 혈통을 선택할 수 있습니다.", true);
      KoreanLocalization.Add("68b7e93b4411438ba34430026d712f9b", "Bloodline", "혈통", false);
      KoreanLocalization.Add("6f09ae43c7ed46048945a81893111598", "At 1st level, and at every even level thereafter, you gain a bonus {g|Encyclopedia:Feat}feat{/g} in addition to those gained from normal advancement.", "1레벨과 이후 짝수 레벨마다, 정상적인 성장으로 얻는 특기와 별개로 추가 {g|Encyclopedia:Feat}특기{/g}를 하나 얻습니다.", true);
      KoreanLocalization.Add("c4178e36c7f64bb8aa42176f343e5fc6", "You can cast a number of {g|Encyclopedia:Cantrips_Orisons}cantrips{/g}, or 0-level {g|Encyclopedia:Spell}spells{/g}. These spells are cast like any other spell, but they are not expended when cast and may be used again.", "여러 {g|Encyclopedia:Cantrips_Orisons}캔트립{/g}, 즉 0레벨 {g|Encyclopedia:Spell}주문{/g}을 시전할 수 있습니다. 다른 주문과 같은 방식으로 시전하지만, 사용해도 소모되지 않으므로 반복해서 시전할 수 있습니다.", true);
      KoreanLocalization.Add("20486415c0084b3289a899faf71123c8", "Cantrips", "캔트립", false);
      KoreanLocalization.Add("4f4892bcca034222bc8314c260138b4c", "Channeling negative energy causes a burst that damages every living creature in a 30-foot radius centered on the caster. The amount of damage inflicted is equal to 1d6 points of damage plus 1d6 points of damage for every two Isekai Protagonist levels beyond 1st (2d6 at 3rd, 3d6 at 5th, and so on). Creatures that take damage from channeled energy receive a Will save to halve the damage. The DC of this save is equal to 10 + 1/2 the Isekai Protagonist level + Charisma modifier.", "음에너지를 방출하여 시전자 중심 30피트 반경의 모든 살아 있는 크리처에게 피해를 입힙니다. 피해량은 1레벨에 1d6이며, 이후 이세계 주인공 레벨이 2 오를 때마다 1d6씩 증가합니다(3레벨에 2d6, 5레벨에 3d6 등). 대상은 의지 내성에 성공하면 피해를 절반만 받습니다. 내성 난이도는 10 + 이세계 주인공 레벨의 절반 + 매력 수정치입니다.", true);
      KoreanLocalization.Add("8a8fd4e9edcb400ca7a2e11be89629e8", "Channel Negative Energy - Damage Living", "음에너지 전달: 생명체 피해", false);
      KoreanLocalization.Add("e97abaf3fd704a399f0caa2fea378327", "You gain the supernatural ability to channel negative energy like a cleric. You use your Isekai Protagonist level as your effective cleric level when channeling negative energy. You can channel energy a number of times per day equal to 3 + your Charisma modifier.", "클레릭처럼 음에너지를 전달하는 초자연적 능력을 얻습니다. 음에너지 전달의 효과를 계산할 때 이세계 주인공 레벨을 유효 클레릭 레벨로 사용합니다. 하루 사용 횟수는 3 + 매력 수정치입니다.", true);
      KoreanLocalization.Add("93378520b1b94208aae7a8926abad27c", "Channel Negative Energy", "음에너지 전달", false);
      KoreanLocalization.Add("c030e454eb614f0aa5c9810bb92d8229", "Channeling negative energy causes a burst that heals every undead creature in a 30-foot radius centered on the caster. The amount of damage healed is equal to 1d6 points of damage plus 1d6 points of damage for every two Isekai Protagonist levels beyond 1st (2d6 at 3rd, 3d6 at 5th, and so on).", "음에너지를 방출하여 시전자 중심 30피트 반경의 모든 언데드를 치유합니다. 회복량은 1레벨에 1d6이며, 이후 이세계 주인공 레벨이 2 오를 때마다 1d6씩 증가합니다(3레벨에 2d6, 5레벨에 3d6 등).", true);
      KoreanLocalization.Add("4358b26d030c4f938adb8eb9fb040394", "Channel Negative Energy - Heal Undead", "음에너지 전달: 언데드 치유", false);
      KoreanLocalization.Add("9c62f5dafc534f32a5065995d04bd58c", "Channeling positive energy causes a burst that damages every undead creature in a 30-foot radius centered on the caster. The amount of damage inflicted is equal to 1d6 points of damage plus 1d6 points of damage for every two Isekai Protagonist levels beyond 1st (2d6 at 3rd, 3d6 at 5th, and so on). Creatures that take damage from channeled energy receive a Will save to halve the damage. The DC of this save is equal to 10 + 1/2 the Isekai Protagonist level + Charisma modifier.", "양에너지를 방출하여 시전자 중심 30피트 반경의 모든 언데드에게 피해를 입힙니다. 피해량은 1레벨에 1d6이며, 이후 이세계 주인공 레벨이 2 오를 때마다 1d6씩 증가합니다(3레벨에 2d6, 5레벨에 3d6 등). 대상은 의지 내성에 성공하면 피해를 절반만 받습니다. 내성 난이도는 10 + 이세계 주인공 레벨의 절반 + 매력 수정치입니다.", true);
      KoreanLocalization.Add("d2879d54da1e4f34b739b3890f3bf630", "Channel Positive Energy - Damage Undead", "양에너지 전달: 언데드 피해", false);
      KoreanLocalization.Add("be7d58a6bf3c4a33b816416c6e7ac42f", "You gain the supernatural ability to channel positive energy like a cleric. You use your Isekai Protagonist level as your effective cleric level when channeling positive energy.  You can channel energy a number of times per day equal to 3 + your Charisma modifier.", "클레릭처럼 양에너지를 전달하는 초자연적 능력을 얻습니다. 양에너지 전달의 효과를 계산할 때 이세계 주인공 레벨을 유효 클레릭 레벨로 사용합니다. 하루 사용 횟수는 3 + 매력 수정치입니다.", true);
      KoreanLocalization.Add("ec9c9568c5194a4b9cc823fa4313b41b", "Channel Positive Energy", "양에너지 전달", false);
      KoreanLocalization.Add("420330b0a8ad41ac9359bbead21e9d07", "Channeling positive energy causes a burst that heals every living creature in a 30-foot radius centered on the caster. The amount of damage healed is equal to 1d6 points of damage plus 1d6 points of damage for every two Isekai Protagonist levels beyond 1st (2d6 at 3rd, 3d6 at 5th, and so on).", "양에너지를 방출하여 시전자 중심 30피트 반경의 모든 살아 있는 크리처를 치유합니다. 회복량은 1레벨에 1d6이며, 이후 이세계 주인공 레벨이 2 오를 때마다 1d6씩 증가합니다(3레벨에 2d6, 5레벨에 3d6 등).", true);
      KoreanLocalization.Add("5bb72e28f549477fa2560d3513ca1882", "Channel Positive Energy - Heal Living", "양에너지 전달: 생명체 치유", false);
      KoreanLocalization.Add("3cfb8800ab31481983618d443b8f2f49", "Otherworldly entities who are reincarnated into the world of Golarion as a Dark Elf have both extreme beauty and power. They are a cruel and cunning dark reflection of the elven race.\nThe Isekai Dark Elf has a +4 racial {g|Encyclopedia:Bonus}bonus{/g} to {g|Encyclopedia:Intelligence}Intelligence{/g}, a +2 racial bonus to {g|Encyclopedia:Dexterity}Dexterity{/g} and {g|Encyclopedia:Wisdom}Wisdom{/g}, and a -2 penalty to Constitution. They have spell resistance equal to 10 + their character level. They can also use the Drow Poison ability as a swift action a number of times per day equal to their Intelligence modifier.", "골라리온에 다크 엘프로 환생한 이세계인은 빼어난 아름다움과 힘을 함께 지닙니다. 엘프의 어두운 이면을 닮은, 잔혹하고 교활한 존재들입니다.\n이세계 다크 엘프는 {g|Encyclopedia:Intelligence}지능{/g}에 +4 종족 {g|Encyclopedia:Bonus}보너스{/g}를, {g|Encyclopedia:Dexterity}민첩{/g}과 {g|Encyclopedia:Wisdom}지혜{/g}에 +2 종족 보너스를 받고, 건강에는 -2 불이익을 받습니다. 10 + 캐릭터 레벨만큼 주문 저항을 지닙니다. 또한 하루에 지능 수정치만큼 드로우 독 능력을 신속 행동으로 사용할 수 있습니다.", true);
      KoreanLocalization.Add("5709e643fb934e7d854ea500104e776c", "Isekai Dark Elf", "이세계 다크 엘프", false);
      KoreanLocalization.Add("ce7f6581c1ab4dcb8d07e1cc571a3128", "Gods from another world.", "다른 세계에서 온 신들입니다.", true);
      KoreanLocalization.Add("16429b92808c42dd9bdffd8c8c30fc72", "(Isekai Protagonist) \"Do you want to join my harem?\"", "(이세계 주인공) \"내 하렘에 들어올 생각 없어?\"", false);
      KoreanLocalization.Add("38f28f4e0ff0480395f40e08c3b8d007", "(Isekai Protagonist) \"I've convinced Irabeth to join the harem.\"", "(이세계 주인공) \"이라베스도 하렘에 들어오기로 했어.\"", false);
      KoreanLocalization.Add("dd6193d3ce934224b6cc64843615360e", "\"Sure thing, only if you can convince Irabeth to join.\"", "\"좋지. 이라베스도 들어오게 설득한다면 말이야.\"", false);
      KoreanLocalization.Add("b41e9abb7c2f486ab948e467679b2cdc", "\"Also, for no particular reason, would you be interested in a spare of coffin I have lying around?\"", "\"아, 별다른 뜻은 없는데 말이야. 집에 남는 관이 하나 있거든. 혹시 필요해?\"", false);
      KoreanLocalization.Add("a46fca3d7e304a0fb45ecc217bab34d0", "{n}Anevia is astonished.{/n} \"That was completely unexpected. I guess I'll discuss with Irabeth about our glorious future in your harem.\"", "{n}아네비아가 깜짝 놀랍니다.{/n} \"정말 뜻밖인걸. 당신 하렘에서 누릴 영광스러운 미래에 대해 이라베스랑 이야기해 봐야겠어.\"", false);
      KoreanLocalization.Add("76ed9a699b9b447db9498263cde5e614", "(Isekai Protagonist) \"Hey can't you transform into anything cooler?\"", "(이세계 주인공) \"이봐, 좀 더 멋진 걸로 변할 수는 없어?\"", false);
      KoreanLocalization.Add("267aaf8c92d44b97b8b40b421d38a0b3", "\"Not sure what you mean, I can be any weapon you want? Am I not good enough?\"", "\"무슨 뜻인지 모르겠는데. 원하는 무기는 뭐든 될 수 있잖아? 나로는 부족한 거야?\"", false);
      KoreanLocalization.Add("f6b0747fd79244208a32a02247ece79c", "(Isekai Protagonist) \"Two thousand gold... And you give me blessing to mary your daughter.\"", "(이세계 주인공) \"2천 골드… 그리고 따님과의 결혼을 허락해 주시오.\"", false);
      KoreanLocalization.Add("ac27deaf79654a76a107f202cbc6d7a1", "\"My daughter?\" {n}Horgus takes a quick glance at Camellia.{/n} \"I don't think you know what sort of person she is. {n}Horgus takes a breath.{/n} Regardless, it seems my previous offer was somewhat insulting. Two thousand gold it is.\"", "\"내 딸?\" {n}호거스가 카멜리아를 흘끗 봅니다.{/n} \"그 아이가 어떤 사람인지 잘 모르는 모양이군. {n}호거스가 숨을 고릅니다.{/n} 어쨌든, 내가 제시한 금액이 좀 모욕적이었나 보군. 2천 골드로 하지.\"", false);
      KoreanLocalization.Add("efe5e4b22ae64cc5a6dc62f052887c21", "(Isekai Protagonist) \"Other than being hit by a truck, I don't remember anything at all...\"", "(이세계 주인공) \"트럭에 치인 것 말고는 아무것도 기억이 안 나는데…\"", false);
      KoreanLocalization.Add("ec06abd2285048a6a4ff0aceaf9ffc7c", "(Isekai Protagonist) \"Do you want to join my harem? Anevia is also joining.\"", "(이세계 주인공) \"내 하렘에 들어올 생각 없어? 아네비아도 들어오기로 했는데.\"", false);
      KoreanLocalization.Add("4c9331d685d54494af13b1d68d7f2da6", "\"It's true.\"", "\"사실이야.\"", false);
      KoreanLocalization.Add("471d270348f240128b23adcb7706bb25", "\"Nevermind. It was a joke.\"", "\"신경 쓰지 마. 농담이었어.\"", false);
      KoreanLocalization.Add("cb40b9485864480cb849ff6cfbd511cc", "\"Ridiculous! I don't know what sorcery is this, but Anevia would never agree to this.\"", "\"말도 안 되는 소리! 무슨 요술을 부린 건지는 모르겠지만, 아네비아가 그런 일에 동의할 리 없어.\"", false);
      KoreanLocalization.Add("8484f356f1aa46e499073ad2352a4d3c", "\"That's what I thought.\"", "\"역시 그럴 줄 알았어.\"", false);
      KoreanLocalization.Add("058adcc857e74bd787014d3e4e3af276", "\"I don't think so.\"", "\"그럴 생각은 없어.\"", false);
      KoreanLocalization.Add("a0ac4070453b4f63867b2e3a47b01cf2", "\"Fine. I'll join your harem after the crusades against the demons is over.\"", "\"좋아. 데몬과의 십자군 전쟁이 끝나면 네 하렘에 들어가지.\"", false);
      KoreanLocalization.Add(null, "(Isekai Protagonist) [Attack] \"Nice acting, Mr. background character. Now it's time for your unmomentous death scene.\"", "(이세계 주인공) [공격한다] \"연기 잘 봤다, 조연 씨. 이제 아무도 기억 못 할 죽음 장면을 찍어야지.\"", false);
      KoreanLocalization.Add("9b76fd16d94d4b1b8dbb976fe7faf4a2", "(Isekai Protagonist) \"Minagho? More like Minag-hoe!\"", "(이세계 주인공) \"미나고? 미나갈보가 더 어울리겠네!\"", false);
      KoreanLocalization.Add("ab479b672f4d4791be88d49855c14da1", "...", "...", false);
      KoreanLocalization.Add("24fdd08f0e0e4b0382ce2f72e2dd3be8", "{n}Seelah smiles and gives you a thumbs up!{/n}", "{n}실라가 웃으며 당신에게 엄지를 치켜듭니다!{/n}", false);
      KoreanLocalization.Add("6d1a688cc1af4c16b972f70bde39205f", "(Isekai Protagonist) \"I am the bone of my sword.\"", "(이세계 주인공) \"내 몸은 검으로 되어 있다.\"", false);
      KoreanLocalization.Add("b4ae53586853499885d9affaa4b95c36", "(Isekai Protagonist) \"I am the hope of the universe.\"", "(이세계 주인공) \"나는 우주의 희망이다.\"", false);
      KoreanLocalization.Add("8ac129aee1504d2f9ad2e4dbea268e96", "(Isekai Protagonist) \"I am just a guy who's a hero for fun.\"", "(이세계 주인공) \"취미로 히어로를 하는 사람이다.\"", false);
      KoreanLocalization.Add("0a294c30391647a5a71c0e7b503086e7", "(Isekai Protagonist) \"I am Atomic.\"", "(이세계 주인공) \"아이 엠 아토믹.\"", false);
      KoreanLocalization.Add("a5b5ec8da25e43a4a1e951266cdcbd06", "(Isekai Protagonist) \"I am a God.\"", "(이세계 주인공) \"나는 신이다.\"", false);
      KoreanLocalization.Add("bc78aad3a5134a598df951f608155a60", "(Isekai Protagonist) \"I am just some guy who got hit by a truck and somehow ended up in this world.\"", "(이세계 주인공) \"그냥 트럭에 치였다가 어쩌다 보니 이 세계에 오게 된 사람이야.\"", false);
      KoreanLocalization.Add("f55de48b68ec4b939a5ff972060ffd2e", "{n}The emptiness is bewildered and confused, but cannot deny what you say to be truth.{/n}", "{n}공허는 당혹스러워하며 혼란에 빠졌지만, 당신의 말이 진실임을 부정하지는 못합니다.{/n}", false);
      KoreanLocalization.Add("d87299f2ee974ecb8b528f3506c56d5f", "(Isekai Protagonist) [Pound the sword repeatedly] \"You better power up right now or you're going to reincarnate as a broken blade.\"", "(이세계 주인공) [검을 거듭 두드린다] \"당장 강해지는 게 좋을 거야. 안 그러면 부러진 칼날로 환생하게 될 테니까.\"", false);
      KoreanLocalization.Add("57a8c59b5fed4848a5efe291f415d52f", "You gain the service of a familiar, which offers you some skill bonuses.", "일부 기술에 보너스를 주는 사역마의 도움을 받습니다.", true);
      KoreanLocalization.Add("8b9d54c21edb4a9297ec9fd8bec0cab5", "Familiar Selection", "사역마 선택", false);
      KoreanLocalization.Add("b648c31cb34c4af7aa76a3f0ade02db3", "At 3rd level, you count your class level as your fighter level for the purpose of qualifying for {g|Encyclopedia:Feat}feats{/g}. If you have levels in fighter, these levels stack. If you have a martial legacy, the fighter level is doubled.", "3레벨부터 {g|Encyclopedia:Feat}특기{/g}의 선행 조건을 충족할 때 이 클래스의 레벨을 파이터 레벨로 취급합니다. 실제 파이터 레벨이 있다면 합산합니다. 무예 전승을 지녔다면 이 능력으로 얻는 파이터 레벨이 두 배가 됩니다.", true);
      KoreanLocalization.Add("54e57c445a844dcd87745d32aa839c29", "Fighter Training", "파이터 훈련", false);
      KoreanLocalization.Add(null, "Otherworldly entities who are reincarnated into the world of Golarion as a Kitsune have both extreme beauty and power. They are very clever and powerful as you are born partially divine.\nThe Isekai Kitsune has a +4 racial {g|Encyclopedia:Bonus}bonus{/g} to {g|Encyclopedia:Dexterity}Dexterity{/g}, a +2 racial bonus to {g|Encyclopedia:Intelligence}Intelligence{/g} and {g|Encyclopedia:Charisma}Charisma{/g}, and a -2 penalty to Strength. They have a +10 bonus to speed and have fast healing equal to their character level.", "골라리온에 키츠네로 환생한 이세계인은 빼어난 아름다움과 힘을 함께 지닙니다. 타고난 신성한 혈통 덕분에 매우 영리하고 강력합니다.\n이세계 키츠네는 {g|Encyclopedia:Dexterity}민첩{/g}에 +4 종족 {g|Encyclopedia:Bonus}보너스{/g}를, {g|Encyclopedia:Intelligence}지능{/g}과 {g|Encyclopedia:Charisma}매력{/g}에 +2 종족 보너스를 받고, 힘에는 -2 불이익을 받습니다. 이동 속도에 +10 보너스를 받으며 캐릭터 레벨만큼 빠른 치유를 지닙니다.", true);
      KoreanLocalization.Add("d8d8d7e781de40b1ad73c2cb7d9d4bfe", "Gain an additional Hex.", "주술을 하나 더 얻습니다.", true);
      KoreanLocalization.Add("da13372638d84cd89a6db758702b5c04", "Hex", "주술", false);
      KoreanLocalization.Add("bcf280e571b443a1bffaaf6201a5cd4b", "Otherworldly entities who are reincarnated into the world of Golarion as a High Elf have both extreme beauty and power. They are a refined and cultured reflection of the elven race.\nThe Isekai High Elf has a +4 racial {g|Encyclopedia:Bonus}bonus{/g} to {g|Encyclopedia:Wisdom}Wisdom{/g}, a +2 racial bonus to {g|Encyclopedia:Dexterity}Dexterity{/g} and {g|Encyclopedia:Intelligence}Intelligence{/g}, and a -2 penalty to Constitution. They have spell resistance equal to 10 + their character level. They can also cast 4 more spells per day for each spell rank.", "골라리온에 하이 엘프로 환생한 이세계인은 빼어난 아름다움과 힘을 함께 지닙니다. 세련되고 교양 있는 엘프의 면모를 보여 줍니다.\n이세계 하이 엘프는 {g|Encyclopedia:Wisdom}지혜{/g}에 +4 종족 {g|Encyclopedia:Bonus}보너스{/g}를, {g|Encyclopedia:Dexterity}민첩{/g}과 {g|Encyclopedia:Intelligence}지능{/g}에 +2 종족 보너스를 받고, 건강에는 -2 불이익을 받습니다. 10 + 캐릭터 레벨만큼 주문 저항을 지닙니다. 또한 각 주문 레벨의 하루 시전 횟수가 4회 증가합니다.", true);
      KoreanLocalization.Add("840402d12e7f4ca2ba8560d427609413", "Isekai High Elf", "이세계 하이 엘프", false);
      KoreanLocalization.Add("3beb932554c94383b3f99b9e806324be", "Otherworldly entities who are reincarnated into the world of Golarion as a High Human have both extreme beauty and power. They possess exceptional drive and a great capacity to endure and expand.\nThe Isekai High Humans have a +2 racial bonus to all attributes.", "골라리온에 하이 휴먼으로 환생한 이세계인은 빼어난 아름다움과 힘을 함께 지닙니다. 남다른 추진력과 뛰어난 인내심, 무한한 가능성을 품고 있습니다.\n이세계 하이 휴먼은 모든 능력치에 +2 종족 보너스를 받습니다.", true);
      KoreanLocalization.Add("3c98e1926fc343e08b7277c9b72579e4", "Isekai High Human", "이세계 하이 휴먼", false);
      KoreanLocalization.Add("b3c984c9e1e4464f964ef60ebe356921", "Let us be honest, there is a reason why for any mixed race classification it is always enough to name the non human options. \nBecause generally it is simply save to assume that the other part of it will be human. \nThere is no other race, except for dragons, that is as flexible when it comes to its choice of bed partners and none as flexible when it comes to being fertile when crossbreeding and realistically by now there are no true pure humans left because everyone is at least (1/2)^100 something else. \nAnd no matter how close to 0 that number is it is not 0 and for some reason in you all that blood became active in a way that allows you access to some of your ancestors powers.", "솔직히 말해 봅시다. 혼혈 종족을 부를 때 인간이 아닌 쪽만 말해도 통하는 데는 이유가 있습니다.\n나머지 절반은 인간이라고 생각하면 대체로 맞으니까요.\n드래곤을 빼면 잠자리 상대를 그토록 가리지 않는 종족도, 다른 종족과 아이를 갖는 데 그토록 유연한 종족도 없습니다. 이제 순수한 인간은 남아 있지 않을 겁니다. 누구나 적어도 (1/2)^100만큼은 다른 종족의 피를 지녔으니까요.\n아무리 0에 가까워도 0은 아닙니다. 어째서인지 당신 안에서는 그 피가 모두 깨어나, 선조들이 지녔던 힘 일부를 쓸 수 있게 되었습니다.", true);
      KoreanLocalization.Add("ff07c7039384440aa8a9d8251db536b5", "Isekai Crossbreed Human", "이세계 혼혈 인간", false);
      KoreanLocalization.Add("9b9a08c0755e4ac4aa5365c1a8a398e2", "Feat", "특기", false);
      KoreanLocalization.Add("b8188c15cc04427ea723d8b665713264", "No alternate trait", "대체 특성 없음", true);
      KoreanLocalization.Add("56d1490ca4b24b068ca8ad7c50c474a4", "None", "없음", false);
      KoreanLocalization.Add("5431e4b8e27f49baa5f472de48c7fafc", "The following alternate traits are available.", "다음 대체 특성을 선택할 수 있습니다.", true);
      KoreanLocalization.Add("27e48f527efd40b58d233c9b5d1b9c7e", "Alternate Racial Traits", "대체 종족 특성", false);
      KoreanLocalization.Add("30efa58f5239448bba86fd03bf18927c", "Isekai Kitsune", "이세계 키츠네", false);
      KoreanLocalization.Add("7b018b47daaf4b2a96aadee9567369ff", "Only a true edgelord would choose to walk alone.", "진정한 중2병 군주만이 홀로 걷는 길을 택합니다.", true);
      KoreanLocalization.Add("2caa907b086945e3828a02470f90e3d5", "Gain a curse, but some curses are blessings in disguise.", "저주 하나를 받습니다. 하지만 어떤 저주는 축복이나 다름없습니다.", true);
      KoreanLocalization.Add("1f33970a177646bdacc30458ae386c72", "Divine Curse", "신성한 저주", false);
      KoreanLocalization.Add("b2ae5f1279d646db92342a13ef668295", "Master another part of reality...", "세상의 또 다른 이치를 통달합니다…", true);
      KoreanLocalization.Add("ecc2f2d399384dc2af2a78554f18c6ed", "Divine Mystery", "신성한 신비", false);
      KoreanLocalization.Add("03bba4ff437a4db0b56cd9bfd48b2535", "As you get closer and closer to the truth of divinity you gain a new Mystery, Revelation, or perhaps a curse from a jealous god?", "신성의 진실에 다가갈수록 새로운 신비나 계시를 얻습니다. 질투심 많은 신에게 저주를 받을지도 모르지요.", true);
      KoreanLocalization.Add("aff4e7314019482db4398f1b523fca15", "Divine Inheritance", "신성한 계승", false);
      KoreanLocalization.Add("501f791deda544cea469dff1fcb00646", "At 1st level, you gain the service of either an animal companion or familiar, using your class level as your effective druid level.", "1레벨에 동물 동료 또는 사역마의 도움을 받습니다. 클래스 레벨을 유효 드루이드 레벨로 사용합니다.", true);
      KoreanLocalization.Add("4dd2f1e207594315ae7093e9e25b23f0", "Pet Selection", "동료 생물 선택", false);
      KoreanLocalization.Add("fca54321cb7e4b1eb594aae6342b7920", "Isekai Protagonists are proficient with all simple and {g|Encyclopedia:Weapon_Proficiency}martial weapons{/g} and with all armor (heavy, light, and medium) and shields (including tower shields). They can cast {g|Encyclopedia:Spell}spells{/g} from this class while wearing armor and shields (including tower shields) without incurring the normal {g|Encyclopedia:Spell_Fail_Chance}arcane spell failure chance{/g}, but they incur the normal arcane spell failure chance for arcane spells received from other classes.", "이세계 주인공은 모든 단순 무기와 {g|Encyclopedia:Weapon_Proficiency}군용 무기{/g}, 모든 갑옷(경장, 평장, 중장), 모든 방패(타워 실드 포함)에 숙련됩니다. 갑옷이나 방패(타워 실드 포함)를 착용해도 이 클래스에서 얻은 {g|Encyclopedia:Spell}주문{/g}에는 일반적인 {g|Encyclopedia:Spell_Fail_Chance}비전 주문 실패 확률{/g}이 적용되지 않습니다. 다른 클래스에서 얻은 비전 주문에는 정상적으로 적용됩니다.", true);
      KoreanLocalization.Add("45580812467242918042a2fd8c825b4e", "Isekai Protagonist Proficiences", "이세계 주인공의 숙련", false);
      KoreanLocalization.Add("f9a6bbffba07433399d6c62be079f79d", "Isekai Protagonists gain twice as many {g|Encyclopedia:Feat}feats{/g} as the other classes.", "이세계 주인공은 다른 클래스보다 {g|Encyclopedia:Feat}특기{/g}를 두 배로 많이 얻습니다.", true);
      KoreanLocalization.Add("e6a27fa9bdbd48f8be66a21120b6e7ad", "Bonus Feat", "추가 특기", false);
      KoreanLocalization.Add("880602abd6c04746866738814138c5dc", "Isekai protagonists possess immense power, and are able to defeat every enemy with ease using their overpowered abilities. They also have plot armor, which make them hard to kill. They are the main character; everyone else are just NPCs.", "이세계 주인공은 막대한 힘을 지녔으며, 초월 능력으로 어떤 적이든 손쉽게 쓰러뜨립니다. 주인공 보정까지 받아 좀처럼 죽지도 않습니다. 이들이야말로 이야기의 주인공이며, 나머지는 전부 NPC에 불과합니다.", false);
      KoreanLocalization.Add("30a354cf885d4ecea6a883fb692b8e63", "Isekai protagonists are people who have been reincarnated into the world of Golarion with overpowered abilities. As their story progresses, they gain more overpowered abilities to wreck every wannabe villain and side character they face.", "이세계 주인공은 초월 능력을 지닌 채 골라리온에 환생한 사람들입니다. 이야기가 진행될수록 더욱 강력한 능력을 얻어, 앞을 가로막는 악당 지망생과 조연들을 모조리 박살 냅니다.", false);
      KoreanLocalization.Add("de48f4acb13a439e99fd40e32badf811", "Isekai Protagonists gain a limited set of features from other classes.", "이세계 주인공은 다른 클래스의 능력 일부를 얻습니다.", true);
      KoreanLocalization.Add("6fe2229f0c054cdc89051f4d702648a2", "Isekai Protagonists gain Overpowered Abilities as they increase their level. These are extremely powerful abiilities that surpass even gods.", "이세계 주인공은 레벨이 오르면 초월 능력을 얻습니다. 신조차 뛰어넘는 엄청난 위력의 능력입니다.", true);
      KoreanLocalization.Add("7c823bb979ff4e0b800bcd71b76b570e", "Overpowered Abilities", "초월 능력", false);
      KoreanLocalization.Add("e546f2b9f59349aa903912a19f6f609c", "Isekai Protagonists gain a luck bonus to {g|Encyclopedia:Armor_Class}AC{/g} and all {g|Encyclopedia:Saving_Throw}saving throws{/g} equal to their character level.", "이세계 주인공은 {g|Encyclopedia:Armor_Class}방어도{/g}와 모든 {g|Encyclopedia:Saving_Throw}내성 굴림{/g}에 캐릭터 레벨만큼 행운 보너스를 받습니다.", true);
      KoreanLocalization.Add("594c175c4a53431ca1fc1dff6b022b82", "Plot Armor", "주인공 보정", false);
      KoreanLocalization.Add("be3a42c68a3b4bea8937b262c4a3ff19", "Isekai protagonists are otherworldly entities who have been reincarnated into the world of Golarion with extraordinary abilities. As their story progresses, they gain more unexplained and overpowered abilities to overcome every challenge they face.", "이세계 주인공은 비범한 능력을 지닌 채 골라리온에 환생한 이세계의 존재입니다. 이야기가 진행될수록 설명할 수 없을 만큼 강력한 초월 능력을 얻어, 앞을 가로막는 모든 시련을 극복합니다.", true);
      KoreanLocalization.Add("a63f2ccf97e4427e9f311a4fe54ef5fa", "Isekai Protagonists gain special powers as they increase their level. These are skills or abilities that greatly enhance the Isekai Protagonist's combat power.", "이세계 주인공은 레벨이 오르면 특수 능력을 얻습니다. 이 능력들은 주인공의 전투력을 크게 강화합니다.", true);
      KoreanLocalization.Add("72a0a92424a947668e8643c09245ae72", "Special Powers", "특수 능력", false);
      KoreanLocalization.Add("5614fae148c544fa94d58692f1e7fbec", "At 15th level, you gain a competence {g|Encyclopedia:Bonus}bonus{/g} to your {g|Encyclopedia:Initiative}initiative{/g} {g|Encyclopedia:Check}checks{/g} equal to your {g|Encyclopedia:Charisma}Charisma{/g} modifier.", "15레벨에 {g|Encyclopedia:Initiative}우선권{/g} {g|Encyclopedia:Check}판정{/g}에 {g|Encyclopedia:Charisma}매력{/g} 수정치만큼 능숙 {g|Encyclopedia:Bonus}보너스{/g}를 받습니다.", true);
      KoreanLocalization.Add("0f10b0318107479d8708ec255c62d6d0", "Quick-Footed", "재빠른 발놀림", false);
      KoreanLocalization.Add("e15a3c452b114a1a9f54710c9ba8feb5", "As you grow so does your connection to the spirits and the power you derive from them. \nAllowing you to connect with more spirits or gain more powers from them.", "성장할수록 영혼들과의 유대가 깊어지고, 그들에게서 얻는 힘도 강해집니다.\n더 많은 영혼과 교감하거나, 이미 교감한 영혼에게서 새로운 힘을 얻을 수 있습니다.", true);
      KoreanLocalization.Add("6b79b4de85af41f69c0293dce9053290", "Spirit Blessing", "영혼의 축복", false);
      KoreanLocalization.Add("88d91c896bec4dcd81b070b66e5c4198", "As your chimera blood evolves you can pick a new bloodline feat or a new bloodline.", "키메라의 피가 진화하면서 새로운 혈통 특기 또는 혈통을 선택할 수 있습니다.", true);
      KoreanLocalization.Add("33b5d555014e457882725549a1b61f38", "Bloodline Evolution", "혈통 진화", false);
      KoreanLocalization.Add("5af13b66ba4a4a7bb59a8fa09263bb29", "Otherworldly entities who are reincarnated into the world of Golarion as a Spriggan have both extreme beauty and power. Their shape changing abilities allow them to easily defeat everyone who would underestimate their power.\nThe Isekai Spriggan gains a +1 racial bonus on concentration checks and on the {g|Encyclopedia:DC}DC{/g} of all {g|Encyclopedia:Spell}spells{/g} they cast. They add Athletics, Trickery, Stealth, and Perception to the list of their class skills. They are also able to use the Size alteration ability to increase their size by two size categories and gain +10 Speed, +12 Strength, -2 Dexterity, +6 Constitution, and a -2 penalty to AC.", "골라리온에 스프리건으로 환생한 이세계인은 빼어난 아름다움과 힘을 함께 지닙니다. 변신 능력으로 자신을 얕보는 자들을 손쉽게 제압합니다.\n이세계 스프리건은 집중 판정과 자신이 시전하는 모든 {g|Encyclopedia:Spell}주문{/g}의 {g|Encyclopedia:DC}난이도{/g}에 +1 종족 보너스를 받습니다. 운동, 손재주, 은신, 지각을 클래스 기술 목록에 추가합니다. 크기 변형 능력으로 자신의 크기를 두 단계 키울 수 있으며, 이때 이동 속도 +10, 힘 +12, 민첩 -2, 건강 +6과 방어도 -2 불이익을 받습니다.", true);
      KoreanLocalization.Add("1ab57d944dab446e9bc623aeadbbc48d", "Isekai Spriggan", "이세계 스프리건", false);
      KoreanLocalization.Add("8acb3f0b39cd4cd588c1d07a601de94a", "Otherworldly entities who are reincarnated into the world of Golarion as a Succubus have both extreme beauty and power, and often have a voracious appetite for sensory pleasures and carnal delights.\nThe Isekai Succubus has a +2 racial {g|Encyclopedia:Bonus}bonus{/g} to {g|Encyclopedia:Dexterity}Dexterity{/g} and {g|Encyclopedia:Intelligence}Intelligence{/g}, a +4 racial bonus to {g|Encyclopedia:Charisma}Charisma{/g}, a -2 {g|Encyclopedia:Penalty}penalty{/g} to {g|Encyclopedia:Strength}Strength{/g}, and a +2 racial bonus on {g|Encyclopedia:Persuasion}Persuasion{/g} and {g|Encyclopedia:Perception}Perception checks{/g}. They have DR 10/Cold Iron or Good, and have spell resistance equal to 10 + their character level. They have immunity to fire, electricity, and poisons as well as acid and cold resistance 20. They can also use the Charm spell once per day.", "골라리온에 서큐버스로 환생한 이세계인은 빼어난 아름다움과 힘을 함께 지니며, 감각적인 쾌락과 육체의 즐거움을 탐하는 경우가 많습니다.\n이세계 서큐버스는 {g|Encyclopedia:Dexterity}민첩{/g}과 {g|Encyclopedia:Intelligence}지능{/g}에 +2 종족 {g|Encyclopedia:Bonus}보너스{/g}를, {g|Encyclopedia:Charisma}매력{/g}에 +4 종족 보너스를 받으며, {g|Encyclopedia:Strength}힘{/g}에는 -2 {g|Encyclopedia:Penalty}불이익{/g}을 받습니다. {g|Encyclopedia:Persuasion}설득{/g}과 {g|Encyclopedia:Perception}지각 판정{/g}에 +2 종족 보너스를 받습니다. 피해 감소 10/한철 또는 선과 10 + 캐릭터 레벨만큼 주문 저항을 지닙니다. 화염, 전격, 독에 면역이며 산성 저항과 냉기 저항 20을 얻습니다. 또한 매혹 주문을 하루에 한 번 사용할 수 있습니다.", true);
      KoreanLocalization.Add("cde9675406c740909fc59f8ccf63aea2", "Isekai Succubus", "이세계 서큐버스", false);
      KoreanLocalization.Add("3a4f6744c89b4de5b90a7aaf0cf2753e", "You can select a rogue talent from a limited set of rogue talents, ignoring any prerequisites for these talents.", "일부 로그 재능 중 하나를 선택할 수 있습니다. 해당 재능의 선행 조건은 무시합니다.", true);
      KoreanLocalization.Add("5ce9fba4ecc443ca8cf883e5872a9b49", "Rogue Talents", "로그 재능", false);
      KoreanLocalization.Add("f1479cb3523d4a38930a8fecae72f992", "Otherworldly entities who are reincarnated into the world of Golarion as a Vampire have both extreme beauty and power. Incredibly beautiful but strikingly grim shades that straddle the line between humanity and vampirekind, they are often single-minded loners intent on a specific goal.\nThe Isekai Vampire has a +4 racial {g|Encyclopedia:Bonus}bonus{/g} to {g|Encyclopedia:Dexterity}Dexterity{/g} and {g|Encyclopedia:Charisma}Charisma{/g}, a -2 {g|Encyclopedia:Penalty}penalty{/g} to {g|Encyclopedia:Constitution}Constitution{/g}, and a +2 racial bonus on {g|Encyclopedia:Persuasion}Persuasion{/g} and {g|Encyclopedia:Perception}Perception checks{/g}. They have DR 10/Magic and Silver, and have fast healing equal to their character level. They have immunity to poison, disease, mind-affecting and death effects as well as cold and electricity resistance 20.", "골라리온에 뱀파이어로 환생한 이세계인은 빼어난 아름다움과 힘을 함께 지닙니다. 인간과 흡혈귀의 경계에 선 이들은 놀랍도록 아름다우면서도 음울한 기운을 풍깁니다. 흔히 홀로 다니며 하나의 목표에 집착합니다.\n이세계 뱀파이어는 {g|Encyclopedia:Dexterity}민첩{/g}과 {g|Encyclopedia:Charisma}매력{/g}에 +4 종족 {g|Encyclopedia:Bonus}보너스{/g}를 받고, {g|Encyclopedia:Constitution}건강{/g}에는 -2 {g|Encyclopedia:Penalty}불이익{/g}을 받습니다. {g|Encyclopedia:Persuasion}설득{/g}과 {g|Encyclopedia:Perception}지각 판정{/g}에 +2 종족 보너스를 받습니다. 피해 감소 10/마법 및 은과 캐릭터 레벨만큼 빠른 치유를 지닙니다. 독, 질병, 정신 영향과 죽음 효과에 면역이며 냉기 저항과 전격 저항 20을 얻습니다.", true);
      KoreanLocalization.Add("80ccd1b65871431ab180d234f24bd930", "Isekai Vampire", "이세계 뱀파이어", false);
      KoreanLocalization.Add("bdfa1df7d4d947adb83ff514cfb60873", "As you grow so does your ability to make new pacts with otherworldy beings other gain other benefits from your existing ones.", "성장할수록 이세계의 존재들과 새 계약을 맺거나, 기존 계약에서 더 많은 혜택을 얻을 수 있습니다.", true);
      KoreanLocalization.Add("3fc3ac497281480cafca9c31d262c62e", "Patrons Blessing", "후원자의 축복", false);
      KoreanLocalization.Add("49d627a530c74b90aa6c1f0320c980cd", "Otherworldly entities who are reincarnated into the world of Golarion as a Wood Elf have both extreme beauty and power. They are a nimble and natural reflection of the elven race.\nThe Isekai Wood Elf has a +4 racial {g|Encyclopedia:Bonus}bonus{/g} to {g|Encyclopedia:Dexterity}Dexterity{/g}, a +2 racial bonus to {g|Encyclopedia:Wisdom}Wisdom{/g} and {g|Encyclopedia:Intelligence}Intelligence{/g}, and a -2 penalty to Constitution. They have spell resistance equal to 10 + their character level. They can also move faster other elves and have a +10 bonus to speed.", "골라리온에 우드 엘프로 환생한 이세계인은 빼어난 아름다움과 힘을 함께 지닙니다. 민첩하고 자연과 조화를 이루는 엘프의 면모를 보여 줍니다.\n이세계 우드 엘프는 {g|Encyclopedia:Dexterity}민첩{/g}에 +4 종족 {g|Encyclopedia:Bonus}보너스{/g}를, {g|Encyclopedia:Wisdom}지혜{/g}와 {g|Encyclopedia:Intelligence}지능{/g}에 +2 종족 보너스를 받고, 건강에는 -2 불이익을 받습니다. 10 + 캐릭터 레벨만큼 주문 저항을 지닙니다. 다른 엘프보다 빨리 움직이며 이동 속도에 +10 보너스를 받습니다.", true);
      KoreanLocalization.Add("78a0591cbe26464d944120dc107b9934", "Isekai Wood Elf", "이세계 우드 엘프", false);
      KoreanLocalization.Add(null, "Enemies within 40 feet of you become shaken and frightened.", "40피트 이내의 적을 동요와 겁먹음 상태로 만듭니다.", false);
      KoreanLocalization.Add("130bed10a5e74508a774d5af0d0420b8", "Killing Intent", "살기", false);
      KoreanLocalization.Add("b71fbd7c91024f1fb8d24ea09054852c", "You have discovered a dark secret of elemental manipulation: you can use the souls of your enemies as fuel for your powers. \nInstead of straining your own body, you can use souls of those who oppose you and unleash devastating blasts of elemental energy. \nYou are a master of soulbinding, a technique that some consider to be unnatural and morbid. \nBut you don’t care about such moral qualms; you only care about your own survival and dominance.", "당신은 원소를 다루는 어두운 비밀을 알아냈습니다. 적의 영혼을 힘의 연료로 쓸 수 있다는 사실을 말입니다.\n자신의 육체를 혹사하는 대신, 맞서는 자들의 영혼을 소모하여 파괴적인 원소 에너지를 쏟아 냅니다.\n당신은 영혼 속박의 달인입니다. 누군가는 그 기술을 부자연스럽고 섬뜩하다고 여기겠지요.\n하지만 그런 도덕적 거리낌은 당신의 관심사가 아닙니다. 중요한 것은 자신의 생존과 지배뿐입니다.", true);
      KoreanLocalization.Add("90c3fe3d7635495fbebeece2fca293b2", "Kinetic Legacy - Soulbinder", "키네티시스트 전승: 영혼 속박자", false);
      KoreanLocalization.Add("4a03b9f796ce4ae8a93f6487eef054fe", "Just like all Kinetic Knights your sanity is somewhat questionable, after all you willingly choose to forego fighting at range and instead choose to use energy blasts as melee weapons...\nAnd why? Because the burning blade looked cool.", "다른 키네틱 나이트들처럼, 당신도 제정신인지 조금 의심스럽습니다. 원거리에서 싸울 수 있는데도, 굳이 에너지 폭발을 근접 무기로 쓰기로 했으니까요…\n왜냐고요? 불타는 검이 멋져 보였거든요.", true);
      KoreanLocalization.Add("9a35e8c2ac2646e184693c0a774d087e", "Kinetic Legacy - Kinetic Knight", "키네티시스트 전승: 키네틱 나이트", false);
      KoreanLocalization.Add("3cbcfaf2137e4c62bdb6dbfde711d6ea", "Most Protagonists only occasionally use kinetic blasts when they think they would look cool.\n But you really love them, and given that there is no other cantrip this overpowered why not?", "대부분의 주인공은 멋을 부리고 싶을 때만 가끔 에너지 폭발을 씁니다.\n하지만 당신은 정말로 그 힘을 사랑합니다. 이렇게 강력한 캔트립은 달리 없는데, 마음껏 쓰지 않을 이유가 있나요?", true);
      KoreanLocalization.Add("c861dfadd16f491ba9c5de9a8b5eb43b", "Kinetic Legacy - Kinetic Lord", "키네티시스트 전승: 원소의 지배자", false);
      KoreanLocalization.Add("38d63e6f3b98410e9e203f973d3f5aa6", "Your soul is stronger than most, for you hail from another world.\nYou command the elements with ease and grace, while others struggle and suffer.\nYou are a noble soul, a revered and feared master of elemental power.", "이세계에서 온 당신의 영혼은 남들보다 강합니다.\n다른 이들이 고통 속에서 힘겹게 다루는 원소를, 당신은 우아하고 손쉽게 지배합니다.\n당신은 고귀한 영혼이자 존경과 두려움을 한몸에 받는 원소의 대가입니다.", true);
      KoreanLocalization.Add("38cf4d5f5fc042ff855c8338e81a2bba", "Kinetic Legacy - Noble Soul", "키네티시스트 전승: 고귀한 영혼", false);
      KoreanLocalization.Add("4969fb4f599246b9a13ea75fbecec022", "The unfathomable willpower needed to fuel your own ascenscion allows you to bend the elements as you see fit. \nAs your divine essence matures you push the limits of your mind ever so far to claim dominion over the fundamental forces of the multiverse, sometimes at the risk of being overwhelmed by them.", "스스로 신격에 오르려는 헤아릴 수 없는 의지로, 당신은 원소를 뜻대로 굴복시킵니다.\n내면의 신성이 성숙할수록 정신의 한계를 거듭 밀어붙여 다중우주의 근원적인 힘을 지배하려 합니다. 때로는 그 힘에 압도당할 위험을 무릅쓰면서 말이지요.", true);
      KoreanLocalization.Add("289bcf08ae554da8a7369b43bc5f5b8b", "Kinetic Legacy - Elemental Ascendent", "키네티시스트 전승: 원소의 초월자", false);
      KoreanLocalization.Add("3cefded81b50434cbd35d006e2aa5461", "First, I joined the bardic college of Wintermoon. \nThen 3 years later, when I got bored with that, I accidentally stumbled into the theives' guild of Whitesnow...\nWhatever the backstory is, you get access to another legacy class feature.", "처음에는 윈터문 음유시인 대학에 들어갔지요.\n3년쯤 지나 싫증이 났을 때, 우연히 화이트스노 도둑 길드에 발을 들였고요…\n과거가 어떻든, 다른 전승의 클래스 능력을 하나 더 얻습니다.", true);
      KoreanLocalization.Add("8eec8b9af648400f8c1d6fbaad1b8679", "Dual Legacy", "이중 전승", false);
      KoreanLocalization.Add("b91a32fec6974e6982bceb2d2c2c2b54", "If not for the gods reincarnating you as an Isekai Hero with great mystic power you would have been...", "신들이 당신을 엄청난 신비의 힘을 지닌 이세계 용사로 환생시키지 않았다면, 당신은 아마…", true);
      KoreanLocalization.Add("7376d474ee6b4c999db61f51265869e1", "Legacy", "전승", false);
      KoreanLocalization.Add("4383bc278a6046c2b80d584a6e98dd1e", "Gain the spells of a Lich.", "리치의 주문을 얻습니다.", true);
      KoreanLocalization.Add("8e1a5453abad4b3b91dfc5b38f502406", "Mythic Lich Spells", "신화 리치 주문", false);
      KoreanLocalization.Add("0684a73e5d874c3eba3627971ccaa869", "You gain resistance against all elements (acid, cold, electricity, fire, and sonic) equal to 10 + 2 times your character level. Your physical attacks are treated as good for the purpose of overcoming {g|Encyclopedia:Damage_Reduction}damage reduction{/g}.", "모든 원소(산성, 냉기, 전격, 화염, 음파)에 대해 10 + 캐릭터 레벨의 2배만큼 저항을 얻습니다. 당신의 물리 공격은 {g|Encyclopedia:Damage_Reduction}피해 감소{/g}를 극복할 때 선 성향으로 취급됩니다.", true);
      KoreanLocalization.Add("79e36de2a3cb46f691542d12d40999a7", "Light Energy Condensation", "빛 에너지 응축", false);
      KoreanLocalization.Add("728a15e5920c40a0b238aa3d6004cd02", "Any {g|Encyclopedia:Spell}spells{/g} dealing {g|Encyclopedia:Damage}damage{/g} now change their dice to d10, if it was not d10 or greater. If it already was d10 or greater, instead the spell deals one additional point of damage per dice rolled.", "{g|Encyclopedia:Damage}피해{/g}를 입히는 {g|Encyclopedia:Spell}주문{/g}의 피해 주사위가 d10보다 작다면 d10으로 바뀝니다. 이미 d10 이상이라면 굴리는 주사위 하나당 피해가 1 증가합니다.", false);
      KoreanLocalization.Add("0bc609e778964c74a80a36ae07404157", "Magical Amplification", "마력 증폭", false);
      KoreanLocalization.Add("3aaec17c89184482b6f97d82906553ea", "Your summoned creatures get a +5 bonus to maximum Hit Points per character level and a +1 bonus to spell penetration, spell DC, spell damage, and saving throws per character level.", "소환수는 당신의 캐릭터 레벨당 최대 생명력에 +5 보너스를 받습니다. 또한 당신의 캐릭터 레벨당 주문 관통, 주문 난이도, 주문 피해와 내성 굴림에 각각 +1 보너스를 받습니다.", false);
      KoreanLocalization.Add("e17bedb2bee24a9a8dbdb4e59aac4589", "Magical Summoning", "마력 소환", false);
      KoreanLocalization.Add("332e155217ff45b59844a16a653cf1d9", "This creature gets a +5 bonus to maximum Hit Points per character level and a +1 bonus to spell penetration, spell DC, spell damage, and saving throws per character level.", "이 크리처는 소환자의 캐릭터 레벨당 최대 생명력에 +5 보너스를 받습니다. 또한 소환자의 캐릭터 레벨당 주문 관통, 주문 난이도, 주문 피해와 내성 굴림에 각각 +1 보너스를 받습니다.", false);
      KoreanLocalization.Add("8ab95433209e47b8bd701c0a4f962763", "Now listen, if you can imbue into and cast your magic through a sword or axe, what exactly prevents you from doing the same with an arrow? \nLet me tell you, the answer is nothing. \nSo watch me as I remain savely at range and give my enemy a nasty suprise when hiding behind his nice large metal shield only made him a bigger more conductive target for the lighting spell I hid in my arrow...", "잠깐, 검이나 도끼에 마법을 담아 시전할 수 있다면 화살로는 왜 못 하겠습니까?\n답은 간단합니다. 못 할 이유가 없지요.\n나는 안전한 거리에서 지켜볼 테니, 커다란 금속 방패 뒤에 숨은 적이 놀라는 모습을 함께 보시죠. 내 화살에 담긴 번개 주문 앞에서는, 그 방패가 녀석을 더 크고 전기가 잘 통하는 표적으로 만들어 줄 뿐이니까요…", true);
      KoreanLocalization.Add("da0f7fd557554042b54715b1a4595d85", "Magus Legacy - Eldritch Archer", "메이거스 전승: 엘드리치 아처", false);
      KoreanLocalization.Add("187b6d92d4c84008ace59d8c0262ce27", "You blend the powers of martial traning and spellcasting into a single style. \nAfter all hundrets of anime/games/books taught you just how dangerous overspecialisation in either art can be.", "당신은 무예와 주문 시전을 하나의 전투 방식으로 융합합니다.\n어느 한쪽에만 지나치게 치우치면 얼마나 위험한지, 수많은 애니메이션과 게임과 책에서 배웠으니까요.", true);
      KoreanLocalization.Add("0543fbb5fbf54e73ac2a7d9059d7ad4a", "Magus Legacy - Magus", "메이거스 전승: 메이거스", false);
      KoreanLocalization.Add("c1eb90eabdb94f1998325bef92e6a91e", "So you were not really into martial arts or physical fighting of any kind. \nMore like hundrets of hours of ballet lessons now serve as he basis of some really good dodging skills. \nNow with magical powers running through your veins you are even more flexible and thus have an even easier time dodging. \nAccording to some elf you met this is actually a special elven form of magic called spell dancing.", "당신은 무술이나 몸싸움에는 별 관심이 없었습니다.\n오히려 수백 시간의 발레 수업이 뛰어난 회피 실력의 밑바탕이 되었지요.\n이제 마력이 혈관을 흐르면서 몸이 한층 유연해져, 공격을 피하기가 더욱 쉬워졌습니다.\n만났던 어떤 엘프에 따르면, 이것은 주문 춤이라는 엘프 특유의 마법이라고 합니다.", true);
      KoreanLocalization.Add("6b1289729aca42a98fec847a08b05d02", "Magus Legacy - Spell Dancer", "메이거스 전승: 주문 무용가", false);
      KoreanLocalization.Add("ee734fa0360d457c8dd0c11fc144651d", "Magus Legacy - Sword Saint", "메이거스 전승: 소드 세인트", false);
      KoreanLocalization.Add("febf31c129ee4357b90ea5053a584cf5", "Allies within 40 feet of you gain a sacred bonus to all attributes equal to 1/2 your character level.", "40피트 이내 아군은 모든 능력치에 당신의 캐릭터 레벨의 절반만큼 신성 보너스를 받습니다.", false);
      KoreanLocalization.Add("cae2ac3f70a54f7f91a465ba4358bcd9", "Majestic Aura", "위엄의 오라", false);
      KoreanLocalization.Add("a5b0c3a998a0407a8a42ce761b1c671c", "This character has a sacred bonus to all attributes equal to 1/2 your character level.", "이 캐릭터는 모든 능력치에 능력 소유자의 캐릭터 레벨의 절반만큼 신성 보너스를 받습니다.", false);
      KoreanLocalization.Add("394d303dc7c34ac2a7d72c62ba30ed7b", "Evil allies within 120 feet of you has an extra attack and deals an additional 5d6 unholy damage.", "120피트 이내의 악 성향 아군은 공격 횟수를 한 번 추가로 얻고, 5d6의 추가 불경 피해를 입힙니다.", false);
      KoreanLocalization.Add("59c2a012154f41cea9f60382b43b5e46", "Overpowered Aura — Malevolent Rage", "초월 오라: 사악한 분노", false);
      KoreanLocalization.Add("3d124c5b9f424052ab860092d4a1a126", "This character has an extra attack and deals an additional 5d6 unholy damage.", "이 캐릭터는 공격 횟수를 한 번 추가로 얻고, 5d6의 추가 불경 피해를 입힙니다.", false);
      KoreanLocalization.Add("1a2ae6972fc34bec8d88e843510adda4", "Aura of Malevolent Rage", "사악한 분노의 오라", false);
      KoreanLocalization.Add("e2a901afa35e4f1999c61127c5557069", "You gain immunity to dazed, dazzled, sleep, confusion, charm, emotion, complusion, and mind-affecting effects.", "몽롱, 눈부심, 수면, 혼란, 매혹, 감정, 강제와 정신 영향 효과에 면역이 됩니다.", true);
      KoreanLocalization.Add("7dc4298041da4d6d8a1efdd1d396a30b", "Master Self-Control", "완전한 자제력", false);
      KoreanLocalization.Add("a0d13a47902f48ff95d9869cb7069a5e", "Each time you cast a summoning {g|Encyclopedia:Spell}spell{/g}, add the highest modifier of Intelligence, Wisdom and Charisma to the total number of creatures summoned.", "소환 {g|Encyclopedia:Spell}주문{/g}을 시전할 때마다, 소환되는 크리처 수에 지능·지혜·매력 수정치 중 가장 높은 값을 더합니다.", false);
      KoreanLocalization.Add("8c4696454556411cae5c24345c907a39", "Overpowered Ability — Master Summoner", "초월 능력: 소환의 대가", false);
      KoreanLocalization.Add("772c95ebd4fe47c0971ea58fa64695cd", "The mastermind has an unparalleled intellect in the new world. They are able to predict the enemies' movements four parallel universes in advance, outsmarting them with mind-boggling strategies using knowledge from their old world.\nYou cast spells like an Arcanist with a number of slots equal to your spells per day.", "책략가는 이세계에서 견줄 이 없는 지성을 자랑합니다. 적이 다음 수를 두기도 전에 네 개의 평행우주 너머까지 내다보고, 전생의 지식에서 끌어낸 기상천외한 계략으로 적을 농락합니다.\n아카니스트와 같은 방식으로 주문을 시전하며, 하루 주문 시전 횟수만큼 주문 슬롯을 얻습니다.", false);
      KoreanLocalization.Add("4ea9945fd971488b968ccf6f3e600f38", "Every move you make is calculated.", "당신의 모든 행동에는 치밀한 계산이 깔려 있습니다.", true);
      KoreanLocalization.Add("9e206fdaceb74c70a9bc048b9426a711", "Genious Legacy", "천재의 전승", false);
      KoreanLocalization.Add("774c61858cb841ba9d65d6aa3cfbce36", "The Mastermind is proficient with all simple and martial weapons and with all armor (heavy, light, and medium). They can cast {g|Encyclopedia:Spell}spells{/g} from this class while wearing armor without incurring the normal {g|Encyclopedia:Spell_Fail_Chance}arcane spell failure chance{/g}, but they incur the normal arcane spell failure chance for arcane spells received from other classes.", "책략가는 모든 단순 무기와 군용 무기, 모든 갑옷(경장, 평장, 중장)에 숙련됩니다. 갑옷을 입어도 이 클래스에서 얻은 {g|Encyclopedia:Spell}주문{/g}에는 일반적인 {g|Encyclopedia:Spell_Fail_Chance}비전 주문 실패 확률{/g}이 적용되지 않습니다. 다른 클래스에서 얻은 비전 주문에는 정상적으로 적용됩니다.", true);
      KoreanLocalization.Add("278757c9221b41cda6ffd7518bbdd194", "Mastermind Proficiences", "책략가의 숙련", false);
      KoreanLocalization.Add("37416d7592ba49a783d55c3171f4c9bd", "At 15th level, you gain a competence {g|Encyclopedia:Bonus}bonus{/g} to your {g|Encyclopedia:Initiative}initiative{/g} {g|Encyclopedia:Check}checks{/g} equal to your {g|Encyclopedia:Intelligence}Intelligence{/g} modifier.", "15레벨에 {g|Encyclopedia:Initiative}우선권{/g} {g|Encyclopedia:Check}판정{/g}에 {g|Encyclopedia:Intelligence}지능{/g} 수정치만큼 능숙 {g|Encyclopedia:Bonus}보너스{/g}를 받습니다.", true);
      KoreanLocalization.Add("b95fc102ea24489abecdeb4c99fad10d", "Mastermind", "책략가", false);
      KoreanLocalization.Add("a465a49d916f4cb88934d4b5038716d0", "Enemies within 120 feet cannot cast spells or use magic items.", "120피트 이내의 적은 주문을 시전하거나 마법 물품을 사용할 수 없습니다.", true);
      KoreanLocalization.Add("68ba3fb93b0f4c83a397cf42deebea09", "This character cannot cast spells or use magic items.", "이 캐릭터는 주문을 시전하거나 마법 물품을 사용할 수 없습니다.", true);
      KoreanLocalization.Add("9e2f7db2604d48cb9448ccd3d7e2f9db", "Masterplan", "완벽한 계획", false);
      KoreanLocalization.Add("c9d2b91583a947fa81b3b9c19acbf6a0", "Your spells ignore spell resistance and spell immunity. Enemies within 120 feet cannot cast spells or use magic items.", "당신의 주문은 주문 저항과 주문 면역을 무시합니다. 120피트 이내의 적은 주문을 시전하거나 마법 물품을 사용할 수 없습니다.", true);
      KoreanLocalization.Add(null, "As a seasoned merchant, you dabble in high-risk ventures. Roll a d20 to determine your return:\n1: No profit (0 gold)\n2-10: Small profit (500-1,000 gold)\n11-19: Moderate profit (1,000-5,000 gold)\n20: Jackpot (50,000-100,000 gold).", "노련한 상인답게 위험한 사업에도 손을 댑니다. d20을 굴려 수익을 결정합니다.\n1: 수익 없음(0골드)\n2-10: 소액 수익(500-1,000골드)\n11-19: 중간 수익(1,000-5,000골드)\n20: 대박(50,000-100,000골드).", false);
      KoreanLocalization.Add(null, "Overpowered Ability — Merchant's Gamble", "초월 능력: 상인의 승부수", false);
      KoreanLocalization.Add("0bce9965857640939a4960f17e52fe96", "Everyone mistakes you for a prodigal genius, treating every action you make as a calculated move in your 1000 year plan. Enemies tremble in fear as meet you, hallucinating a universe-sized gap between them your power level.\nBenefit: You always take the higher of two d20 rolls. Enemies that attack you take the lower of two d20 rolls for one round.", "사람들은 당신을 희대의 천재로 착각하며, 모든 행동을 천 년 계획의 치밀한 포석으로 받아들입니다. 적들은 당신과 마주하기만 해도 공포에 떨고, 당신과 자신 사이에 우주만큼이나 큰 힘의 격차가 있다고 믿습니다.\n효과: d20을 굴릴 때마다 두 번 굴려 더 높은 결과를 사용합니다. 당신을 공격하는 적은 1라운드 동안 d20을 두 번 굴려 더 낮은 결과를 사용합니다.", false);
      KoreanLocalization.Add("d4cfdebdc3e84c4ab1688e5ed971c855", "Overpowered Ability — Meta Luck", "초월 능력: 초월적 행운", false);
      KoreanLocalization.Add("5a0bd8b5b1894f78a2ae3b6b710f32e4", "This character always takes the higher of two d20 rolls.", "이 캐릭터는 d20을 굴릴 때마다 두 번 굴려 더 높은 결과를 사용합니다.", false);
      KoreanLocalization.Add("3b3b971aa1914e56a519829a3efe48c0", "Meta Luck", "초월적 행운", false);
      KoreanLocalization.Add("a8ce25a9863e4c4bb866c9a8dc13a39c", "This creature takes the lower of two d20 rolls.", "이 크리처는 d20을 굴릴 때마다 두 번 굴려 더 낮은 결과를 사용합니다.", true);
      KoreanLocalization.Add("74463cf58e7d42d2b980a68461bbc789", "Meta Luck (Debuff)", "초월적 행운 (약화)", false);
      KoreanLocalization.Add("3a706a4df3a5423ba8b181a168591562", "Your summoned creatures get a +5 bonus to maximum Hit Points per character level and a +1 bonus to Attack, damage, and AC per character level.", "소환수는 당신의 캐릭터 레벨당 최대 생명력에 +5 보너스를 받습니다. 또한 당신의 캐릭터 레벨당 명중 굴림, 피해 굴림과 방어도에 각각 +1 보너스를 받습니다.", false);
      KoreanLocalization.Add("de16216a191f4c32aef670d64159b9aa", "Mighty Summoning", "강대한 소환", false);
      KoreanLocalization.Add("208f79cfc529470fb4b2f92613d91f8f", "This creature gets a +5 bonus to maximum Hit Points per character level and a +1 bonus to Attack, damage, and AC per character level.", "이 크리처는 소환자의 캐릭터 레벨당 최대 생명력에 +5 보너스를 받습니다. 또한 소환자의 캐릭터 레벨당 명중 굴림, 피해 굴림과 방어도에 각각 +1 보너스를 받습니다.", false);
      KoreanLocalization.Add("1531dd68582a4dfb8dc8cc1a6d01302e", "You gain immunity to mind affecting effects.", "정신 영향 효과에 면역이 됩니다.", true);
      KoreanLocalization.Add("65f31ff4070b4fbe8717ecf8d9204468", "Mind Affecting Immunity", "정신 영향 면역", false);
      KoreanLocalization.Add(null, "This creature cannot be mind-controlled again for 1 minute.", "이 크리처는 1분 동안 다시 정신 지배를 당하지 않습니다.", true);
      KoreanLocalization.Add(null, "This creature has been mind-controlled.", "이 크리처는 정신 지배를 당한 상태입니다.", true);
      KoreanLocalization.Add("3b6ff2cb7ad14db0a72f1a92d922d9ca", "Behold the power of a king! All will listen and obey!\nBenefit: You can make any creature fight on your side as if it was your ally. It will {g|Encyclopedia:Attack}attack{/g} your opponents to the best of its ability.", "왕의 힘을 보아라! 모두 내 말을 듣고 복종하리라!\n효과: 크리처를 아군처럼 당신 편에서 싸우게 합니다. 대상은 당신의 적을 최선을 다해 {g|Encyclopedia:Attack}공격{/g}합니다.", false);
      KoreanLocalization.Add(null, "Will negates", "내성 없음", false);
      KoreanLocalization.Add("ce7cbc302ce04658b21f67be42da85e9", "Overpowered Ability — Mind Control", "초월 능력: 정신 지배", false);
      KoreanLocalization.Add("a617a92054f9460499ab3cd1236ce6c9", "Mind Controlled", "정신 지배", false);
      KoreanLocalization.Add("7580ff794d264115abae8359d70bb4d8", "Mind Control Immunity", "정신 지배 면역", false);
      KoreanLocalization.Add("52ef80dae23c42b09df3b60bd5df72a5", "You practiced your martial arts day and night. \nReading chinese cultivation novels in the spare time left. \nBeing reborn and getting access to Ki as such was a dream come true.", "당신은 밤낮으로 무예를 수련했습니다.\n남는 시간에는 중국 선협 소설을 읽었지요.\n환생하여 기를 다룰 수 있게 된 것은 꿈이 이루어진 것이나 다름없습니다.", true);
      KoreanLocalization.Add("82c64788d9a448008622c86b2c4784e1", "Monk Legacy - Daoist Martial Artist", "몽크 전승: 도가 무인", false);
      KoreanLocalization.Add("8cf3a9f5d8f94479a392690fbf797dd7", "You have a dragon in your dantian!", "당신의 단전에 드래곤이 깃들었습니다!", true);
      KoreanLocalization.Add("8758b9dc56034583810f41a03d4706ae", "Monk Legacy - Fist of a Dragon", "몽크 전승: 용의 주먹", false);
      KoreanLocalization.Add("56907137735c4015bd51d45e8d806b05", "You gain immunity to movement impairing effects.", "이동을 방해하는 효과에 면역이 됩니다.", true);
      KoreanLocalization.Add("8af1c8fbb9fb43bc8cb4b0580bdf1583", "Movement Impairing Immunity", "이동 방해 면역", false);
      KoreanLocalization.Add("f6c9917c58e441b99dcd47e667989e9a", "You emit a small aura of mundanity, giving you immunity to Sneak attack damage and {g|Encyclopedia:Critical}critical hits{/g}.", "작은 평범함의 오라를 내뿜어, 암습 피해와 {g|Encyclopedia:Critical}치명타{/g}에 면역이 됩니다.", true);
      KoreanLocalization.Add("c7417cd905f64d109f030972f33e4a2b", "Mundane Aura", "평범함의 오라", false);
      KoreanLocalization.Add("4b3337f261b743b1956f05138126cef1", "The God Emperor gains an inherent bonus to all attributes equal to 1/2 their character level and {g|Encyclopedia:Damage_Reduction}DR{/g}/— and spell resistance equal to their character level.\nAs they increase their level, they gain more immunities.", "신황은 모든 능력치에 캐릭터 레벨의 절반만큼 고유 보너스를 받으며, 캐릭터 레벨만큼 {g|Encyclopedia:Damage_Reduction}피해 감소{/g}/—와 주문 저항을 얻습니다.\n레벨이 오를수록 더 많은 면역을 얻습니다.", true);
      KoreanLocalization.Add("b8668c4ffc6845acbf59299843b7eb15", "Nascent Apotheosis", "신성의 발현", false);
      KoreanLocalization.Add("d25fabeb02fa43bfa624ac310cb64ccd", "You gain immunity to the nauseated condition.", "구토에 면역이 됩니다.", true);
      KoreanLocalization.Add("18c481786fb844c1aaf21902a4056f0a", "Nauseated Immunity", "구토 면역", false);
      KoreanLocalization.Add("b63b2074fa1849d599e79e504fab8bcb", "You decide not to abuse your power.", "당신은 힘을 남용하지 않기로 합니다.", true);
      KoreanLocalization.Add("0e8e8f4305dc40b7a9da22a0a03f23d4", "Any {g|Encyclopedia:Attack}attacks{/g} you make have their {g|Encyclopedia:Damage}damage{/g} multiplier increased by 1 (×2 becomes ×3, for example).", "당신의 모든 {g|Encyclopedia:Attack}공격{/g}의 치명타 {g|Encyclopedia:Damage}피해{/g} 배율이 1 증가합니다(예: ×2가 ×3으로 증가).", true);
      KoreanLocalization.Add("a456239d904d4b7aa7bd102a9533b8f7", "Omega Strike", "오메가 스트라이크", false);
      KoreanLocalization.Add("fae6ba88703540dea33aafe849144753", "Seekers of Truth are driven by a desire to uncover the secrets behind the fundamental forces of nature. \nBecause of their unique perspective as otherworlders, they are able to approach the world with a fresh and unbiased eye, allowing them to see beyond the surface of things and seek out the deeper truth behind the world around them. \nThey are driven by a desire to uncover the secrets of the world that would otherwise remain hidden, and are not satisfied with simply accepting things at face value. \nThis allows them to uncover the secrets of the world that are often only revealed to mortals through revelations.\n\nPlease note that you do not get previous inheritances when seletcing this at higher levels.", "진리의 탐구자는 자연의 근원적인 힘에 숨겨진 비밀을 밝히려 합니다.\n이세계인 특유의 시선으로 선입견 없이 세상을 바라보기에, 겉모습 너머의 깊은 진실을 찾아낼 수 있습니다.\n이들은 숨겨진 세계의 비밀을 알고자 하며, 눈에 보이는 것을 그대로 받아들이는 데 만족하지 않습니다.\n덕분에 보통 필멸자에게는 계시를 통해서만 드러나는 비밀까지 밝혀낼 수 있습니다.\n\n높은 레벨에서 이 전승을 선택해도 이전 레벨의 계승 능력을 소급해서 얻지는 않습니다.", true);
      KoreanLocalization.Add("81c19bd68df4480091c510094d6b28b8", "Oracle Legacy - Seeker of Truth", "오라클 전승: 진리의 탐구자", false);
      KoreanLocalization.Add("d7e668b04d22401587a735b98e6a1884", "At 13th Level, you become immune to fatigue and exhaustion.", "13레벨에 피로와 탈진에 면역이 됩니다.", true);
      KoreanLocalization.Add("e1393605864e46769dc9a1a3022498b2", "Otherworldly Stamina", "이세계의 체력", false);
      KoreanLocalization.Add("4a4a92bbbae84a948f45cb91ab8df551", "After obtaining ungodly amounts of power, some protagonists become Overlords. They view the new world as theirs to play with, and the new inhabitants as theirs to torment. Overlords seek to increase their power even further, often by establishing their own kingdom.", "터무니없는 힘을 손에 넣은 주인공 중에는 패왕이 되는 이들도 있습니다. 이들에게 새로운 세계는 제멋대로 주무를 놀이터이고, 그곳의 주민들은 괴롭힐 대상일 뿐입니다. 패왕은 더 큰 힘을 추구하며, 흔히 자신만의 왕국을 세우려 합니다.", false);
      KoreanLocalization.Add("67cb605f5664412786fe9bdb2889a91e", "You have a dark and secret past.", "당신에게는 어둡고 은밀한 과거가 있습니다.", true);
      KoreanLocalization.Add("1a913250f7444cd9ad36780fb5bcc402", "Evil Legacy", "어둠의 전승", false);
      KoreanLocalization.Add("7fcb64213f6545889dcc9785cac85825", "The Overlord is proficient with all simple, martial, and exotic weapons and with all armor (heavy, light, and medium) and shields (including tower shields). They can cast {g|Encyclopedia:Spell}spells{/g} from this class while wearing armor and shields (including tower shields) without incurring the normal {g|Encyclopedia:Spell_Fail_Chance}arcane spell failure chance{/g}, but they incur the normal arcane spell failure chance for arcane spells received from other classes.", "패왕은 모든 단순 무기, 군용 무기, 특수 무기와 모든 갑옷(경장, 평장, 중장), 모든 방패(타워 실드 포함)에 숙련됩니다. 갑옷이나 방패(타워 실드 포함)를 착용해도 이 클래스에서 얻은 {g|Encyclopedia:Spell}주문{/g}에는 일반적인 {g|Encyclopedia:Spell_Fail_Chance}비전 주문 실패 확률{/g}이 적용되지 않습니다. 다른 클래스에서 얻은 비전 주문에는 정상적으로 적용됩니다.", true);
      KoreanLocalization.Add("cd18ad0a4aa0467bb398bdc548606135", "Overlord Proficiences", "패왕의 숙련", false);
      KoreanLocalization.Add("78b5966e9b454ee49355f99a5570777c", "Overlord", "패왕", false);
      KoreanLocalization.Add("5bfdc51bfdb043aa98a296baf7f748e7", "You use your mythic powers to gain an additional Overpowered Ability.\nSource: Isekai Mod", "신화의 힘으로 초월 능력을 하나 더 얻습니다.\n출처: 이세계 모드", true);
      KoreanLocalization.Add("6e3f20652da843f88c0fd19b6a6d169e", "Mythic Overpowered Ability", "신화 초월 능력", false);
      KoreanLocalization.Add("d7e5ec87d46d4c97b9b0818ac5b769d9", "As a being from another world, you are granted an Overpowered Ability which no ordinary being in this world possess.", "당신은 다른 세계에서 온 존재로서, 이 세계의 평범한 존재는 가질 수 없는 초월 능력을 받습니다.", true);
      KoreanLocalization.Add("4adad3f6a40f458794d0a8c7fdd2cf71", "Overpowered Ability", "초월 능력", false);
      KoreanLocalization.Add("2f74ff7594534e069c495ffa987476cd", "Overlords get to select additional Overpowered Abilities.", "패왕은 초월 능력을 추가로 선택할 수 있습니다.", true);
      KoreanLocalization.Add("821fdd1e4b4841af9636356f5518d310", "Additional Overpowered Ability", "추가 초월 능력", false);
      KoreanLocalization.Add("b1066d67b2104020b6eb3f2e76baf3ae", "You gain an Overpowered Aura that greatly enhances the combat ability of your allies.", "아군의 전투 능력을 크게 강화하는 초월 오라를 얻습니다.", true);
      KoreanLocalization.Add("be2dcb987803428ba309869216c97bc3", "Overpowered Aura", "초월 오라", false);
      KoreanLocalization.Add("073d375478884026abf1082f0d0409ff", "You are a true hero, representing all that is good and holy in the world.\nProtecting the innocent and smiting the evil.\nLess benevolent people might actually throw up a little just from talking to you just because of how inherently good you are.", "당신은 세상의 선하고 성스러운 모든 것을 대변하는 진정한 용사입니다.\n무고한 이를 지키고 악을 강타하지요.\n당신이 워낙 선한 나머지, 덜 고결한 사람들은 대화만 나눠도 속이 조금 메스꺼울지도 모릅니다.", true);
      KoreanLocalization.Add("6dbd280ee2d543a48c33df551e8054e5", "Paladin Legacy - Hero of Light", "팔라딘 전승: 빛의 용사", false);
      KoreanLocalization.Add("674fffa1b2c14569b01eb4ee27bdf29b", "You gain immunity to paralysis.", "마비에 면역이 됩니다.", true);
      KoreanLocalization.Add("5be010c641ca4f5092380db06f270c70", "Paralyzed Immunity", "마비 면역", false);
      KoreanLocalization.Add("835c3aee3ccf4e33812281bb17ab7b38", "At 12th level, you transform the damage you deal into either divine or unholy.", "12레벨에 자신이 입히는 피해를 신성 또는 불경 피해로 바꿀 수 있습니다.", true);
      KoreanLocalization.Add("dce64ae852f145caa9dbc21af9c54507", "Chosen Path", "선택한 길", false);
      KoreanLocalization.Add(null, "You navigate every conversation and fight with perfect accuracy. Every word is predicted; every action is foreseen. Your premonitions guide you on your quest, as if you have experienced this before...\nBenefit: You gain a +5 bonus to all d20 rolls.", "모든 대화와 전투를 한 치의 오차도 없이 헤쳐 나갑니다. 모든 말을 예측하고, 모든 행동을 내다봅니다. 마치 이 일을 이미 겪어 본 듯한 예감이 당신의 여정을 이끕니다…\n효과: 모든 d20 굴림에 +5 보너스를 받습니다.", true);
      KoreanLocalization.Add("820e1ba252ab43c2b2e5ff637cdfc006", "Overpowered Ability — Perfect Roll", "초월 능력: 완벽한 굴림", false);
      KoreanLocalization.Add("0b3fc95e467d4393a4b565fa7ff24cc1", "You gain immunity to petrification.", "석화에 면역이 됩니다.", true);
      KoreanLocalization.Add("5df4ed910c894db2b0e6a51a9640fa95", "Petrified Immunity", "석화 면역", false);
      KoreanLocalization.Add("85c6e789b3ba4c8daf57f8ab3b104ee6", "You were a computer nerd in your last life, you get a +10 Bonus to Knowledge(Programming) and +5 to your MMORPG Skill.\nWait what do you mean there are no computers in this world and all that knowledge and skill is useless?\nWell at least some of the theoretical knowledge about magic is applicable in this world...", "전생에 컴퓨터광이었던 당신은 지식(프로그래밍)에 +10 보너스를, MMORPG 실력에 +5 보너스를 받습니다.\n잠깐, 이 세계에는 컴퓨터가 없어서 그 지식과 실력이 전부 쓸모없다고요?\n뭐, 적어도 마법에 관한 이론 지식 일부는 여기서도 통하겠지요…", true);
      KoreanLocalization.Add("70d087c80d674a72ba551568da2eaa79", "Player Legacy - Computer Nerd", "플레이어 전승: 컴퓨터광", false);
      KoreanLocalization.Add("d68635b228694ffe94d7f40c631b6f66", "You were a part time worker bouncing from job to job. \nYou know how to learn the basics of a new job and ultimately all thse classes are just a different type of job. \nSure picking up the next one takes a while, but ultimately you will be the master of all.", "당신은 여러 일자리를 전전하던 아르바이트생이었습니다.\n새로운 일의 기초를 익히는 법은 잘 압니다. 결국 이 클래스들도 서로 다른 직업일 뿐이잖아요.\n다음 일을 배우는 데 시간이 조금 걸리기는 하겠지만, 언젠가는 전부 통달할 겁니다.", true);
      KoreanLocalization.Add("d214c1a5cf514f13a5b383f33a0f2895", "Player Legacy - Part Timer", "플레이어 전승: 아르바이트생", false);
      KoreanLocalization.Add("457405fbd37c412f96c2be6b5109c612", "You gain a luck bonus to {g|Encyclopedia:Armor_Class}AC{/g} and all {g|Encyclopedia:Saving_Throw}saving throws{/g} equal to your character level.", "{g|Encyclopedia:Armor_Class}방어도{/g}와 모든 {g|Encyclopedia:Saving_Throw}내성 굴림{/g}에 캐릭터 레벨만큼 행운 보너스를 받습니다.", true);
      KoreanLocalization.Add("da11c8d27ffe43a096f87d97e7a7f569", "You gain immunity to poison.", "독에 면역이 됩니다.", true);
      KoreanLocalization.Add("bfca7a87593f4dbb905b092db9cca03c", "Poison Immunity", "독 면역", false);
      KoreanLocalization.Add(null, "Overpowered Surge", "압도적인 기세", false);
      KoreanLocalization.Add(null, "Defeating enemies grants temporary bonuses to the party.", "이 오라의 영향을 받는 아군은 명중 굴림과 인내 내성에 +2 보너스를 받습니다.", true);
      KoreanLocalization.Add(null, "You are Overpowered but overly cautious. You use overwhelming force to ensure all enemies you kill are thoroughly defeated.\nBenefit: When enemies are defeated within a 120-foot radius of you, your party gains temporary bonuses to their attack and saving throws.", "당신은 압도적으로 강하지만 지나칠 만큼 신중합니다. 쓰러뜨린 적이 확실히 끝장났는지 확인하기 위해서라도 압도적인 힘을 쏟아붓습니다.\n효과: 120피트 이내 아군은 명중 굴림과 인내 내성에 +2 보너스를 받습니다.", false);
      KoreanLocalization.Add("ba6a358f3cad4a3c9f433f74c4eced75", "Overpowered Ability — Power Leveling", "초월 능력: 파워 레벨링", false);
      KoreanLocalization.Add("ddf3c947248c45d7899361461b729de1", "At 15th level, you are able to ascend into a higher plane of existence and harness its energies.", "15레벨에 더 높은 존재의 차원으로 올라, 그곳의 에너지를 끌어 쓸 수 있습니다.", true);
      KoreanLocalization.Add("da5a89c840b74c2dad7da1b82525c3e8", "Transcendental Realm", "초월의 영역", false);
      KoreanLocalization.Add("7e9f8ccf4e784d5ab2bfd0af27998799", "You deal damage to enemies equal to the damage you receive.", "적에게 자신이 받은 피해만큼 피해를 되돌려 줍니다.", false);
      KoreanLocalization.Add("6fdb80fe28244d5487c28a3dfd67200a", "Reflect", "반사", false);
      KoreanLocalization.Add("e86a9183a3b64091b45c6aacd0081f89", "You regain 10 hit points per round and cannot die while regeneration is functioning. Regeneration is disabled for 1 round when you are hit with an acid or fire attack. ", "라운드마다 생명력을 10 회복하며, 재생이 작동하는 동안에는 죽지 않습니다. 산성 또는 화염 공격에 맞으면 1라운드 동안 재생이 억제됩니다.", true);
      KoreanLocalization.Add("ba7c150e77c64edba2b2b041635895c1", "Regeneration", "재생", false);
      KoreanLocalization.Add("b6abff98b3e5478e80513e08b2202014", "The Isekai Protagonist is able to channel both positive energy and negative energy.\nSo this what happens when you channel one percent of your power...", "이세계 주인공은 양에너지와 음에너지를 모두 전달할 수 있습니다.\n이것이 고작 힘의 1퍼센트를 방출한 결과라니…", true);
      KoreanLocalization.Add("9fbacbb9c7c443fd87c95ec11d57c945", "Release Energy", "에너지 방출", false);
      KoreanLocalization.Add("b5106009451f4c20adf1244eb5972d6d", "The damage you deal is now divine damage.", "당신이 입히는 피해가 신성 피해로 바뀝니다.", false);
      KoreanLocalization.Add("b4c816a956544211a641d2815e5aac29", "Righteous Path", "정의의 길", false);
      KoreanLocalization.Add("470c92ecf6f94e8db473a385976d7ec7", "Good allies within 120 feet of you has an extra attack and deals an additional 5d6 holy damage.", "120피트 이내의 선 성향 아군은 공격 횟수를 한 번 추가로 얻고, 5d6의 추가 성스러운 피해를 입힙니다.", false);
      KoreanLocalization.Add("6ef0f2ed6aac4b3eb7c51c91f7b6f1f8", "Overpowered Aura — Righteous Wrath", "초월 오라: 정의로운 분노", false);
      KoreanLocalization.Add("395d68c4bb2c47b8bbdef52bff2fd7fe", "This character has an extra attack and deals an additional 5d6 holy damage.", "이 캐릭터는 공격 횟수를 한 번 추가로 얻고, 5d6의 추가 성스러운 피해를 입힙니다.", false);
      KoreanLocalization.Add("72252fd0500b4af1b3fe772096c87c34", "Aura of Righteous Wrath", "정의로운 분노의 오라", false);
      KoreanLocalization.Add("8ab4843d416c48ee972a215ad80e3985", "Your reincarnation gave you great power; that is no reason to forget the usefulness of a simple backstab.", "환생하여 엄청난 힘을 얻었다고 해서, 단순한 기습의 유용함을 잊을 이유는 없습니다.", true);
      KoreanLocalization.Add("d1ac0538725f4aad9d60ea6853865d39", "Rogue Legacy - Supernatural Thief", "로그 전승: 초자연적인 도둑", false);
      KoreanLocalization.Add("c1e24b34661a4c6da5a3164d9a2f6ba8", "Once per day, when your {g|Encyclopedia:HP}HP{/g} drops to 0, you are resurrected to full health. You also gain a +10 profane bonus to all attributes and your size also increases by one size category for 24 hours.", "휴식마다 한 번, 사망하면 {g|Encyclopedia:HP}생명력{/g}을 모두 회복한 상태로 부활합니다.", false);
      KoreanLocalization.Add("187a6c810cb747a7bc87d5f8d1778b7c", "You gain a +10 profane bonus to all attributes and your size increases by one size category for 24 hours.", "모든 능력치에 +10 불경 보너스를 받고 크기가 한 단계 커집니다. 크기 변화로 힘에 +2, 민첩에 -2의 크기 수정치가 추가로 적용됩니다.", true);
      KoreanLocalization.Add("ed759586e5ac4233823e83b17b99d445", "Second Phase", "두 번째 형태", false);
      KoreanLocalization.Add("c23372f42a4a4eed8ff9105fce53cdae", "Your attacks ignore damage reduction and your spells ignore spell resistance and spell immunity.\nOnce per day, when your {g|Encyclopedia:HP}HP{/g} drops to 0, you are resurrected to full health.", "당신의 공격은 피해 감소를 무시하고, 주문은 주문 저항과 주문 면역을 무시합니다.\n휴식마다 한 번, 사망하면 {g|Encyclopedia:HP}생명력{/g}을 모두 회복한 상태로 부활합니다.", false);
      KoreanLocalization.Add("632c39a1e0274a36b8ca033ceb8eda6b", "Second Reincarnation", "두 번째 환생", false);
      KoreanLocalization.Add("fe688cf7a5e44c69b43118dcfe9ab8e3", "On the verge of defeat, you were somehow able to draw out your secret power...", "패배 직전, 당신은 어떻게든 숨겨진 힘을 끌어낼 수 있었습니다…", true);
      KoreanLocalization.Add("1d6dcd0b60bf4a419c82c6a126c07d47", "Secret Power", "숨겨진 힘", false);
      KoreanLocalization.Add("311adde506b74c9d924fe7784d3df8fe", "Enemies die in one hit.", "적을 한 방에 죽입니다.", true);
      KoreanLocalization.Add("405f53b3195a49aa8a6d683b8b8d07f3", "Serious Strike", "진심 일격", false);
      KoreanLocalization.Add("35d76074ed464719ae7c87b080f0ab27", "Allies within 40 feet of you transform their damage type into unholy.", "40피트 이내 아군이 입히는 피해의 유형이 불경으로 바뀝니다.", false);
      KoreanLocalization.Add("ae653272055c4db586ab1a5db31d6058", "Shadow Realm", "그림자의 영역", false);
      KoreanLocalization.Add("d4c24a9b1e6a4738ab87782545dab9f5", "This character transforms their damage type into unholy.", "이 캐릭터가 입히는 피해의 유형이 불경으로 바뀝니다.", false);
      KoreanLocalization.Add("2a62cc6ee03b4ce69bcaaa9290a09f7a", "You gain immunity to shaken effects.", "동요에 면역이 됩니다.", true);
      KoreanLocalization.Add("b85b2c6365d84326b1dc2dcc3b359b39", "Shaken Immunity", "동요 면역", false);
      KoreanLocalization.Add("8c22ee0362794a3890d02e63df28c2e4", "As persons who originated from the other worlds, Spirit Beacons have an unique aura. \nThis aura is particularly attractive to spirits, and they have learned to harness the power of these spirits by forming contracts with them. \nDespite their reliance on spirits, Spirit Beacons are not bound by the will of these supernatural beings. \nThey are able to maintain their independence and make their own decisions, using the power of the spirits as a tool rather than being controlled by them.", "다른 세계에서 온 영혼의 등대는 독특한 오라를 지닙니다.\n영혼들이 유난히 이 오라에 이끌리기에, 이들은 영혼과 계약을 맺어 그 힘을 다루는 법을 배웠습니다.\n영혼의 힘을 빌리지만, 그 초자연적인 존재들의 의지에 얽매이지는 않습니다.\n자신의 뜻에 따라 판단하고 행동하며, 영혼에게 지배당하는 대신 그 힘을 도구로 사용합니다.", true);
      KoreanLocalization.Add("241fd57a877442f7b8acac70d10d83b2", "Shaman Legacy - Spirit Beacons", "샤먼 전승: 영혼의 등대", false);
      KoreanLocalization.Add("bb3d3b494f9f4449833bb450cc996ae7", "You have a connection to nature, maybe one of your ancestors as a were creature or a druidic circle initiated you into the secrets of shapeshifting, regardless of the source you have a connection to the animal kingdrom enabling you to shapeshift. \nAs a result of the nature of your shapeshifter ability you have less choice (you will never be a tree or an elemental) but greater control, allowing for partial shifts.", "당신은 자연과 이어져 있습니다. 조상 중에 야수인간이 있었거나 드루이드 집회에서 변신의 비법을 배웠을지도 모릅니다. 그 근원이 무엇이든, 동물계와의 유대로 모습을 바꿀 수 있습니다.\n이 변신 능력은 선택의 폭이 좁은 대신(나무나 정령이 될 수는 없습니다), 제어가 정밀하여 몸의 일부만 바꿀 수도 있습니다.", true);
      KoreanLocalization.Add("38f0cf5793934ab683a82398b1203322", "Shifter Legacy - Beast Shifter", "시프터 전승: 야수 변신자", false);
      KoreanLocalization.Add("5048f50b8b5f4bb48563c7b71c348d3f", "When reincaranting you wanted to be a dragon. \nBecause dragons are cool! \nBut sadly  that would have been too balancebreaking according to the god of reincarnation. \nWeirdly enough being a shapeshifted baby dragon that learns to reassume his natural form with time is not. \nSo one day you will soar through the sky in your draconic form. \nDragon Claws are useful in the meantime...", "당신은 환생할 때 드래곤이 되고 싶었습니다.\n드래곤은 멋지니까요!\n안타깝게도 환생의 신은 그건 너무 균형을 무너뜨린다고 했습니다.\n그런데 이상하게도, 다른 모습으로 변한 새끼 드래곤이 시간이 흐르며 본모습을 되찾는 건 괜찮다네요.\n그러니 언젠가는 드래곤의 모습으로 하늘을 날 겁니다.\n그때까지는 드래곤의 발톱도 꽤 쓸 만하겠지요…", true);
      KoreanLocalization.Add("9fcb1b6fd01e4045ae0f5fa5573adf2a", "Shifter Legacy - Shapeshifted Baby Dragon", "시프터 전승: 모습을 감춘 새끼 드래곤", false);
      KoreanLocalization.Add("f9ef92f960b14bae8ccc34c139fe6e35", "Skinwalkers are rare and dangerous predators that choose to exist above the natural order. \nRather than communing with nature like the druids, Skinwalkers are known to choose a powerful predator, often times protectors of forests or mountains, before stalking them from the shadows until they find an opportune moment to lay a trap and claim their life. \nThey will then ritually skin their prey before donning their hide and using it to transform into a semblance of its once mighty owner. \nMany a novice necromancer has actually looked at you in horror at the realization of just what this ritual skinning involved, because he originally thought he was the evil member of the group.", "스킨워커는 자연의 질서 위에 서기를 택한 희귀하고 위험한 포식자입니다.\n드루이드처럼 자연과 교감하는 대신, 숲이나 산을 지키는 강력한 포식자를 골라 그림자 속에서 뒤쫓다가 기회를 노려 덫을 놓고 목숨을 빼앗습니다.\n그런 다음 의식을 치르며 사냥감의 가죽을 벗겨 뒤집어쓰고, 한때 강대했던 그 주인의 모습을 흉내 냅니다.\n초보 네크로맨서들조차 그 의식이 무엇을 뜻하는지 깨닫고는 당신을 공포에 질린 눈으로 보곤 합니다. 이 일행에서 사악한 역할은 자기 몫인 줄 알았거든요.", true);
      KoreanLocalization.Add("4e8488f480d9480bb42677e7befe12aa", "Shifter Legacy - Skinwalker", "시프터 전승: 스킨워커", false);
      KoreanLocalization.Add("7eef5ed19e0c4f6f844359e2ef0d5033", "Why does everyone always think of dragons first?\nWe griffons are cool too and unlike dragons we are actually reliable servants of the divine and the symbol of nobility. \nSo just sit back and watch me save this world after that dragon messed up, as dragons always do...", "왜 다들 드래곤부터 떠올리는 걸까요?\n우리 그리폰도 멋집니다. 게다가 드래곤과 달리 믿음직한 신의 종이자 고귀함의 상징이지요.\n그러니 드래곤이 늘 그렇듯 일을 망쳐 놓은 뒤에, 내가 이 세계를 구하는 모습을 편히 지켜보세요…", true);
      KoreanLocalization.Add("b95b73bb24924c78958675794e6a3fac", "Shifter Legacy - Shapeshifted Griffon", "시프터 전승: 모습을 감춘 그리폰", false);
      KoreanLocalization.Add("324471f9bbff455298e2493451cb36b9", "Your reincarnation was the action of a god. \nThey send you to this world to be a hero, so while you feel a connection to nature this connection is in a way \"tainted\" by that divine connection. \nYour kin are not the normal animals roaming the woods but the divine beasts of your deities realm.", "당신을 환생시킨 것은 신입니다.\n용사가 되라고 이 세계에 보냈기에, 자연과의 유대에도 그 신성한 연결이 일종의 \"흔적\"을 남겼습니다.\n당신과 이어진 존재들은 숲을 떠도는 평범한 동물이 아니라, 신이 다스리는 영역의 신성한 야수들입니다.", true);
      KoreanLocalization.Add("1d6c3464d981479e8e8a254c585c5d80", "Shifter Legacy - Divine Beast", "시프터 전승: 신성한 야수", false);
      KoreanLocalization.Add("6d1114aa691743abac83d9d5e365e51e", "Some things cannot be easily forgotten, and in your dreaded former life you were called a hedgehog... \nBut this new world shall be respectful to your newfound stingers, as they are even more dangerous than your sharp tongue.", "쉽게 잊히지 않는 일도 있습니다. 지긋지긋했던 전생에 당신은 고슴도치라 불렸지요…\n하지만 이 세계에서는 새로 얻은 가시에 존중을 표해야 할 겁니다. 날카로운 혀보다도 훨씬 위험하니까요.", true);
      KoreanLocalization.Add("362da6c469324c6db3bfd0c6d4cd1004", "Shifter Legacy - Stinger", "시프터 전승: 가시 사수", false);
      KoreanLocalization.Add("7156f58b097a4a378cab08e4a113d48a", "Your attacks have Shock. They deal an additional 1d6 electricity damage.", "당신의 공격에 전격 효과가 적용되어 1d6의 추가 전격 피해를 입힙니다.", false);
      KoreanLocalization.Add("2414629606374bfea0dfbdfccbba4f9c", "Shock Weapon", "전격 무기", false);
      KoreanLocalization.Add("d245102c20954644a9aa46f392a24e57", "You gain immunity to the sickened condition.", "고통에 면역이 됩니다.", true);
      KoreanLocalization.Add("ed4dc673f7244af4a6ae65f5e8fc11b0", "Sickened Immunity", "고통 면역", false);
      KoreanLocalization.Add("43c4d41ae74e4eceb2d2925cb111e872", "Your critical threat range is increased by 2.", "치명타 위협 범위가 2 증가합니다.", true);
      KoreanLocalization.Add("a17cc32d3b124e8aa05cddcfd8942f32", "Sigma Strike", "시그마 스트라이크", false);
      KoreanLocalization.Add("cd06732066ab473685ada7c4a2462fb9", "You gain a bonus to spell DC and spell hit point damage equal to 1/2 your character level.", "주문 난이도와 주문이 입히는 생명력 피해에 캐릭터 레벨의 절반만큼 보너스를 받습니다.", true);
      KoreanLocalization.Add("ff8b1fc00b8f42c793939cac4ffe1da3", "Signature Ability", "고유 능력", false);
      KoreanLocalization.Add("0f35634e2a224667a6e75c821b09b8a9", "You gain a luck bonus to {g|Encyclopedia:BAB}attack{/g} and damage rolls equal to 1/2 your character level.", "{g|Encyclopedia:BAB}명중{/g} 굴림과 피해 굴림에 캐릭터 레벨의 절반만큼 행운 보너스를 받습니다.", true);
      KoreanLocalization.Add("7d5527f2ca3c467885b56d984f3c3a34", "Signature Attack", "고유 공격", false);
      KoreanLocalization.Add("7033fc92b9ca43b795f647aae6b9a6f3", "Another Signature Move", "추가 필살기", false);
      KoreanLocalization.Add("3eec77c7d5c141b4a88427a7c50340e1", "At 6th level, you choose a signature move.", "6레벨에 필살기를 하나 선택합니다.", false);
      KoreanLocalization.Add("e867a214a5ad4eff83526dbb158cb065", "Signature Move", "필살기", false);
      KoreanLocalization.Add("a8f7c30b30e3428b8e4935c1e01a1e30", "You gain an additional 1d6 sneak attack damage equal to 1/2 your Isekai Protagonist class level.", "이세계 주인공 클래스 레벨의 절반만큼 암습 피해 주사위가 1d6씩 증가합니다.", true);
      KoreanLocalization.Add("e72bfae4c3e343ffac25ad42c8ace072", "Signature Strike", "고유 일격", false);
      KoreanLocalization.Add("1ac1ca5beaab4e15861f3ee098001644", "Enemies within 40 feet of you take a penalty on all attributes equal to 1/2 your character level.", "40피트 이내의 적은 모든 능력치에 당신의 캐릭터 레벨의 절반만큼 불이익을 받습니다.", false);
      KoreanLocalization.Add("c7e4694467144948b5458ea07aad6d36", "Siphoning Aura", "흡수의 오라", false);
      KoreanLocalization.Add("049a62b2d72442298d8d8e10ae9e94f1", "This creature has a penalty on all attributes equal to 1/2 your character level.", "이 크리처는 모든 능력치에 능력 소유자의 캐릭터 레벨의 절반만큼 불이익을 받습니다.", false);
      KoreanLocalization.Add("751fe644ef06498baa088df10640d745", "As a standard action, increase your size by two size categories and gain +10 Speed, +12 Strength, -2 Dexterity, +6 Constitution, and a -2 penalty to AC.", "표준 행동으로 크기를 두 단계 키웁니다. 이동 속도 +10, 힘 +12, 민첩 -2, 건강 +6과 방어도 -2 불이익을 받습니다.", true);
      KoreanLocalization.Add("0ff5fd2e0282492b990875291ee2e433", "This creature's size is increased by two size categories and they gain +10 Speed, +12 Strength, -2 Dexterity, +6 Constitution, and a -2 penalty to AC.", "이 크리처는 크기가 두 단계 커지고, 이동 속도 +10, 힘 +12, 민첩 -2, 건강 +6과 방어도 -2 불이익을 받습니다.", true);
      KoreanLocalization.Add("dd486297ac20490faf72a97ab0e28e6c", "Size Alteration", "크기 변형", false);
      KoreanLocalization.Add("597f2733426c47abb7ca1c01fed97321", "Your songs scream out your rage at the world. \nInspiring your allies to rage along with your songs.", "당신의 노래는 세상을 향한 분노를 절규합니다.\n아군도 그 노래에 이끌려 함께 분노하지요.", true);
      KoreanLocalization.Add("6b075500d8d540cc88323fb0bf95df3c", "Skald Legacy - Metal Singer", "스칼드 전승: 메탈 가수", false);
      KoreanLocalization.Add("ceed75eb615446fea21e7dc76186aba6", "You were a flatterer in your past life, and learned to hone your skills to a ridiculous level. \nNo Queen can resist you, and that's a real advantage in these dark times.", "전생에 아첨꾼이었던 당신은 그 재주를 터무니없는 경지까지 갈고닦았습니다.\n어떤 여왕도 당신을 거부하지 못합니다. 이런 암울한 시대에는 꽤 큰 장점이지요.", true);
      KoreanLocalization.Add("afd38a45ceec49e0a7874cb91dfb4666", "Skald Legacy - Silver Tongue", "스칼드 전승: 달변가", false);
      KoreanLocalization.Add("df17d9f5cf3a4299b8dc45d897aa38b2", "You had a hidden passion for karaoke and were devastated seeing that no such thing exist in Golarion. \nAs an ever - ready person you decide to train nonetheless since killing demonic armies only with your voice would show your talent to the entire world.", "당신은 남몰래 노래방을 사랑했기에, 골라리온에는 그런 것이 없다는 사실에 절망했습니다.\n하지만 언제나 준비된 사람이니 수련을 계속하기로 합니다. 목소리만으로 데몬 군단을 쓰러뜨리면 온 세상이 당신의 재능을 알게 될 테니까요.", true);
      KoreanLocalization.Add("10399a204bdd485c9cc0bcb938ef3631", "Skald Legacy - The Voice", "스칼드 전승: 목소리의 대가", false);
      KoreanLocalization.Add("179df3b73b2b458cbe00aea01c998442", "You gain immunity to sleep.", "수면에 면역이 됩니다.", true);
      KoreanLocalization.Add("b1f4c832800d4be3971f2f22c2a936c8", "Sleep Immunity", "수면 면역", false);
      KoreanLocalization.Add("fb36580a1dfb406486f7278efe62f1cf", "You gain immunity to slow.", "감속에 면역이 됩니다.", true);
      KoreanLocalization.Add("c428a93ee72b4b7bbf48ffa406b798f8", "Slow Immunity", "감속 면역", false);
      KoreanLocalization.Add("d87b91e6d8164f83ba55516e43f8a3e8", "You gain immunity to sneak attacks.", "암습에 면역이 됩니다.", true);
      KoreanLocalization.Add("ebffd5f9ffab4ddbb156f1a830dd9b37", "Sneak attack Immunity", "암습 면역", false);
      KoreanLocalization.Add("351f10ce92c54edabcb7bf02b417519f", "You can add your sneak {g|Encyclopedia:Attack}attack{/g} {g|Encyclopedia:Damage}damage{/g} to any {g|Encyclopedia:Spell}spell{/g} that deals damage, if the targets are {g|Encyclopedia:Flat_Footed}flat-footed{/g}. This additional damage only applies to spells that deal hit point damage, and the additional damage is of the same type as the spell. If the spell allows a {g|Encyclopedia:Saving_Throw}saving throw{/g} to negate or halve the damage, it also negates or halves the sneak attack damage.", "대상이 {g|Encyclopedia:Flat_Footed}무방비{/g} 상태라면, 피해를 입히는 모든 {g|Encyclopedia:Spell}주문{/g}에 {g|Encyclopedia:Attack}암습{/g} {g|Encyclopedia:Damage}피해{/g}를 더할 수 있습니다. 생명력 피해를 입히는 주문에만 적용되며, 추가 피해의 유형은 해당 주문과 같습니다. 주문이 {g|Encyclopedia:Saving_Throw}내성 굴림{/g}으로 피해를 무효화하거나 절반으로 줄일 수 있다면, 암습 피해도 함께 무효화되거나 절반으로 줄어듭니다.", true);
      KoreanLocalization.Add("ca33c9f1578f4531b7f1450f67f417d0", "Sneaky Magic", "은밀한 마법", false);
      KoreanLocalization.Add("5503b72f92df4051a65a9626537a985e", "You gain immunity to Sonic.", "음파에 면역이 됩니다.", true);
      KoreanLocalization.Add("7d4ef708f63141709c73a14c881ab08c", "Sonic Immunity", "음파 면역", false);
      KoreanLocalization.Add("e8a65301807a48d68949c5fbdba8ed0d", "Their otherworldly knowledge and point of view allow Chimeras to imbue themselves with different bloodlines in order to gain power and strength. \nChimeras are constantly seeking out new sources of power, and their ability to absorb and incorporate these different bloodlines allows them to become truly formidable foes. \nHowever, their constant experimentation with bloodlines can also lead to confusion and uncertainty about their own heritage and identity, as their original ancestry becomes harder to discern over time.\n\nPlease note that you do not get previous Bloodline Evolutions when picking this legacy at higher levels.", "키메라는 이세계의 지식과 관점을 활용해 여러 혈통을 몸에 받아들여 힘을 얻습니다.\n끊임없이 새로운 힘의 근원을 찾으며, 서로 다른 혈통을 흡수하고 융합하여 무시무시한 적수가 됩니다.\n하지만 혈통 실험을 거듭할수록 본래의 조상을 분간하기 어려워져, 자신의 출신과 정체성에 혼란을 겪기도 합니다.\n\n높은 레벨에서 이 전승을 선택해도 이전 레벨의 혈통 진화를 소급해서 얻지는 않습니다.", true);
      KoreanLocalization.Add("44180ad457ed4dbfa971177a0575df7b", "Sorcerer Legacy - Chimera", "소서러 전승: 키메라", false);
      KoreanLocalization.Add("e24f06a85f0a4302af8dde12715799ba", "You use your mythic powers to gain an additional special power.\nSource: Isekai Mod", "신화의 힘으로 특수 능력을 하나 더 얻습니다.\n출처: 이세계 모드", true);
      KoreanLocalization.Add("1df4a2bfaedf43e6bbf0241e7f9d287d", "Mythic Special Power", "신화 특수 능력", false);
      KoreanLocalization.Add("d95c9ffd44fc434d9ae1074c9a55f570", "As you increase your level, you gain special powers that allow you to wreck your enemies more easily.", "레벨이 오르면 적을 더욱 손쉽게 제압할 수 있는 특수 능력을 얻습니다.", true);
      KoreanLocalization.Add("bbe1221b067749e8972aee78c53b3696", "Special Power", "특수 능력", false);
      KoreanLocalization.Add("1344075d2d81414ab90f301dd76471b7", "The DC of spells you cast increases by 4.", "자신이 시전하는 주문의 난이도가 4 증가합니다.", true);
