      KoreanLocalization.Add("c3e8fd9198b04f8697bf0547b8a5fc30", "You gain spell resistance equal to 10 + twice your character level.", "10 + 캐릭터 레벨의 2배만큼 주문 저항을 얻습니다.", false);
      KoreanLocalization.Add("c5a596ed43184f76878df7158ef3ff3e", "Spell Negation", "주문 무효화", false);
      KoreanLocalization.Add("c9b8e269945045f797f5cda5a9e2e659", "You gain immunity to the staggered condition.", "비틀거림에 면역이 됩니다.", true);
