      KoreanLocalization.Add("90eeaf63676b4743a0450c73b736819b", "At 1st level, you get to select a starting weapon. The weapon can be found in the Kenarbes festival chest.", "1레벨에 시작 무기를 하나 선택합니다. 선택한 무기는 케나브레스 축제의 상자에서 얻을 수 있습니다.", true);
      KoreanLocalization.Add("255eb7310af84d61bc42a8209e017eee", "Starting Weapon", "시작 무기", false);
      KoreanLocalization.Add("161bc0e8910b42ffbfebfc517aaa84bc", "You start with a shortbow.", "단궁을 시작 무기로 얻습니다.", true);
      KoreanLocalization.Add("36ba0d0f51844b5bad6d694c26007496", "You start with a cold iron shortspear.", "한철 단창을 시작 무기로 얻습니다.", true);
      KoreanLocalization.Add("89084f4f5610453e974e808ab81f94b5", "You start with a cold iron shortsword.", "한철 소검을 시작 무기로 얻습니다.", true);
      KoreanLocalization.Add("c5505a61e80b43d9bda5c41ef31d9322", "You start with a cold iron sickle.", "한철 낫을 시작 무기로 얻습니다.", true);
      KoreanLocalization.Add("5d4c20f022b444d2960f542b968cb8fe", "You start with a cold iron spear.", "한철 창을 시작 무기로 얻습니다.", true);
      KoreanLocalization.Add("a2ffa313e8a640048457112b2ff5d2e8", "You start with a cold iron starknife.", "한철 스타나이프를 시작 무기로 얻습니다.", true);
      KoreanLocalization.Add("761413db67c24ea593d6185525395e53", "You start with a cold iron throwing axe.", "한철 투척 도끼를 시작 무기로 얻습니다.", true);
      KoreanLocalization.Add("15683bc5fade47b7910738c8f451e13f", "You start with a cold iron tongi.", "한철 통기를 시작 무기로 얻습니다.", true);
      KoreanLocalization.Add("79837401ca2e448d8b956243866a4474", "You start with a cold iron trident.", "한철 삼지창을 시작 무기로 얻습니다.", true);
      KoreanLocalization.Add("ef38798166594898a6445caa24db43df", "You start with a cold iron urgrosh.", "한철 우르그로쉬를 시작 무기로 얻습니다.", true);
      KoreanLocalization.Add("6d54b69e7b274ebfb93b397e185ac29b", "You start with a cold iron warhammer.", "한철 전투망치를 시작 무기로 얻습니다.", true);
      KoreanLocalization.Add("9c54807f93274ebdba0e3886c2e615eb", "You gain immunity to ability score damage and negative levels.", "능력치 피해와 음수 레벨에 면역이 됩니다.", true);
      KoreanLocalization.Add("d85a5dfefbec42079994794063317ec2", "Energy Drain and Negative level Immunity", "능력치 피해 및 음수 레벨 면역", false);
      KoreanLocalization.Add("394ac8f35f47442c894e9fa05b04b378", "You gain immunity to stun effects.", "기절에 면역이 됩니다.", true);
      KoreanLocalization.Add("507d47b1d63d4f829d95466850a9ebd5", "Stun Immunity", "기절 면역", false);
      KoreanLocalization.Add("46ef19a51f52456fa78a4542c42fd67a", "You can make any creature fight on your side as if it was your ally. It will {g|Encyclopedia:Attack}attack{/g} your opponents to the best of its ability. However this creature will try to throw off the domination effect, making a {g|Encyclopedia:Saving_Throw}Will save{/g} each {g|Encyclopedia:Combat_Round}round{/g}.", "크리처를 아군처럼 당신 편에서 싸우게 합니다. 대상은 당신의 적을 최선을 다해 {g|Encyclopedia:Attack}공격{/g}합니다. 다만 지배에서 벗어나려 하므로, 매 {g|Encyclopedia:Combat_Round}라운드{/g} {g|Encyclopedia:Saving_Throw}의지 내성{/g}을 시도합니다.", true);
      KoreanLocalization.Add("bb4fabe87e594d3fae8e8958ceb2828e", "Succubus Charm", "서큐버스의 매혹", false);
      KoreanLocalization.Add("b07c082662b549d09c068b12b73a677c", "This {g|Encyclopedia:Spell}spell{/g} summons Areshkagal. Summoned monsters appear where you designate and act according to their {g|Encyclopedia:Initiative}initiative{/g} {g|Encyclopedia:Check}check{/g} results. They {g|Encyclopedia:Attack}attack{/g} your opponents to the best of their ability.", "이 {g|Encyclopedia:Spell}주문{/g}은 아레쉬카갈을 소환합니다. 소환된 크리처는 지정한 위치에 나타나 {g|Encyclopedia:Initiative}우선권{/g} {g|Encyclopedia:Check}판정{/g} 결과에 따라 행동합니다. 크리처는 당신의 적을 최선을 다해 {g|Encyclopedia:Attack}공격{/g}합니다.", true);
      KoreanLocalization.Add("40a6fcff01c246f29980f46123e88e35", "Overpowered Ability — Summon Calamity (Areshkagal)", "초월 능력: 재앙 소환 (아레쉬카갈)", false);
      KoreanLocalization.Add("834dd3939da543acae355a006f83cf09", "This {g|Encyclopedia:Spell}spell{/g} summons Demon Lord Baphomet. Summoned monsters appear where you designate and act according to their {g|Encyclopedia:Initiative}initiative{/g} {g|Encyclopedia:Check}check{/g} results. They {g|Encyclopedia:Attack}attack{/g} your opponents to the best of their ability.", "이 {g|Encyclopedia:Spell}주문{/g}은 데몬 군주 바포메트를 소환합니다. 소환된 크리처는 지정한 위치에 나타나 {g|Encyclopedia:Initiative}우선권{/g} {g|Encyclopedia:Check}판정{/g} 결과에 따라 행동합니다. 크리처는 당신의 적을 최선을 다해 {g|Encyclopedia:Attack}공격{/g}합니다.", true);
      KoreanLocalization.Add("59b1acf5b8b74cdcb750c787ac3afe82", "Overpowered Ability — Summon Calamity (Baphomet)", "초월 능력: 재앙 소환 (바포메트)", false);
      KoreanLocalization.Add("30867279d178412ab0f8492d2ebdbe08", "This {g|Encyclopedia:Spell}spell{/g} summons a Hydra, an Owlbear, a Roc, or a Minotaur. Summoned monsters appear where you designate and act according to their {g|Encyclopedia:Initiative}initiative{/g} {g|Encyclopedia:Check}check{/g} results. They {g|Encyclopedia:Attack}attack{/g} your opponents to the best of their ability.", "이 {g|Encyclopedia:Spell}주문{/g}은 히드라, 아울베어, 로크 또는 미노타우로스를 소환합니다. 소환된 크리처는 지정한 위치에 나타나 {g|Encyclopedia:Initiative}우선권{/g} {g|Encyclopedia:Check}판정{/g} 결과에 따라 행동합니다. 크리처는 당신의 적을 최선을 다해 {g|Encyclopedia:Attack}공격{/g}합니다.", true);
      KoreanLocalization.Add("f1416e65e2664e11a3aa433e54fad0be", "Summon Beast", "야수 소환", false);
      KoreanLocalization.Add("c5074dd162644cf39119970008a01ad2", "As a full action, you summon a Hydra, an Owlbear, a Roc, or a Minotaur.", "전 라운드 행동으로 히드라, 아울베어, 로크 또는 미노타우로스를 소환합니다.", true);
      KoreanLocalization.Add("162050b5fea44f44a2a2ce6ca997e8ac", "This {g|Encyclopedia:Spell}spell{/g} summons a Devastator, Playful Darkness, Baphomet, Deskari, Nocticula, Mephistopheles, or Areshkagal. Summoned monsters appear where you designate and act according to their {g|Encyclopedia:Initiative}initiative{/g} {g|Encyclopedia:Check}check{/g} results. They {g|Encyclopedia:Attack}attack{/g} your opponents to the best of their ability.", "이 {g|Encyclopedia:Spell}주문{/g}은 멸절자, 장난스러운 어둠, 바포메트, 데스카리, 녹티큘라, 메피스토펠레스 또는 아레쉬카갈을 소환합니다. 소환된 크리처는 지정한 위치에 나타나 {g|Encyclopedia:Initiative}우선권{/g} {g|Encyclopedia:Check}판정{/g} 결과에 따라 행동합니다. 크리처는 당신의 적을 최선을 다해 {g|Encyclopedia:Attack}공격{/g}합니다.", true);
      KoreanLocalization.Add("631035bcd8f645fd9e929ee243511e1d", "Overpowered Ability — Summon Calamity", "초월 능력: 재앙 소환", false);
      KoreanLocalization.Add("1796b905908140089da1652b14dff73c", "There is nothing you cannot summon. Your calls are heeded; your commands are absolute. Even demon lords show no negligence... and tremblingly obey.\nBenefit: As a full action, you summon a powerful being to bring calamity. You can summon one of the following: Devastator, Playful Darkness, Baphomet, Deskari, Nocticula, Mephistopheles, or Areshkagal.", "당신이 소환하지 못할 존재는 없습니다. 부름은 언제나 응답받고, 명령은 절대적입니다. 데몬 군주조차 감히 소홀히 여기지 못하고… 떨면서 복종합니다.\n효과: 전 라운드 행동으로 강력한 존재를 불러 재앙을 내립니다. 멸절자, 장난스러운 어둠, 바포메트, 데스카리, 녹티큘라, 메피스토펠레스, 아레쉬카갈 중 하나를 소환할 수 있습니다.", true);
      KoreanLocalization.Add("d2737c831c9f466d975b1e3e0dfce1fe", "This {g|Encyclopedia:Spell}spell{/g} summons Demon Lord Deskari. Summoned monsters appear where you designate and act according to their {g|Encyclopedia:Initiative}initiative{/g} {g|Encyclopedia:Check}check{/g} results. They {g|Encyclopedia:Attack}attack{/g} your opponents to the best of their ability.", "이 {g|Encyclopedia:Spell}주문{/g}은 데몬 군주 데스카리를 소환합니다. 소환된 크리처는 지정한 위치에 나타나 {g|Encyclopedia:Initiative}우선권{/g} {g|Encyclopedia:Check}판정{/g} 결과에 따라 행동합니다. 크리처는 당신의 적을 최선을 다해 {g|Encyclopedia:Attack}공격{/g}합니다.", true);
      KoreanLocalization.Add("00ffa9a1fded43338b71134a783ed537", "Overpowered Ability — Summon Calamity (Deskari)", "초월 능력: 재앙 소환 (데스카리)", false);
      KoreanLocalization.Add("dcf0780227824692bc0788752ec2a894", "This {g|Encyclopedia:Spell}spell{/g} summons Archdevil Mephistopheles. Summoned monsters appear where you designate and act according to their {g|Encyclopedia:Initiative}initiative{/g} {g|Encyclopedia:Check}check{/g} results. They {g|Encyclopedia:Attack}attack{/g} your opponents to the best of their ability.", "이 {g|Encyclopedia:Spell}주문{/g}은 대악마 메피스토펠레스를 소환합니다. 소환된 크리처는 지정한 위치에 나타나 {g|Encyclopedia:Initiative}우선권{/g} {g|Encyclopedia:Check}판정{/g} 결과에 따라 행동합니다. 크리처는 당신의 적을 최선을 다해 {g|Encyclopedia:Attack}공격{/g}합니다.", true);
      KoreanLocalization.Add("9d49a3bb5d69472eb83310b3c52feb0e", "Overpowered Ability — Summon Calamity (Mephistopheles)", "초월 능력: 재앙 소환 (메피스토펠레스)", false);
      KoreanLocalization.Add("033d944fa23646d6ad6152ee901d4979", "This {g|Encyclopedia:Spell}spell{/g} summons Demon Lord Nocticula. Summoned monsters appear where you designate and act according to their {g|Encyclopedia:Initiative}initiative{/g} {g|Encyclopedia:Check}check{/g} results. They {g|Encyclopedia:Attack}attack{/g} your opponents to the best of their ability.", "이 {g|Encyclopedia:Spell}주문{/g}은 데몬 군주 녹티큘라를 소환합니다. 소환된 크리처는 지정한 위치에 나타나 {g|Encyclopedia:Initiative}우선권{/g} {g|Encyclopedia:Check}판정{/g} 결과에 따라 행동합니다. 크리처는 당신의 적을 최선을 다해 {g|Encyclopedia:Attack}공격{/g}합니다.", true);
      KoreanLocalization.Add("c8da36df9e6348d29c5e7e72b1016571", "Overpowered Ability — Summon Calamity (Nocticula)", "초월 능력: 재앙 소환 (녹티큘라)", false);
      KoreanLocalization.Add("d6d49f8e492143fdb78d861bf3eb9abf", "This {g|Encyclopedia:Spell}spell{/g} summons a Devastator. Summoned monsters appear where you designate and act according to their {g|Encyclopedia:Initiative}initiative{/g} {g|Encyclopedia:Check}check{/g} results. They {g|Encyclopedia:Attack}attack{/g} your opponents to the best of their ability.", "이 {g|Encyclopedia:Spell}주문{/g}은 멸절자를 소환합니다. 소환된 크리처는 지정한 위치에 나타나 {g|Encyclopedia:Initiative}우선권{/g} {g|Encyclopedia:Check}판정{/g} 결과에 따라 행동합니다. 크리처는 당신의 적을 최선을 다해 {g|Encyclopedia:Attack}공격{/g}합니다.", true);
      KoreanLocalization.Add("6f322f33bebb4941aaabb6a2458a2640", "Overpowered Ability — Summon Calamity (Devastator)", "초월 능력: 재앙 소환 (멸절자)", false);
      KoreanLocalization.Add(null, "Summon Exalted Choir", "고귀한 합창단 소환", false);
      KoreanLocalization.Add(null, "Exalted Choir", "고귀한 합창단", false);
      KoreanLocalization.Add(null, "As a full action, you summon a Succubus, an Astral Deva, and an Erinyes to aid you in battle.", "전 라운드 행동으로 서큐버스, 아스트랄 데바, 에리니에스를 하나씩 소환하여 전투를 돕게 합니다.", true);
      KoreanLocalization.Add("ea458f3129b041be894391ae843a202c", "This {g|Encyclopedia:Spell}spell{/g} summons a Succubus, Nymph, Astral Deva, and an Erinyes. Summoned monsters appear where you designate and act according to their {g|Encyclopedia:Initiative}initiative{/g} {g|Encyclopedia:Check}check{/g} results. They {g|Encyclopedia:Attack}attack{/g} your opponents to the best of their ability.", "이 {g|Encyclopedia:Spell}주문{/g}은 서큐버스, 아스트랄 데바, 에리니에스를 하나씩 소환합니다. 소환된 크리처는 지정한 위치에 나타나 {g|Encyclopedia:Initiative}우선권{/g} {g|Encyclopedia:Check}판정{/g} 결과에 따라 행동합니다. 크리처는 당신의 적을 최선을 다해 {g|Encyclopedia:Attack}공격{/g}합니다.", true);
      KoreanLocalization.Add("89e6ea980ec34fc8b5297131b7cbc9bf", "This {g|Encyclopedia:Spell}spell{/g} summons a Hydra. Summoned monsters appear where you designate and act according to their {g|Encyclopedia:Initiative}initiative{/g} {g|Encyclopedia:Check}check{/g} results. They {g|Encyclopedia:Attack}attack{/g} your opponents to the best of their ability.", "이 {g|Encyclopedia:Spell}주문{/g}은 히드라를 소환합니다. 소환된 크리처는 지정한 위치에 나타나 {g|Encyclopedia:Initiative}우선권{/g} {g|Encyclopedia:Check}판정{/g} 결과에 따라 행동합니다. 크리처는 당신의 적을 최선을 다해 {g|Encyclopedia:Attack}공격{/g}합니다.", true);
      KoreanLocalization.Add("14ae4f75e71b4f3b9f4e9b65d3ea7021", "Summon Beast (Hydra)", "야수 소환 (히드라)", false);
      KoreanLocalization.Add("9a0b73c6fee34cb29ae62d06e11b5541", "This {g|Encyclopedia:Spell}spell{/g} summons a Minotaur.  Summoned monsters appear where you designate and act according to their {g|Encyclopedia:Initiative}initiative{/g} {g|Encyclopedia:Check}check{/g} results. They {g|Encyclopedia:Attack}attack{/g} your opponents to the best of their ability.", "이 {g|Encyclopedia:Spell}주문{/g}은 미노타우로스를 소환합니다. 소환된 크리처는 지정한 위치에 나타나 {g|Encyclopedia:Initiative}우선권{/g} {g|Encyclopedia:Check}판정{/g} 결과에 따라 행동합니다. 크리처는 당신의 적을 최선을 다해 {g|Encyclopedia:Attack}공격{/g}합니다.", true);
      KoreanLocalization.Add("34753a83406f4286a2d8aee2f06ff075", "Summon Beast (Minotaur)", "야수 소환 (미노타우로스)", false);
      KoreanLocalization.Add("999c5b8b35284cf0949ab4de6b6e4626", "This {g|Encyclopedia:Spell}spell{/g} summons an Owlbear. Summoned monsters appear where you designate and act according to their {g|Encyclopedia:Initiative}initiative{/g} {g|Encyclopedia:Check}check{/g} results. They {g|Encyclopedia:Attack}attack{/g} your opponents to the best of their ability.", "이 {g|Encyclopedia:Spell}주문{/g}은 아울베어를 소환합니다. 소환된 크리처는 지정한 위치에 나타나 {g|Encyclopedia:Initiative}우선권{/g} {g|Encyclopedia:Check}판정{/g} 결과에 따라 행동합니다. 크리처는 당신의 적을 최선을 다해 {g|Encyclopedia:Attack}공격{/g}합니다.", true);
      KoreanLocalization.Add("2bd855c7da2447beac2c435a70b8a622", "Summon Beast (Owlbear)", "야수 소환 (아울베어)", false);
      KoreanLocalization.Add("9296a015a66a4bc19d5700b6c6b1bf88", "This {g|Encyclopedia:Spell}spell{/g} summons Playful Darkness. Summoned monsters appear where you designate and act according to their {g|Encyclopedia:Initiative}initiative{/g} {g|Encyclopedia:Check}check{/g} results. They {g|Encyclopedia:Attack}attack{/g} your opponents to the best of their ability.", "이 {g|Encyclopedia:Spell}주문{/g}은 장난스러운 어둠을 소환합니다. 소환된 크리처는 지정한 위치에 나타나 {g|Encyclopedia:Initiative}우선권{/g} {g|Encyclopedia:Check}판정{/g} 결과에 따라 행동합니다. 크리처는 당신의 적을 최선을 다해 {g|Encyclopedia:Attack}공격{/g}합니다.", true);
      KoreanLocalization.Add("0ed5dec4c18646129937367a4a606860", "Overpowered Ability — Summon Calamity (Playful Darkness)", "초월 능력: 재앙 소환 (장난스러운 어둠)", false);
      KoreanLocalization.Add("fee9e445eeaf42b09fac04c8f08771d3", "This {g|Encyclopedia:Spell}spell{/g} summons a Roc.  Summoned monsters appear where you designate and act according to their {g|Encyclopedia:Initiative}initiative{/g} {g|Encyclopedia:Check}check{/g} results. They {g|Encyclopedia:Attack}attack{/g} your opponents to the best of their ability.", "이 {g|Encyclopedia:Spell}주문{/g}은 로크를 소환합니다. 소환된 크리처는 지정한 위치에 나타나 {g|Encyclopedia:Initiative}우선권{/g} {g|Encyclopedia:Check}판정{/g} 결과에 따라 행동합니다. 크리처는 당신의 적을 최선을 다해 {g|Encyclopedia:Attack}공격{/g}합니다.", true);
      KoreanLocalization.Add("5b452f814b4c46d7ad32f7ce9e163544", "Summon Beast (Roc)", "야수 소환 (로크)", false);
      KoreanLocalization.Add("620cfd50fbed49df94b21c720ea08f67", "You are able to buff you and your allies with the following effects for 24 hours: resist energy, protection from energy, protection from arrows, haste, mage armor, shield, shield of faith, veil of heaven, veil of positive energy, blur, bull's strength, cat's grace, bear's endurance, fox's cunning, owl's wisdom, eagle's splendor, mirror image, false life, barkskin, aid, protection from evil, bestow grace, aura of greater courage, displacement, magical vestiment, delay poison, invisibility greater, stone skin, death ward, freedom of movement, false life greater, burst of glory, spell resistance, eagle soul, legendary proportions, frightful aspect, seamantle, foresight, unbreakable heart, remove fear, divine favor, magic fang, align weapon good, crusaders edge, magic weapon greater, divine power, true seeing, shield of law, angelic aspect greater, winds of vengeance, hurricane bow, sense vitals, heroism greater, echolocation, life bubble, protection from spells, mind blank, and heroic invocation.", "자신과 60피트 이내 아군에게 다음 효과를 24시간 동안 부여합니다: 에너지 저항; 에너지로부터 보호; 화살로부터 보호; 가속; 마법사의 갑옷; 방패; 신념의 방패; 천상의 장막; 양에너지의 장막; 흐릿한 형체; 황소의 힘; 고양이의 우아함; 곰의 지구력; 여우의 교활함; 올빼미의 지혜; 독수리의 위엄; 거울상; 거짓 생명; 나무껍질; 지원; 악으로부터 보호; 은총 부여; 상급 용기의 오라; 환위; 마법의 예복; 독 지연; 돌가죽; 죽음 방호; 이동의 자유; 거짓 생명, 상급; 피어나는 영광; 주문 저항; 독수리의 혼; 전설적인 크기; 무시무시한 형상; 바다의 망토; 미래시; 꺾이지 않는 마음; 공포 제거; 신성한 은혜; 마법 송곳니; 성향 무기 (선); 성전사의 칼날; 상급 마법 무기; 신성한 힘; 진실의 시야; 질서의 방패; 엔젤의 형상, 상급; 복수의 돌풍; 태풍의 활; 급소 감지; 영웅심, 상급; 반향; 생명 거품; 주문으로부터 보호; 정신 비우기; 영웅심 강신.", false);
      KoreanLocalization.Add("325af03e38894392aee2b260f92c2a9c", "Overpowered Ability — Super Buff", "초월 능력: 궁극의 강화", false);
      KoreanLocalization.Add("5ee8a59bfbec4913b3bf6a005043a5a0", "You dispell all buffs from you and your allies.", "자신과 60피트 이내 아군에게 자신이 부여한 궁극의 강화 효과를 해제합니다.", true);
      KoreanLocalization.Add("52b7b55bca9d4ef2be71149f17bbc8ff", "Dismiss Super Buff", "궁극의 강화 해제", false);
      KoreanLocalization.Add("19c415fda5a1487c95bc48f038179d62", "You gain a size bonus to HP equal to your 10 times your Constitution modifier.", "생명력에 건강 수정치의 10배만큼 크기 보너스를 받습니다.", true);
      KoreanLocalization.Add("8745afb1661b40659050abcfd6b10179", "Supermassive", "초거대", false);
      KoreanLocalization.Add("e9d1e7723f3e4a9fa7fd50026a809416", "The Edge Lord uses their Dexterity modifier for their melee attack and damage bonus instead of Strength. In addition, they may use their Dexterity in place of their Strength for CMB and to qualify for any feat for which it is a prerequisite.", "중2병 군주는 근접 명중과 피해 보너스에 힘 대신 민첩 수정치를 사용합니다. 전법 보너스(CMB)와 힘을 선행 조건으로 요구하는 특기를 습득할 때에도 힘 대신 민첩을 사용할 수 있습니다.", true);
      KoreanLocalization.Add("eeabc67c632541ed87474df9670b375f", "Supersonic Combat", "초음속 전투", false);
      KoreanLocalization.Add("2a96478b85b64313a7d2b549acf9081e", "You have transcended mortal limitations, achieving perfection in body and mind. \nBenefit: Gain an initial +5 bonus to all attributes. Additionally, gain +1 to all attributes for every 2 character levels and +1 for every mythic rank.", "필멸자의 한계를 넘어, 육체와 정신이 완전한 경지에 이르렀습니다.\n효과: 모든 능력치에 기본 +5 보너스를 받습니다. 능력이 활성화될 때 캐릭터 레벨 2당 +1, 신화 등급당 +1의 추가 보너스가 적용됩니다.", true);
      KoreanLocalization.Add("ce735fa2327b43cd9834013770df27a6", "Overpowered Ability — Supreme Being", "초월 능력: 지고의 존재", false);
      KoreanLocalization.Add("ac1c6a7302bd415a970119febba3b864", "You gain immunity to stunned, staggered, slowed, entangled, petrified, paralysis, and movement impairing effects.", "기절, 비틀거림, 감속, 얽힘, 석화, 마비와 이동 방해 효과에 면역이 됩니다.", true);
      KoreanLocalization.Add("eade74bbdac54e04a7628f8d2a909667", "Tenacious", "불굴의 의지", false);
      KoreanLocalization.Add("c11568f5565d4e0398f4d7700c057072", "Underpowered Ability — Thought Master", "하위 능력: 사유의 달인", false);
      KoreanLocalization.Add("c0566073da7846ddbd789e7af76d8191", "Your attacks have Thundering. They deal an additional 1d6 sonic damage.", "당신의 공격에 천둥 효과가 적용되어 1d6의 추가 음파 피해를 입힙니다.", false);
      KoreanLocalization.Add("04aa72b0be704c8da637b6345c80c12b", "Thundering Weapon", "천둥 무기", false);
      KoreanLocalization.Add("3e4f959f901f4c858c3191e7a141d8b3", "At 12th level, you and your companions take a short intermission beside a large body of water. During this time, you begin a journey of self discovery.", "12레벨에 당신과 동료들은 넓은 물가에서 잠시 쉬어 갑니다. 이 시간을 통해 자신을 알아 가는 여정을 시작합니다.", false);
      KoreanLocalization.Add("bc35fea7823c40c1b5d5cf25e1e676a7", "Another Training Episode", "추가 수련 에피소드", false);
      KoreanLocalization.Add("6e0460bebd344e4e8f11e3873ff1d02b", "Training Episode", "수련 에피소드", false);
      KoreanLocalization.Add(null, "Through relentless training and an unwavering desire to better yourself, you gain a +2 bonus to all attributes at level 1, increasing by +1 every 4 levels (to a maximum of +8 at level 20).", "끊임없는 수련과 더 나아지고자 하는 열망이 당신을 강화합니다.\n모든 능력치에 기본 +2 보너스를 받습니다. 능력이 활성화될 때, 캐릭터 레벨을 4로 나눈 몫에 2를 더한 값(최대 8)만큼 추가 보너스가 적용됩니다. 두 보너스의 합은 1레벨에 +4, 20레벨에 +9입니다.", true);
      KoreanLocalization.Add("5bb32ec387f34b21b59d5b43de7f87e3", "Training Montage", "수련 몽타주", false);
      KoreanLocalization.Add("03bcf7439eef480f9571a4daf13c3cae", "Gain the spells of a Trickster.", "트릭스터의 주문을 얻습니다.", true);
      KoreanLocalization.Add("a4313cd9b2b7414786fa8b503b58ba98", "Mythic Trickster Spells", "신화 트릭스터 주문", false);
      KoreanLocalization.Add(null, "Truck-kun is a menace of the streets, a killer that prowls the road before it smashes their victim so hard they get transported into another world. Many fear death brought by Truck-kun, but there are some who believe that their reincarnation will bring them into a new world. Beware of the streets, and look at both sides of the road, or else you might be its latest victim.\nDomains: Artifice, Destruction, Repose, Travel\nFavoured Weapon: Heavy Shield Bash", "트럭 군은 도로를 배회하는 살인자이자 거리의 공포입니다. 희생자를 너무 세게 들이받는 바람에 다른 세계로 보내 버리지요. 많은 이가 트럭 군에게 죽임당하는 것을 두려워하지만, 환생하면 새로운 세계가 기다릴 것이라 믿는 이들도 있습니다. 길에서는 조심하고, 건너기 전에 양쪽을 살피세요. 그렇지 않으면 다음 희생자는 당신일지도 모릅니다.\n영역: 제작, 파괴, 안식, 여행\n선호 무기: 중형 방패 치기", true);
      KoreanLocalization.Add("d0a0b97de49f465ab866a43800ca2fac", "Truck-kun", "트럭 군", false);
      KoreanLocalization.Add("21c3c38b2a304bf7999efb502ad82b95", "Restore life and complete {g|Encyclopedia:Strength}strength{/g} to any deceased creature. Upon completion of this ability, the creature is immediately restored to full {g|Encyclopedia:HP}hit points{/g}, vigor, and {g|Encyclopedia:Healing}health{/g}, with no loss of prepared spells.\nThis ability does not require diamonds.", "죽은 크리처에게 생명과 온전한 {g|Encyclopedia:Strength}활력{/g}을 되돌려 줍니다. 능력이 완성되면 대상은 즉시 최대 {g|Encyclopedia:HP}생명력{/g}과 {g|Encyclopedia:Healing}건강{/g}, 활력을 되찾으며, 준비한 주문도 잃지 않습니다.\n다이아몬드가 필요하지 않습니다.", false);
      KoreanLocalization.Add("f90c600a310541ac88749b91a9ffbc2a", "Overpowered Ability — True Resurrection", "초월 능력: 진정한 부활", false);
      KoreanLocalization.Add(null, "Blessed by the winds of fate in your new life, you can effortlessly dodge even the most well-aimed strikes.\nBenefit: You gain a +4 dodge bonus to AC and can move freely without provoking attacks of opportunity.", "새 삶에서 운명의 바람이 당신을 축복합니다. 아무리 정교한 일격도 손쉽게 피합니다.\n효과: 방어도에 +4 회피 보너스를 받습니다.", true);
      KoreanLocalization.Add(null, "Underpowered Ability — Super Strength", "하위 능력: 초인적인 힘", false);
      KoreanLocalization.Add(null, "Infused with the strength of a titan, your physical might is a testament to your rebirth in this new world.\nBenefit: You gain +50 hit points and +4 Strength.", "타이탄의 힘이 스며든 육체가 이세계에 다시 태어났음을 증명합니다.\n효과: 생명력에 +50, 힘에 +4 보너스를 받습니다.", true);
      KoreanLocalization.Add(null, "Your newfound mind is a gift from the cosmos, giving you unparalleled clarity and understanding.\nBenefit: You gain a +4 bonus to Intelligence and Wisdom, and a +2 bonus to Knowledge (Arcana), Knowledge (World), and Perception checks.", "새롭게 얻은 정신은 우주의 선물입니다. 비할 데 없는 명료함과 이해력을 얻습니다.\n효과: 지능과 지혜에 +4 보너스를, 지식 (비전), 지식 (세계), 지각 판정에 +2 능숙 보너스를 받습니다.", true);
      KoreanLocalization.Add(null, "Even in this new world, you prefer to keep things simple. These humble abilities reflect your decision to avoid overwhelming power in favor of a quiet, comfortable life.", "이세계에서도 당신은 소박한 삶을 원합니다. 압도적인 힘 대신 조용하고 편안한 일상을 택한 당신에게 어울리는, 작고 수수한 능력들입니다.", true);
      KoreanLocalization.Add("51d13ea9780040789a7b9a79d877b0d7", "Underpowered Ability", "하위 능력", false);
      KoreanLocalization.Add("cb8c0cffaeb445fa9766226c6ce54bc8", "The damage you deal is now unholy damage.", "당신이 입히는 피해가 불경 피해로 바뀝니다.", false);
      KoreanLocalization.Add("e41e385ef21b4253916e1e20e43c694c", "Unjust Path", "불의의 길", false);
      KoreanLocalization.Add("cd51eb39413546fbb7b20cf63c006af2", "On the brink of defeat, the enemies have surrounded and exhausted you. Just as they are about to deliver the finishing blow, you get up and say the following words: Not today.\nBenefit: As a standard action, you restore all of your spell slots. You gain an initial 1 use at level 1, scaling to a maximum of 5 uses by level 20 (gaining an additional use every 4 levels).", "패배를 눈앞에 두고, 적에게 포위된 채 힘마저 다했습니다. 적이 마지막 일격을 가하려는 순간, 당신은 다시 일어서며 말합니다. \"오늘은 아니야.\"\n효과: 표준 행동으로 자신의 모든 주문 슬롯을 회복합니다. 사용할 때마다 전용 자원을 1회분 소비하며, 휴식하면 자원이 회복됩니다.", false);
      KoreanLocalization.Add("f161809e34be41d69fead36851be775a", "Overpowered Ability — Unlimited Power", "초월 능력: 무한한 힘", false);
      KoreanLocalization.Add("3ed3ac8133144a7a80cda13944fbeb0c", "Enemies you attack are treated as flat-footed.", "당신이 공격하는 적을 무방비 상태로 취급합니다.", false);
      KoreanLocalization.Add("0e83f9bddf6c4feca318473110ae0194", "Unreactable", "대응 불가", false);
      KoreanLocalization.Add("65871cd0ca004b709cc5040b442335db", "Allies within 40 feet of you gain a profane bonus to AC and saving throws equal to 1/2 your character level.", "40피트 이내 아군은 방어도와 내성 굴림에 당신의 캐릭터 레벨의 절반만큼 불경 보너스를 받습니다.", false);
      KoreanLocalization.Add("a6f1a55c35204056afeb181954044703", "Void Barrier", "공허의 장벽", false);
      KoreanLocalization.Add("cd90e3c0c45e4977b97ef4763ad39d1f", "This character has a profane bonus to AC and saving throws equal to 1/2 your character level.", "이 캐릭터는 방어도와 내성 굴림에 능력 소유자의 캐릭터 레벨의 절반만큼 불경 보너스를 받습니다.", false);
      KoreanLocalization.Add("f1dc8766a7fd4aa2a6c881c39d8303d0", "You were once an ordinary person in your original world, until you were summoned by a mysterious entity to another world full of magic and monsters. \nThere, you learned how to make pacts with various beings, from spirits and demons to dragons and gods. \nYou use your pacts to gain power, knowledge, and allies in this strange new world. \nBut beware, for every pact has a price, and some beings may not be so willing to cooperate with you.", "당신은 원래 세계에서 평범하게 살다가, 정체불명의 존재에게 소환되어 마법과 괴물이 가득한 세계에 왔습니다.\n그곳에서 영혼과 데몬부터 드래곤과 신에 이르기까지, 다양한 존재와 계약하는 법을 배웠습니다.\n이 낯선 세계에서 계약을 통해 힘과 지식과 동료를 얻습니다.\n하지만 조심하세요. 모든 계약에는 대가가 있고, 모든 존재가 기꺼이 협력해 주는 것은 아닙니다.", true);
      KoreanLocalization.Add("a2310c1b9edf49db956ee79f25104378", "Witch Legacy - Pactmaker", "위치 전승: 계약자", false);
      KoreanLocalization.UIStrings.Add("A booming trade in enchanted Crusader cloaks brought {0} gold into the treasury.", "십자군용 마법 망토 거래가 호황을 누려 금고에 {0}골드가 들어왔습니다.");
      KoreanLocalization.UIStrings.Add("A caravan of rare goods you invested in was destroyed by demon raiders. Your gamble failed.", "희귀 물품을 실은 상단에 투자했지만, 데몬 약탈자들이 상단을 파괴했습니다. 투자가 실패로 끝났습니다.");
      KoreanLocalization.UIStrings.Add("A clever trade route you devised bypassed demon patrols, bringing {0} gold into your coffers.", "기발한 교역로를 개척해 데몬 순찰대를 피하고, 금고에 {0}골드를 들였습니다.");
      KoreanLocalization.UIStrings.Add("A large-scale operation to reclaim a demon-infested mine yielded {0} gold in rare minerals.", "데몬이 들끓는 광산을 대대적으로 탈환해, 희귀 광물로 {0}골드를 벌었습니다.");
      KoreanLocalization.UIStrings.Add("A partnership with a city council to rebuild their defenses earned you {0} gold in shared profits.", "도시 의회와 협력해 방어 시설을 재건하고, 수익을 나누어 {0}골드를 벌었습니다.");
      KoreanLocalization.UIStrings.Add("A rival faction sabotaged your plans to monopolize the holy relic market. No gold gained.", "성유물 시장을 독점하려던 계획을 경쟁 세력이 방해했습니다. 골드를 얻지 못했습니다.");
      KoreanLocalization.UIStrings.Add("A small alchemical workshop you funded paid back {0} gold in profits from potion sales.", "자금을 댄 작은 연금술 공방에서 물약 판매 수익으로 {0}골드를 돌려받았습니다.");
      KoreanLocalization.UIStrings.Add("A small-town blacksmith repaid your earlier support with a modest donation of {0} gold.", "작은 마을의 대장장이가 지난번 도움에 보답하며 {0}골드를 기부했습니다.");
      KoreanLocalization.UIStrings.Add("A wealthy benefactor, inspired by your leadership, donated {0} gold to the Crusade.", "당신의 지도력에 감명받은 부유한 후원자가 십자군에 {0}골드를 기부했습니다.");
      KoreanLocalization.UIStrings.Add("A wealthy noble funded your Crusade efforts after you secured their town’s safety, donating {0} gold.", "마을을 안전하게 지켜 준 덕분에 부유한 귀족이 십자군을 후원하며 {0}골드를 기부했습니다.");
      KoreanLocalization.UIStrings.Add("Added Content", "추가 콘텐츠");
      KoreanLocalization.UIStrings.Add("Adds Exceptional feats to feat selection.", "특기 선택 목록에 비범한 특기를 추가합니다.");
      KoreanLocalization.UIStrings.Add("Adds Isekai Backgrounds.", "이세계 배경을 추가합니다.");
      KoreanLocalization.UIStrings.Add("Adds Isekai Gods.", "이세계의 신들을 추가합니다.");
      KoreanLocalization.UIStrings.Add("Adds Isekai Heritages.", "이세계 혈통을 추가합니다.");
      KoreanLocalization.UIStrings.Add("Adds extra dialogue for the Isekai Protagonist.", "이세계 주인공 전용 대사와 선택지를 추가합니다.");
      KoreanLocalization.UIStrings.Add("Adds the Isekai Protagonist class.", "이세계 주인공 클래스를 추가합니다.");
